window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["国家广播电视总局"] = {"zhongwaihezuozhizuodianshijuguanliguidingdebuchong3c668f-2":[],"zhongwaihezuozhizuodianshijuguanliguidingdebuchong3c668f":[],"weixingdianshiguangbodimianjieshousheshiguanliguidcaf52f":[{"i":1,"n":"第一条","txt":"根据国务院颁布的《卫星电视广播地面接收设施管理规定》（以下简称《管理规定》）第十三条规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"广播电影电视部是卫星电视广播地面接收设施（以下简称卫星地面接收设施）的归口管理部门，会同公安部、国家安全部负责全国卫星地面接收设施管理工作。 地方各级广播电视行政部门是当地的卫星地面接收设施的归口管理部门，会同地方各级公安部门和国家安全部门负责本辖区内的卫星地面接收设施的管理工作。 广播电视行政部门的职责是对卫星地面接收设施实行归口管理，审批卫星地面接收设施的设置，组织对卫星地面接收设施的生产、销售、使用情况进行检查；公安部门的职责是查处抗拒、阻碍管理部门依法执行公务的违法行为，协助管理部门对卫星地面接收设施进行技术检查；国家安全部门的职责是检验审核卫星地面接收设施的技术性能，进行技术安全检查，并视需要采取必要的技术防范措施。"},{"i":3,"n":"第三条","txt":"申请设置卫星地面接收设施接收卫星传送的电视节目的单位，应当具备下列条件： （一）有确定的接收方位、接收内容和收视对象范围； （二）有符合国家标准的接收设备； （三）有合格的专职管理人员； （四）有健全的管理制度。"},{"i":4,"n":"第四条","txt":"任何单位均可申请设置卫星地面接收设施接收卫星传送的境内电视节目。 下列单位和场所可申请设置卫星地面接收设施接收卫星传送的境外电视节目： （一）级别较高、规模较大的教育、科研、新闻、金融、经贸等确因业务工作需要的单位； （二）三星级或国家标准二级以上的涉外宾馆； （三）专供外国人和港、澳、台人士办公或居住的公寓等。"},{"i":5,"n":"第五条","txt":"凡需设置卫星地面接收设施接收境内电视节目的单位，必须向当地县级以上（含县级）广播电视行政部门提出申请，报地、市级广播电视行政部门审批。省、自治区、直辖市的直属单位可直接报省、自治区、直辖市广播电视行政部门审批。经审查批准的单位，凭审批机关开具的证明购买卫星地面接收设施。卫星地面接收设施安装完毕，经审批机关检验合格后由其发给《接收卫星传送的境内电视节目许可证》（以下简称《许可证》），并报省、自治区、直辖市广播电视行政部门、国家安全部门备案。此种《许可证》格式由广播电影电视部统一制定，各省、自治区、直辖市自行印制。 设置卫星地面接收设施专门接收卫星传送的境内教育电视节目的各类学校和教育、教学单位，亦按上述程序办理审批手续。经审查批准的，可由当地教育行政部门负责管理，同时接受广播电视行政部门和公安、国家安全部门的检查和管理。 凡需设置卫星地面接收设施接收境外电视节目的单位，必须向当地县级以上"},{"i":6,"n":"第六条","txt":"个人不得安装和使用卫星地面接收设施。 但在收不到当地电视台、电视转播台、电视差转台、有线电视台（站）的电视节目的地区，个人可申请安装卫星地面接收设施接收境内电视节目。 个人需设置卫星地面接收设施的，必须经所在单位同意并持其开具的证明，向当地县级以上（含县级）广播电视行政部门提出申请，经地、市级广播电视行政部门和国家安全部门签署意见后报省、自治区、直辖市广播电视行政部门审批。经审查批准的个人，凭审批机关开具的证明购买卫星地面接收设施。卫星地面接收设施安装完毕，经省、自治区、直辖市广播电视行政部门和国家安全部门检验合格后，由省、自治区、直辖市广播电视行政部门发给《接收卫星传送的境内电视节目许可证》。 个人设置的卫星接收天线不得占用公共场所、影响环境美观和邻里日常生活。"},{"i":7,"n":"第七条","txt":"必要时广播电影电视部可以直接批准设置卫星地面接收设施，并发给相应的《许可证》。"},{"i":8,"n":"第八条","txt":"《管理规定》发布前，单位未经批准已经设置的卫星地面接收设施，不符合前述条款中设置卫星地面接收设施申报条件的，应予拆除。符合前述条款中设置卫星地面接收设施申报条件的，必须自《管理规定》发布之日起六个月内依照《管理规定》和本《实施细则》办理审批手续。"},{"i":9,"n":"第九条","txt":"禁止未持有《许可证》的单位和个人设置卫星地面接收设施接收卫星传送的电视节目。"},{"i":10,"n":"第十条","txt":"安装卫星地面接收设施的施工单位，必须持有《卫星地面接收设施安装许可证》。申领安装许可证的条件和办法，由各省、自治区、直辖市广播电视行政部门自行制定。 单位和个人设置卫星地面接收设施，必须由持有《卫星地面接收设施安装许可证》的单位提供安装和维修服务。"},{"i":11,"n":"第十一条","txt":"持有《许可证》的单位和个人，必须按照《许可证》载明的接收目的、接收内容、接收方式和收视对象范围等要求，接收和使用卫星电视节目。 持有《接收卫星传送的境外电视节目许可证》的涉外宾馆可以通过宾馆的有线（闭路）电视系统向客房传送接收的境外电视节目。 持有《接收卫星传送的境外电视节目许可证》的其他单位，要根据工作需要限定收视人员范围，不得将接收设施的终端安置到超越其规定接收范围的场所。禁止在本单位的有线（闭路）电视系统中传送所接收的境外电视节目。 禁止在车站、码头、机场、商店和影视厅、歌舞厅等公共场所播放或以其它方式传播卫星传送的境外电视节目。 禁止利用卫星地面接收设施接收、传播反动淫秽的卫星电视节目。"},{"i":12,"n":"第十二条","txt":"禁止电视台、电视转播台、电视差转台、有线电视台、有线电视站、共用天线系统转播卫星传送的境外电视节目。"},{"i":13,"n":"第十三条","txt":"《许可证》不得涂改或者转让。需要改变《许可证》规定的内容或者不再接收卫星传送的电视节目的单位，应按设置卫星地面接收设施接收电视节目的申请程序，及时报请审批机关换发或者注销《许可证》。"},{"i":14,"n":"第十四条","txt":"有关卫星地面接收设施的宣传、广告不得违反《管理规定》及本《实施细则》的有关规定。"},{"i":15,"n":"第十五条","txt":"卫星地面接收设施由电子工业部指定的企业生产。定点生产企业的审批和管理办法，由电子工业部商有关部门另行制定。"},{"i":16,"n":"第十六条","txt":"卫星地面接收设施实行定点销售。定点销售单位的审批和管理办法由省、自治区、直辖市人民政府工商行政管理部门会同国内贸易、广播电视和电子工业行政部门另行制定。 定点销售单位只能向持有地、市级以上（含地、市级）广播电视行政部门开具的证明的单位和个人销售经质量认证合格的卫星地面接收设施。"},{"i":17,"n":"第十七条","txt":"卫星地面接收设施的质量认证证书和认证标志，由国家技术监督局或其授权的部门认可的认证机构按照有关质量认证的法律、法规的规定认证合格后发放；未经质量认证的，不得销售和使用。"},{"i":18,"n":"第十八条","txt":"进口卫星地面接收设施必须持广播电影电视部开具的证明，进口卫星地面接收设施的专用元部件必须持电子工业部开具的证明，到国家机电产品进出口办公室办理审批手续，海关凭审查批件放行。 禁止个人携带、邮寄卫星地面接收设施入境。"},{"i":19,"n":"第十九条","txt":"对违反本《实施细则》第九至第十四条规定的单位和个人，由县级以上（含县级）广播电视行政部门给予行政处罚。其具体处罚措施如下： （一）对违反本《实施细则》第九、第十一、第十二、第十三条规定的单位，可给予警告、一千至五万元罚款、没收其使用的卫星地面接收设施、吊销《许可证》等处罚； （二）对违反本《实施细则》第九、第十一、第十三条规定的个人，可给予警告、五百至五千元罚款、没收其使用的卫星地面接收设施、吊销《许可证》等处罚； （三）对违反本《实施细则》第十条规定，未持有《卫星地面接收设施安装许可证》而承担安装卫星地面接收设施施工任务的单位可处以警告、一千至三万元罚款； （四）对违反本《实施细则》第十四条规定的，可处以警告、一千至三万元罚款。 以上行政处罚可单处也可并处。 对同一单位或个人有两种以上违反本《实施细则》行为的行政处罚，分别裁决，合并执行。 对同一违规行为的行政处罚只能一次处罚，不得重"},{"i":20,"n":"第二十条","txt":"对违反本《实施细则》第十五条规定，未经批准擅自生产卫星地面接收设施的，按电子工业部的有关规定处罚。"},{"i":21,"n":"第二十一条","txt":"对违反本《实施细则》第十六条规定，未经批准擅自销售卫星地面接收设施的，及向未持有广播电视行政部门开具的证明的单位和个人销售卫星地面接收设施的，由工商行政管理部门责令停止销售，没收其卫星地面接收设施，并可以处以相当于销售额二倍以下的罚款。 对违反本《实施细则》第十七条规定，销售未经质量认证或认证不合格的卫星地面接收设施的，由标准化行政主管部门责令停止销售，处以违法所得三倍以下的罚款，并可对该违法单位负责人处五千元以下的罚款。"},{"i":22,"n":"第二十二条","txt":"对违反本《实施细则》第十八条规定，擅自进口卫星地面接收设施或携带卫星地面接收设施入境的，海关按照《海关法》的有关规定处理。"},{"i":23,"n":"第二十三条","txt":"抗拒、阻碍管理部门依法对卫星地面接收设施的生产、销售、设置、安装和使用进行管理的，由公安部门依照《中华人民共和国治安管理处罚条例》的规定处罚；情节严重、构成犯罪的，由司法机关依法追究当事人的刑事责任。"},{"i":24,"n":"第二十四条","txt":"利用卫星地面接收设施从事危害国家安全活动的，由国家安全、公安部门依照《国家安全法》的规定处理。"},{"i":25,"n":"第二十五条","txt":"当事人对依照《管理规定》和本《实施细则》做出的处罚决定不服的，可根据《行政复议条例》和《行政诉讼法》有关规定申请行政复议或者提起行政诉讼。 对于不申请复议、不起诉又不履行处罚决定的，作出处罚决定的广播电视等行政部门可依法强制执行（法律另有规定的除外）。"},{"i":26,"n":"第二十六条","txt":"罚款上缴国库。"},{"i":27,"n":"第二十七条","txt":"军队以及公安、国家安全部门设置用于军事、公安、国家安全业务的卫星地面接收设施，由中国人民解放军有关部门、公安部和国家安全部各自另行制定管理规定实施管理，并将管理规定送广播电影电视部备案。但其宿舍区、宾馆等用于非军事、公安、国家安全业务的卫星地面接收设施的设置、安装和使用，应依照《管理规定》和本《实施细则》接受管理。 外国驻华使（领）馆，以及其它享有外交特权与豁免的机构设置卫星地面接收设施，通过外交途径办理。"},{"i":28,"n":"第二十八条","txt":"持有《许可证》的单位接收、使用卫星传送的电视节目，应尊重该节目著作权人的权利。"},{"i":29,"n":"第二十九条","txt":"卫星地面接收设施管理费的征收和使用办法，由广播电影电视部商有关部门或由省、自治区、直辖市广播电视行政部门商有关部门制定。"},{"i":30,"n":"第三十条","txt":"各省、自治区、直辖市广播电视行政部门可依据《管理规定》和本《实施细则》，结合各地实际情况，商有关部门制定卫星地面接收设施的具体管理办法。"},{"i":31,"n":"第三十一条","txt":"本《实施细则》自发布之日起施行。过去发布的规定与《管理规定》和本《实施细则》不一致之处，均以《管理规定》和本《实施细则》为准。"}],"guangbodianshiguanggaobochuguanlibanfadebuchongguid0a5e2":[],"zhuanwangjidingxiangchuanboshitingjiemufuwuguanligbbbc9f":[{"i":1,"n":"第一条","txt":"为规范专网及定向传播视听节目服务秩序，促进行业健康有序发展，保护公众和从业机构的合法权益，维护国家利益和公共利益，根据国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称专网及定向传播视听节目服务，是指以电视机、手机等各类固定、移动电子设备为接收终端，通过局域网络及利用互联网架设虚拟专网或者以互联网等信息网络为定向传输通道，向公众定向提供广播电视节目等视听节目服务活动，包括以交互式网络电视（IPTV）、专网手机电视、互联网电视等形式从事内容提供、集成播控、传输分发等活动。"},{"i":3,"n":"第三条","txt":"国家广播电视总局负责全国专网及定向传播视听节目服务的监督管理工作。 县级以上地方人民政府广播电视行政部门负责本行政区域内专网及定向传播视听节目服务的监督管理工作。"},{"i":4,"n":"第四条","txt":"从事专网及定向传播视听节目服务，应当坚持为人民服务、为社会主义服务，把社会效益放在首位，弘扬社会主义核心价值观，弘扬民族优秀传统文化，弘扬正能量。 专网及定向传播视听节目服务单位应当自觉遵守宪法、法律和行政法规，提供更多更好的专网及定向传播视听节目服务，不断丰富人民群众的精神文化生活。 鼓励专网及定向传播视听节目服务行业组织发挥行业自律、引导、服务功能，鼓励公众监督专网及定向传播视听节目服务。"},{"i":5,"n":"第五条","txt":"从事内容提供、集成播控、传输分发等专网及定向传播视听节目服务，应当依照本规定取得《信息网络传播视听节目许可证》。 《信息网络传播视听节目许可证》由国家广播电视总局根据专网及定向传播视听节目服务的业务类别、服务内容、传输网络、覆盖范围等事项分类核发。 专网及定向传播视听节目服务业务指导目录由国家广播电视总局制定。"},{"i":6,"n":"第六条","txt":"申请从事专网及定向传播视听节目服务的单位，应当具备下列条件： （一）具备法人资格，为国有独资或者国有控股单位； （二）有健全的节目内容编审、安全传播管理制度和安全保护措施； （三）有与其业务相适应的技术能力、经营场所和相关资源； （四）有与其业务相适应的专业人员； （五）技术方案符合国家有关标准和技术规范； （六）符合国家广播电视总局确定的专网及定向传播视听节目服务总体规划、布局和业务指导目录； （七）符合法律、行政法规和国家规定的其他条件。 外商投资企业不得从事专网及定向传播视听节目服务。"},{"i":7,"n":"第七条","txt":"申请从事内容提供服务的，应当是经国家广播电视总局批准设立的地（市）级以上广播电视播出机构或者中央新闻单位等机构，还应当具备两千小时以上的节目内容储备和三十人以上的专业节目编审人员。 申请从事集成播控服务的，应当是经国家广播电视总局批准设立的省、自治区、直辖市级以上广播电视播出机构。 申请从事交互式网络电视（IPTV）传输服务、专网手机电视分发服务的，应当是工业和信息化部批准的具有合法基础网络运营资质的单位，并具有一定规模的公共信息基础网络设施资源和为用户提供长期服务的信誉或者能力。"},{"i":8,"n":"第八条","txt":"申请从事专网及定向传播视听节目服务，应当向省、自治区、直辖市人民政府广播电视行政部门提出申请，中央直属单位可直接向国家广播电视总局提出申请。 省、自治区、直辖市人民政府广播电视行政部门应当自收到申请之日起二十日内提出初核意见，并将初核意见及全部申请材料报国家广播电视总局审批；国家广播电视总局应当自收到申请或者初核意见之日起四十日内作出许可或者不予许可的决定，其中专家评审时间为二十日。予以许可的，向申请人颁发《信息网络传播视听节目许可证》，并向社会公告；不予许可的，应当书面通知申请人并说明理由。"},{"i":9,"n":"第九条","txt":"《信息网络传播视听节目许可证》有效期为三年。有效期届满，需继续从事专网及定向传播视听节目服务的，应当于有效期届满前三十日内，持符合本规定第六条、第七条条件的相关材料，按照本规定的审批程序办理续办手续。"},{"i":10,"n":"第十条","txt":"专网及定向传播视听节目服务单位变更《信息网络传播视听节目许可证》载明的业务类别、服务内容、传输网络、覆盖范围等业务项目以及变更股东、股权结构等重大事项的，应当事先按本规定办理审批手续。 专网及定向传播视听节目服务单位的单位名称、办公场所、法定代表人依法变更的，应当在变更后十五日内向原发证机关备案。 专网及定向传播视听节目服务单位采用合资、合作模式开展节目生产购销、广告投放、市场推广、商业合作、收付结算、技术服务等经营性业务的，应当在签订合资、合作协议后十五日内向原发证机关备案。"},{"i":11,"n":"第十一条","txt":"专网及定向传播视听节目服务单位在专网及定向传播视听节目服务业务指导目录载明的业务类别之外，拟增加新产品或者开展新业务的，应当报国家广播电视总局进行安全评估。"},{"i":12,"n":"第十二条","txt":"专网及定向传播视听节目服务单位应当在取得《信息网络传播视听节目许可证》九十日内提供服务。未按期提供服务的，由原发证机关注销其《信息网络传播视听节目许可证》。 如因特殊原因，延期或者中止提供服务的，应当经原发证机关同意。申请终止服务的，应当提前六十日向原发证机关申报，由原发证机关注销其《信息网络传播视听节目许可证》。 未经申报，连续停止业务超过六十日的，由原发证机关按终止业务处理，并注销其《信息网络传播视听节目许可证》。"},{"i":13,"n":"第十三条","txt":"专网及定向传播视听节目服务单位应当按照《信息网络传播视听节目许可证》载明的事项从事专网及定向传播视听节目服务。"},{"i":14,"n":"第十四条","txt":"专网及定向传播视听节目服务单位应当建立健全与国家网络信息安全相适应的安全管理制度、保障体系和技术保障手段，履行安全保障义务。 专网及定向传播视听节目服务单位应当为广播电视行政部门设立的节目监控系统提供必要的信号接入条件。"},{"i":15,"n":"第十五条","txt":"专网及定向传播视听节目服务单位相互之间应当按照广播电视行政部门的管理规定和相关标准实行规范对接，并为对接提供必要的技术支持和服务保障。"},{"i":16,"n":"第十六条","txt":"用于专网及定向传播视听节目服务的技术系统和终端产品，应当符合国家有关标准和技术规范。 任何单位不得向未取得专网及定向传播视听节目服务许可的单位提供与专网及定向传播视听节目服务有关的服务器托管、网络传输、软硬件技术支持、代收费等服务。"},{"i":17,"n":"第十七条","txt":"专网及定向传播视听节目服务单位传播的节目应当符合法律、行政法规、部门规章的规定，不得含有以下内容： （一）违反宪法确定的基本原则，煽动抗拒或者破坏宪法、法律、行政法规实施的； （二）危害国家统一、主权和领土完整，泄露国家秘密，危害国家安全，损害国家荣誉和利益的； （三）诋毁民族优秀文化传统，煽动民族仇恨、民族歧视，侵害民族风俗习惯，歪曲民族历史和民族历史人物，伤害民族感情，破坏民族团结的； （四）宣扬宗教狂热，危害宗教和睦，伤害信教公民宗教感情，破坏信教公民和不信教公民团结，宣扬邪教、迷信的； （五）危害社会公德，扰乱社会秩序，破坏社会稳定，宣扬淫秽、赌博、吸毒，渲染暴力、恐怖，教唆犯罪或者传授犯罪方法的； （六）侵害未成年人合法权益或者损害未成年人身心健康的； （七）侮辱、诽谤他人或者散布他人隐私，侵害他人合法权益的； （八）法律、行政法规禁止的其他内容。"},{"i":18,"n":"第十八条","txt":"专网及定向传播视听节目服务单位传播的电影、电视剧、动画片、纪录片等节目，应当符合国家广播电影电视相关管理规定。专网及定向传播视听节目服务单位传播的时政类视听新闻节目，应当是地（市）级以上广播电视播出机构制作、播出的新闻节目。 专网及定向传播视听节目服务单位不得转播、链接、聚合、集成非法广播电视频道节目、非法视听节目网站的节目和未取得内容提供服务许可的单位开办的节目。 专网及定向传播视听节目服务单位应当遵守著作权法律、行政法规的规定，采取版权保护措施，保护著作权人的合法权益。"},{"i":19,"n":"第十九条","txt":"内容提供服务单位，负责建设和运营内容提供平台，组织、编辑和审核节目内容。 内容提供服务单位播出的节目应当经过集成播控服务单位设立的集成播控平台统一集成后提供给用户。内容提供服务单位应当选择依法取得集成播控服务许可的单位提供接入服务。"},{"i":20,"n":"第二十条","txt":"内容提供服务单位负责审查其内容提供平台上的节目是否符合本规定第十七条的规定和版权管理要求，并进行播前审查。 内容提供服务单位应当建立健全节目审查、安全播出等节目内容管理制度，配备专业节目审查人员。所播出节目的名称、内容概要、播出时间、时长、来源等信息，应当至少保留六十日，并配合广播电视行政部门依法查询。 内容提供服务单位发现含有违反本规定的节目，应当立即删除并保存有关记录，并向广播电视行政部门报告，落实广播电视行政部门的管理要求。"},{"i":21,"n":"第二十一条","txt":"集成播控服务单位，负责集成播控平台的建设和运营，负责对内容提供服务单位播出的节目的统一集成和播出监控，负责电子节目指南（EPG）、用户端、计费、版权等管理。 集成播控服务单位发现接入集成播控平台的节目含有违反本规定的内容时，应当立即切断节目源，并向广播电视行政部门报告。"},{"i":22,"n":"第二十二条","txt":"集成播控服务单位应当建立健全安全播控管理制度，采取技术安全管控措施，配备专业安全播控管理人员，按照广播电视行政部门的管理规定集成播控节目。 集成播控服务单位在提供接入服务时，应当查验内容提供服务单位的《信息网络传播视听节目许可证》，并为其提供优质的信号接入服务，不得擅自插播、截留、变更内容提供服务单位播出的节目信号。"},{"i":23,"n":"第二十三条","txt":"集成播控服务单位和内容提供服务单位应当在播出界面显著位置标注国家广播电视总局批准的播出标识、名称。"},{"i":24,"n":"第二十四条","txt":"传输分发服务单位应当遵守广播电视行政部门有关安全传输的管理规定，建立健全安全传输管理制度，保障网络传输安全。 传输分发服务单位在提供传输分发服务前，应当查验集成播控服务单位的《信息网络传播视听节目许可证》。不得擅自插播、截留、变更集成播控平台发出的节目信号和电子节目指南（EPG）、用户端、计费、版权等控制信号。"},{"i":25,"n":"第二十五条","txt":"省、自治区、直辖市以上人民政府广播电视行政部门应当建立健全节目监管系统，建立公众监督举报制度，加强对专网及定向传播视听节目服务的监督管理。 广播电视行政部门发现专网及定向传播视听节目服务单位未及时处置违法违规内容、落实监管措施的，可以对其主要负责人、法定代表人、总编辑进行约谈。"},{"i":26,"n":"第二十六条","txt":"擅自从事专网及定向传播视听节目服务的，由县级以上人民政府广播电视行政部门予以警告、责令改正，可并处三万元以下罚款；情节严重的，根据《广播电视管理条例》第四十七条的规定予以处罚。"},{"i":27,"n":"第二十七条","txt":"专网及定向传播视听节目服务单位传播的节目内容违反本规定的，由县级以上人民政府广播电视行政部门予以警告、责令改正，可并处三万元以下罚款；情节严重的，根据《广播电视管理条例》第四十九条的规定予以处罚。"},{"i":28,"n":"第二十八条","txt":"违反本规定，有下列行为之一的，由县级以上人民政府广播电视行政部门予以警告、责令改正，可并处三万元以下罚款；情节严重的，根据《广播电视管理条例》第五十条的规定予以处罚： （一）未按照《信息网络传播视听节目许可证》载明的事项从事专网及定向传播视听节目服务的； （二）违规传播时政类视听新闻节目的； （三）集成播控服务单位未对内容提供服务单位播出的节目进行统一集成和播出监控或者未负责电子节目指南（EPG）、用户端、计费、版权等管理的。"},{"i":29,"n":"第二十九条","txt":"违反本规定，有下列行为之一的，由县级以上人民政府广播电视行政部门予以警告、责令改正，可并处三万元以下罚款；情节严重的，根据《广播电视管理条例》第五十一条的规定予以处罚： （一）专网及定向传播视听节目服务单位转播、链接、聚合、集成非法广播电视频道节目、非法视听节目网站的节目和未取得内容提供服务许可的单位开办的节目的； （二）集成播控服务单位擅自插播、截留、变更内容提供服务单位播出的节目信号的； （三）传输分发服务单位擅自插播、截留、变更集成播控平台发出的节目信号和电子节目指南（EPG）、用户端、计费、版权等控制信号的。"},{"i":30,"n":"第三十条","txt":"违反本规定，有下列行为之一的，由县级以上人民政府广播电视行政部门予以警告、责令改正，可并处三万元以下罚款；同时，可对其主要出资者和经营者予以警告，可并处两万元以下罚款： （一）变更股东、股权结构等重大事项，未事先办理审批手续的； （二）专网及定向传播视听节目服务单位的单位名称、办公场所、法定代表人依法变更后未及时向原发证机关备案的； （三）未按本规定要求，将拟增加的新产品或者开展的新业务报国家广播电视总局进行安全评估的； （四）采用合资、合作模式开展节目生产购销、广告投放、市场推广、商业合作、收付结算、技术服务等经营性业务未及时向原发证机关备案的； （五）集成播控服务单位和传输分发服务单位在提供服务时未履行许可证查验义务的； （六）未按本规定要求建立健全与国家网络信息安全相适应的安全播控、节目内容、安全传输等管理制度、保障体系的； （七）集成播控服务单位和内容提供服务单位未在播出界面显"},{"i":31,"n":"第三十一条","txt":"广播电视行政部门工作人员滥用职权、玩忽职守的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":32,"n":"第三十二条","txt":"制作、编辑、集成并通过互联网向公众提供视音频节目以及为他人提供上载传播视听节目服务的，由国家广播电视总局、工业和信息化部按照国家有关规定进行监督管理。"},{"i":33,"n":"第三十三条","txt":"本规定自2016年6月1日起施行。2004年7月6日国家广播电影电视总局发布的《互联网等信息网络传播视听节目管理办法》（国家广播电影电视总局令第39号）同时废止。"}],"zhongwaihezuozhizuodianshijuguanliguiding":[{"i":1,"n":"第一条","txt":"为促进中外文化交流，繁荣电视剧创作，加强中外合作制作电视剧管理，保护制作者的合法权益，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于境内广播电视节目制作机构(以下称中方)与外国法人及自然人(以下称外方)合作制作电视剧(含电视动画片)的活动。"},{"i":3,"n":"第三条","txt":"国家广播电影电视总局(以下称广电总局)负责全国中外合作制作电视剧(含电视动画片)的管理工作，对境外合作方、数量和中外联合制作电视剧(含电视动画片)题材实施调控。 省级广播电视行政部门负责本行政区域内中外合作制作电视剧(含电视动画片)的具体管理工作。"},{"i":4,"n":"第四条","txt":"国家对中外合作制作电视剧(含电视动画片)实行许可制度。 未经批准，不得从事中外合作制作电视剧(含电视动画片)活动；未经审查通过的中外合作制作电视剧(含电视动画片)完成片，不得发行和播出。"},{"i":5,"n":"第五条","txt":"中外合作制作电视剧可以采取下列形式： (一)联合制作，系指中方与外方共同投资、共派主创人员、共同分享利益及共同承担风险的电视剧(含电视动画片)制作方式； (二)协作制作，系指由外方出资并提供主创人员，在境内拍摄全部或部分外景，中方提供劳务或设备、器材、场地予以协助的电视剧制作方式； (三)委托制作，系指外方出资，委托中方在境内制作的电视剧制作方式。"},{"i":6,"n":"第六条","txt":"申请中外联合制作电视剧立项，应符合下列条件： (一)中方机构须持有《电视剧制作许可证(甲种)》； (二)中方机构应对联合制作的电视剧向广电总局同时申报合拍电视剧题材规划； (三)双方共同投资，包括以货币直接投资，或以劳务、实物、广告时间等折价作为投资； (四)前期创意、剧本写作等主要创作要素由双方共同确定； (五)共派创作人员、技术人员参与全程摄制。电视剧主创人员(编剧、制片人、导演、主要演员)中，中方人员不得少于三分之一； (六)电视剧的国内外版权归中方及外方共同所有。"},{"i":7,"n":"第七条","txt":"申请中外联合制作电视剧立项，应提交下列书面材料： (一)申请书； (二)《电视剧制作许可证(甲种)》复印件； (三)省级广播电视行政部门的初审意见(直接从广电总局申领《电视剧制作许可证(甲种)》的中方制作机构除外)； (四)每集不少于5000字的分集梗概或完整的剧本； (五)境内外主创人员(编剧、制片人、导演、主要演员)名单及履历； (六)制作计划、境内拍摄景点及详细拍摄日程； (七)合作协议意向书； (八)外方法人注册登记证明(外方为自然人的，应提交履历)、资信证明。审批机关可以要求外方提交经过公证的境外第三者担保书。"},{"i":8,"n":"第八条","txt":"申请中外联合制作电视动画片立项，应符合下列条件： (一)中方机构须持有《广播电视节目制作经营许可证》； (二)中方机构应对联合制作的电视动画片向广电总局同时申报合拍电视动画片题材规划； (三)双方共同投资，包括以货币直接投资，或以劳务、实物、广告时间等折价作为投资； (四)前期创意、剧本写作等主要创作要素由双方共同确定； (五)电视动画片的国内外版权归中方及外方共同所有。"},{"i":9,"n":"第九条","txt":"申请中外联合制作电视动画片立项，应提交以下材料： (一)申请书； (二)《广播电视节目制作经营许可证》复印件； (三)省级广播电视行政部门的初审意见(直接从广电总局申领《电视剧制作许可证(甲种)》的中方制作机构除外)； (四)每集不少于500字的分集梗概或完整的剧本； (五)合作协议意向书； (六)外方法人注册登记证明(外方为自然人的，应提交履历)、资信证明。审批机关可以要求外方提交经过公证的境外第三者担保书。"},{"i":10,"n":"第十条","txt":"申请中外协作制作、委托制作电视剧(含电视动画片)，应提交下列文件： (一)申请书； (二)每集不少于1500字的分集梗概或完整的剧本； (三)主创人员(编剧、制片人、导演、主要演员)名单； (四)境内拍摄景点及拍摄计划； (五)合作协议意向书； (六)审批机关可以要求外方提供的相关资信证明。"},{"i":11,"n":"第十一条","txt":"直接从广电总局申领《电视剧制作许可证(甲种)》的中方制作机构申请与外方合作制作电视剧(含电视动画片)，向广电总局申报。 其他中方制作机构申请与外方合作制作电视剧(含电视动画片)，经所在地省级广播电视行政部门同意，报广电总局审批。"},{"i":12,"n":"第十二条","txt":"广电总局在正式受理中外合作制作电视剧(含电视动画片)申请后，应当在法定期限内作出是否准予拍摄的决定。其中中外联合制作电视剧(含电视动画片)的审查时间为五十日(含专家评审时间三十日)；中外协作制作、委托制作的电视剧(含电视动画片)的审查时间为二十日。符合条件的，由广电总局作出准予拍摄的批复；不符合条件的，应当书面通知申请人并说明理由。 送审单位对不准予拍摄的决定不服的，可以在收到决定之日起六十日内，向广电总局提出复审申请。广电总局应当在五十日内作出复审决定，其中组织专家评审的时间为三十日，并将决定书面通知送审机构。"},{"i":13,"n":"第十三条","txt":"中外联合制作电视剧(含电视动画片)完成后，应当按照本规定第十一条规定的程序报省级以上广播电视行政部门审查。"},{"i":14,"n":"第十四条","txt":"申报中外联合制作电视剧(含电视动画片)完成片审查，应提交以下材料： (一)省级广播电视行政部门的初审意见(直接从广电总局申领《电视剧制作许可证(甲种)》的中方制作机构除外)； (二)广电总局准予拍摄的批复和合拍电视剧(电视动画片)题材规划的复印件； (三)图像、声音、时码等符合审查要求的大1/2完整录像带一套； (四)每集不少于300字的剧情梗概； (五)与样带字幕相同的片头片尾字幕。"},{"i":15,"n":"第十五条","txt":"广电总局在正式受理中外联合制作的电视剧(含电视动画片)完成片审查申请后，应当在五十日内作出是否准予行政许可的决定，其中组织专家评审的时间为三十日。符合条件的，由广电总局颁发《电视剧(电视动画片)发行许可证》；不符合条件的，应当书面通知申请人并说明理由。 送审单位对不准予行政许可的决定不服的，可以在收到决定之日起六十日内，向广电总局提出复审申请。广电总局应当依前款规定的审查期限作出复审决定，并将行政许可决定书面通知送审机构。复审合格的，由广电总局核发《电视剧(电视动画片)发行许可证》。"},{"i":16,"n":"第十六条","txt":"已经取得广电总局准予拍摄批复的剧本和已经取得《电视剧(电视动画片)发行许可证》的完成片，不得随意进行实质性的改动。确需对剧名、主要人物、主要情节和剧集长度等进行改动的，应当按照本规定重新报批。"},{"i":17,"n":"第十七条","txt":"国家鼓励中外合作制作体现中华民族优良传统和人类文明进步内容的电视剧，鼓励中外合作制作旨在塑造中国动画品牌形象的电视动画片。 中外合作制作的电视剧(含电视动画片)中不得含有下列内容： (一)反对宪法确定的基本原则的； (二)危害国家统一、主权和领土完整的； (三)泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； (四)煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； (五)宣扬邪教、迷信的； (六)扰乱社会秩序，破坏社会稳定的； (七)宣扬淫秽、赌博、暴力或者教唆犯罪的； (八)侮辱或者诽谤他人，侵害他人合法权益的； (九)危害社会公德或者民族优秀文化传统的； (十)有法律、行政法规和国家规定禁止的其他内容的。"},{"i":18,"n":"第十八条","txt":"凡以中国特色为表现主题的中外联合制作的电视动画片，可视同国产电视动画片播出。"},{"i":19,"n":"第十九条","txt":"中外联合制作电视剧(含电视动画片)应制作普通话语言版本。根据发行需要，经合作方同意，可以制作相应国家、地区、少数民族的语言文字版本。"},{"i":20,"n":"第二十条","txt":"违反本规定的，依据《广播电视管理条例》的规定予以处罚。构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"与香港特别行政区、澳门特别行政区、台湾地区的法人与自然人合作制作电视剧(含电视动画片)，参照本规定执行。"},{"i":22,"n":"第二十二条","txt":"本规定自2004年10月21日起施行，广播电影电视部《中外合作制作电视剧(录像片)管理规定》(广播电影电视部令第15号)同时废止。"}],"hulianwangshitingjiemufuwuguanliguiding-3":[{"i":1,"n":"第一条","txt":"为维护国家利益和公共利益，保护公众和互联网视听节目服务单位的合法权益，规范互联网视听节目服务秩序，促进健康有序发展，根据国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内向公众提供互联网（含移动互联网，以下简称互联网）视听节目服务活动，适用本规定。 本规定所称互联网视听节目服务，是指制作、编辑、集成并通过互联网向公众提供视音频节目，以及为他人提供上载传播视听节目服务的活动。"},{"i":3,"n":"第三条","txt":"国务院广播电影电视主管部门作为互联网视听节目服务的行业主管部门，负责对互联网视听节目服务实施监督管理，统筹互联网视听节目服务的产业发展、行业管理、内容建设和安全监管。国务院信息产业主管部门作为互联网行业主管部门，依据电信行业管理职责对互联网视听节目服务实施相应的监督管理。 地方人民政府广播电影电视主管部门和地方电信管理机构依据各自职责对本行政区域内的互联网视听节目服务单位及接入服务实施相应的监督管理。"},{"i":4,"n":"第四条","txt":"互联网视听节目服务单位及其相关网络运营单位，是重要的网络文化建设力量，承担建设中国特色网络文化和维护网络文化信息安全的责任,应自觉遵守宪法、法律和行政法规，接受互联网视听节目服务行业主管部门和互联网行业主管部门的管理。"},{"i":5,"n":"第五条","txt":"互联网视听节目服务单位组成的全国性社会团体，负责制定行业自律规范，倡导文明上网、文明办网，营造文明健康的网络环境，传播健康有益视听节目，抵制腐朽落后思想文化传播，并在国务院广播电影电视主管部门指导下开展活动。"},{"i":6,"n":"第六条","txt":"发展互联网视听节目服务要有益于传播社会主义先进文化，推动社会全面进步和人的全面发展、促进社会和谐。从事互联网视听节目服务，应当坚持为人民服务、为社会主义服务，坚持正确导向，把社会效益放在首位，建设社会主义核心价值体系，遵守社会主义道德规范，大力弘扬体现时代发展和社会进步的思想文化，大力弘扬民族优秀文化传统，提供更多更好的互联网视听节目服务，满足人民群众日益增长的需求，不断丰富人民群众的精神文化生活，充分发挥文化滋润心灵、陶冶情操、愉悦身心的作用，为青少年成长创造良好的网上空间，形成共建共享的精神家园。"},{"i":7,"n":"第七条","txt":"从事互联网视听节目服务，应当依照本规定取得广播电影电视主管部门颁发的《信息网络传播视听节目许可证》（以下简称《许可证》）或履行备案手续。 未按照本规定取得广播电影电视主管部门颁发的《许可证》或履行备案手续，任何单位和个人不得从事互联网视听节目服务。 互联网视听节目服务业务指导目录由国务院广播电影电视主管部门商国务院信息产业主管部门制定。"},{"i":8,"n":"第八条","txt":"申请从事互联网视听节目服务的，应当同时具备以下条件： （一）具备法人资格，为国有独资或国有控股单位，且在申请之日前三年内无违法违规记录； （二）有健全的节目安全传播管理制度和安全保护技术措施； （三）有与其业务相适应并符合国家规定的视听节目资源； （四）有与其业务相适应的技术能力、网络资源； （五）有与其业务相适应的专业人员，且主要出资者和经营者在申请之日前三年内无违法违规记录； （六）技术方案符合国家标准、行业标准和技术规范； （七）符合国务院广播电影电视主管部门确定的互联网视听节目服务总体规划、布局和业务指导目录； （八）符合法律、行政法规和国家有关规定的条件。"},{"i":9,"n":"第九条","txt":"从事广播电台、电视台形态服务和时政类视听新闻服务的，除符合本规定第八条规定外，还应当持有广播电视播出机构许可证或互联网新闻信息服务许可证。其中，以自办频道方式播放视听节目的，由地（市）级以上广播电台、电视台、中央新闻单位提出申请。 从事主持、访谈、报道类视听服务的，除符合本规定第八条规定外，还应当持有广播电视节目制作经营许可证和互联网新闻信息服务许可证；从事自办网络剧（片）类服务的，还应当持有广播电视节目制作经营许可证。 未经批准，任何组织和个人不得在互联网上使用广播电视专有名称开展业务。"},{"i":10,"n":"第十条","txt":"申请《许可证》，应当通过省、自治区、直辖市人民政府广播电影电视主管部门向国务院广播电影电视主管部门提出申请，中央直属单位可以直接向国务院广播电影电视主管部门提出申请。 省、自治区、直辖市人民政府广播电影电视主管部门应当提供便捷的服务，自收到申请之日起20日内提出初审意见，报国务院广播电影电视主管部门审批；国务院广播电影电视主管部门应当自收到申请或者初审意见之日起40日内作出许可或者不予许可的决定，其中专家评审时间为20日。予以许可的，向申请人颁发《许可证》，并向社会公告；不予许可的，应当书面通知申请人并说明理由。《许可证》应当载明互联网视听节目服务的播出标识、名称、服务类别等事项。 《许可证》有效期为3年。有效期届满，需继续从事互联网视听节目服务的，应于有效期届满前30日内，持符合本办法第八条规定条件的相关材料，向原发证机关申请办理续办手续。 地（市）级以上广播电台、电视台从事互联网视"},{"i":11,"n":"第十一条","txt":"取得《许可证》的单位，应当依据《互联网信息服务管理办法》，向省（自治区、直辖市）电信管理机构或国务院信息产业主管部门（以下简称电信主管部门）申请办理电信业务经营许可或者履行相关备案手续，并依法到工商行政管理部门办理注册登记或变更登记手续。电信主管部门应根据广播电影电视主管部门许可，严格互联网视听节目服务单位的域名和IP地址管理。"},{"i":12,"n":"第十二条","txt":"互联网视听节目服务单位变更股东、股权结构，有重大资产变动或有上市等重大融资行为的，以及业务项目超出《许可证》载明范围的，应按本规定办理审批手续。互联网视听节目服务单位的办公场所、法定代表人以及互联网信息服务单位的网址、网站名依法变更的，应当在变更后15日内向省级以上广播电影电视主管部门和电信主管部门备案,变更事项涉及工商登记的，应当依法到工商行政管理部门办理变更登记手续。"},{"i":13,"n":"第十三条","txt":"互联网视听节目服务单位应当在取得《许可证》90日内提供互联网视听节目服务。未按期提供服务的，其《许可证》由原发证机关予以注销。如因特殊原因，应经发证机关同意。申请终止服务的，应提前60日向原发证机关申报，其《许可证》由原发证机关予以注销。连续停止业务超过60日的，由原发证机关按终止业务处理，其《许可证》由原发证机关予以注销。"},{"i":14,"n":"第十四条","txt":"互联网视听节目服务单位应当按照《许可证》载明或备案的事项开展互联网视听节目服务，并在播出界面显著位置标注国务院广播电影电视主管部门批准的播出标识、名称、《许可证》或备案编号。 任何单位不得向未持有《许可证》或备案的单位提供与互联网视听节目服务有关的代收费及信号传输、服务器托管等金融和技术服务。"},{"i":15,"n":"第十五条","txt":"鼓励国有战略投资者投资互联网视听节目服务企业；鼓励互联网视听节目服务单位积极开发适应新一代互联网和移动通信特点的新业务，为移动多媒体、多媒体网站生产积极健康的视听节目，努力提高互联网视听节目的供给能力；鼓励影视生产基地、电视节目制作单位多生产适合在网上传播的影视剧（片）、娱乐节目，积极发展民族网络影视产业；鼓励互联网视听节目服务单位传播公益性视听节目。 互联网视听节目服务单位应当遵守著作权法律、行政法规的规定，采取版权保护措施，保护著作权人的合法权益。"},{"i":16,"n":"第十六条","txt":"互联网视听节目服务单位提供的、网络运营单位接入的视听节目应当符合法律、行政法规、部门规章的规定。已播出的视听节目应至少完整保留60日。视听节目不得含有以下内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）诱导未成年人违法犯罪和渲染暴力、色情、赌博、恐怖活动的； （八）侮辱或者诽谤他人，侵害公民个人隐私等他人合法权益的； （九）危害社会公德，损害民族优秀文化传统的； （十）有关法律、行政法规和国家规定禁止的其他内容。"},{"i":17,"n":"第十七条","txt":"用于互联网视听节目服务的电影电视剧类节目和其它节目，应当符合国家有关广播电影电视节目的管理规定。互联网视听节目服务单位播出时政类视听新闻节目，应当是地（市）级以上广播电台、电视台制作、播出的节目和中央新闻单位网站登载的时政类视听新闻节目。 未持有《许可证》的单位不得为个人提供上载传播视听节目服务。互联网视听节目服务单位不得允许个人上载时政类视听新闻节目，在提供播客、视频分享等上载传播视听节目服务时，应当提示上载者不得上载违反本规定的视听节目。任何单位和个人不得转播、链接、聚合、集成非法的广播电视频道、视听节目网站的节目。"},{"i":18,"n":"第十八条","txt":"广播电影电视主管部门发现互联网视听节目服务单位传播违反本规定的视听节目，应当采取必要措施予以制止。互联网视听节目服务单位对含有违反本规定内容的视听节目，应当立即删除，并保存有关记录，履行报告义务，落实有关主管部门的管理要求。 互联网视听节目服务单位主要出资者和经营者应对播出和上载的视听节目内容负责。"},{"i":19,"n":"第十九条","txt":"互联网视听节目服务单位应当选择依法取得互联网接入服务电信业务经营许可证或广播电视节目传送业务经营许可证的网络运营单位提供服务;应当依法维护用户权利，履行对用户的承诺，对用户信息保密,不得进行虚假宣传或误导用户、做出对用户不公平不合理的规定、损害用户的合法权益；提供有偿服务时，应当以显著方式公布所提供服务的视听节目种类、范围、资费标准和时限，并告知用户中止或者取消互联网视听节目服务的条件和方式。"},{"i":20,"n":"第二十条","txt":"网络运营单位提供互联网视听节目信号传输服务时，应当保障视听节目服务单位的合法权益，保证传输安全，不得擅自插播、截留视听节目信号;在提供服务前应当查验视听节目服务单位的《许可证》或备案证明材料，按照《许可证》载明事项或备案范围提供接入服务。"},{"i":21,"n":"第二十一条","txt":"广播电影电视和电信主管部门应建立公众监督举报制度。公众有权举报视听节目服务单位的违法违规行为，有关主管部门应当及时处理，不得推诿。广播电影电视、电信等监督管理部门发现违反本规定的行为，不属于本部门职责的，应当移交有权处理的部门处理。 电信主管部门应当依照国家有关规定向广播电影电视主管部门提供必要的技术系统接口和网站数据查询资料。"},{"i":22,"n":"第二十二条","txt":"广播电影电视主管部门依法对互联网视听节目服务单位进行实地检查，有关单位和个人应当予以配合。广播电影电视主管部门工作人员依法进行实地检查时应当主动出示有关证件。"},{"i":23,"n":"第二十三条","txt":"违反本规定有下列行为之一的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；同时，可对其主要出资者和经营者予以警告，可并处2万元以下罚款： （一）擅自在互联网上使用广播电视专有名称开展业务的； （二）变更股东、股权结构，或上市融资，或重大资产变动时，未办理审批手续的； （三）未建立健全节目运营规范，未采取版权保护措施，或对传播有害内容未履行提示、删除、报告义务的； （四）未在播出界面显著位置标注播出标识、名称、《许可证》和备案编号的； （五）未履行保留节目记录、向主管部门如实提供查询义务的； （六）向未持有《许可证》或备案的单位提供代收费及信号传输、服务器托管等与互联网视听节目服务有关的服务的； （七）未履行查验义务，或向互联网视听节目服务单位提供其《许可证》或备案载明事项范围以外的接入服务的； （八）进行虚假宣传或者误导用户的； （九）未经用户同意，擅自泄露用"},{"i":24,"n":"第二十四条","txt":"擅自从事互联网视听节目服务的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第四十七条的规定予以处罚。 传播的视听节目内容违反本规定的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第四十九条的规定予以处罚。 未按照许可证载明或备案的事项从事互联网视听节目服务的或违规播出时政类视听新闻节目的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第五十条之规定予以处罚。 转播、链接、聚合、集成非法的广播电视频道和视听节目网站内容的，擅自插播、截留视听节目信号的，由县级以上广播电影电视主管部门予以警告、责令改正，可并处3万元以下罚款；情节严重的，根据《广播电视管理条例》第五十一条之规定予以处罚。"},{"i":25,"n":"第二十五条","txt":"对违反本规定的互联网视听节目服务单位，电信主管部门应根据广播电影电视主管部门的书面意见，按照电信管理和互联网管理的法律、行政法规的规定，关闭其网站，吊销其相应许可证或撤销备案，责令为其提供信号接入服务的网络运营单位停止接入；拒不执行停止接入服务决定，违反《电信条例》第五十七条规定的，由电信主管部门依据《电信条例》第七十八条的规定吊销其许可证。 违反治安管理规定的，由公安机关依法予以处罚；构成犯罪的，由司法机关依法追究刑事责任。"},{"i":26,"n":"第二十六条","txt":"广播电影电视、电信等主管部门不履行规定的职责，或滥用职权的，要依法给予有关责任人处分，构成犯罪的，由司法机关依法追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"互联网视听节目服务单位出现重大违法违规行为的，除按有关规定予以处罚外，其主要出资者和经营者自互联网视听节目服务单位受到处罚之日起5年内不得投资和从事互联网视听节目服务。"},{"i":28,"n":"第二十八条","txt":"通过互联网提供视音频即时通讯服务，由国务院信息产业主管部门按照国家有关规定进行监督管理。 利用局域网络及利用互联网架设虚拟专网向公众提供网络视听节目服务，须向行业主管部门提出申请，由国务院信息产业主管部门前置审批，国务院广播电影电视主管部门审核批准，按照国家有关规定进行监督管理。"},{"i":29,"n":"第二十九条","txt":"本规定自2008年1月31日起施行。此前发布的规定与本规定不一致之处，依本规定执行。"}],"weixingdianshiguangbodimianjieshousheshianzhuangfu665aaa":[{"i":1,"n":"第一条","txt":"为了规范卫星电视广播地面接收设施（以下简称卫星地面接收设施）安装服务活动，维护相关各方合法权益，根据《卫星电视广播地面接收设施管理规定》、《广播电视管理条例》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于卫星地面接收设施的安装施工及其配套供应、售后服务维修和卫星节目落地代理、收视授权等相关服务活动。"},{"i":3,"n":"第三条","txt":"县级以上人民政府广播影视行政部门会同其他有关部门，依据各自职责，负责对本行政区域内的卫星地面接收设施安装服务活动实施监督管理，指导从事卫星地面接收设施安装服务活动的机构（以下简称卫星地面接收设施安装服务机构）分层次、分区域建立健全卫星地面接收设施安装专营服务体系及网点，向用户提供及时便捷服务，维护用户基本公共文化权益；并依法维护广播影视事业建设和节目传播的正常秩序，打击非法生产、销售、安装卫星地面接收设施行为。 上级人民政府广播影视行政部门及其他有关部门，应当加强对下级人民政府广播影视行政部门及其他有关部门相关管理工作的监督检查。"},{"i":4,"n":"第四条","txt":"国家对卫星地面接收设施安装服务实行许可制度。 设立卫星地面接收设施安装服务机构，应当取得《卫星地面接收设施安装服务许可证》。未持有《卫星地面接收设施安装服务许可证》的单位，不得从事卫星地面接收设施的安装施工及其配套供应、售后服务维修和卫星节目落地代理、收视授权等相关服务活动。 卫星地面接收设施安装服务机构，应当凭用户出具的省、自治区、直辖市人民政府广播影视行政部门核发的购买证明，向用户提供卫星地面接收设施安装服务。所安装的卫星地面接收设施，应当由省、自治区、直辖市以上人民政府广播影视行政部门核准的卫星地面接收设施安装服务机构，从合法的卫星地面接收设施生产企业定向进货；进货时，应当核验该企业所持国家统一组织招标的中标通知书和与省、自治区、直辖市人民政府广播影视行政部门签订的设施采购合同等文件。卫星地面接收设施不得进入社会市场流通领域。 卫星地面接收设施安装服务机构,应当接受卫星节目运营机"},{"i":5,"n":"第五条","txt":"申请设立的卫星地面接收设施安装服务机构，应当具备下列条件： （一）具有独立法人资格，其中企业法人应当是国有企业或者国有控股企业； （二）有符合国家法律、法规规定的机构名称、组织机构和章程，有健全的管理制度和安全保障措施； （三）有与其业务活动相适应的专业人员、设备和营业场所； （四）有明确的服务区，有可行的服务方案及必要的服务资源； （五）法定代表人、主要出资者和经营者在申请之日前三年内，未因违反国家卫星地面接收设施管理的规定而被有关主管部门给予两次以上行政处罚的； （六）符合法律、行政法规和国家有关规定规定的其他条件。 广播影视行政部门在审核上述条件时，还应当统筹考虑当地广播电视覆盖的规划及建设安排。"},{"i":6,"n":"第六条","txt":"申请设立卫星地面接收设施安装服务机构，应当提交以下材料： （一）申请报告和申请表； （二）拟申请服务区的范围图； （三）主要工程技术人员名单和证明材料； （四）法人代表、主要经营者的身份证明和简历及主要出资单位有关证明材料； （五）营业场所证明。"},{"i":7,"n":"第七条","txt":"设立卫星地面接收设施安装服务机构，应当根据拟申请服务区的范围，向所在地县级以上人民政府广播影视行政部门提出申请，经逐级审核后，报省、自治区、直辖市以上人民政府广播影视行政部门审批。 省、自治区、直辖市以上人民政府广播影视行政部门应当自收到申请或者初审意见20日内，作出准予许可或者不予许可的决定。准予许可的，发给许可证；不予许可的，应当书面通知申请人并说明理由。 《卫星地面接收设施安装服务许可证》由国务院广播影视行政部门统一印制。"},{"i":8,"n":"第八条","txt":"卫星地面接收设施安装服务机构应当按照《卫星地面接收设施安装服务许可证》载明的业务类别、服务区等事项从事卫星地面接收设施安装服务活动。 卫星地面接收设施安装服务机构拟变更机构名称、法定代表人、主要出资者、主要经营者、业务类别、服务区等重要事项的，应当在变更前30日向原发证机关申请换发《卫星地面接收设施安装服务许可证》。 卫星地面接收设施安装服务机构拟终止服务，应当在终止前60日向原发证机关提交终止服务申请及善后方案，经原发证机关批准后方可终止。善后服务方案由所在地县级人民政府广播影视行政部门监督执行。"},{"i":9,"n":"第九条","txt":"卫星地面接收设施安装服务机构和卫星地面接收设施生产企业之间，除依法形成的供货关系外，不得存在其他利益关联。相关供货产品的维修网点，双方可以通过委托、代理、合作方式设立，卫星地面接收设施生产企业不得自行建立或者参股。设立维修网点应当具备必要的维修管理条件，经所在地县级人民政府广播影视行政部门审核，报省、自治区、直辖市人民政府广播影视行政部门批准，凭批准文件到工商行政管理机关变更或者注册营业执照后，方可营业。"},{"i":10,"n":"第十条","txt":"卫星地面接收设施安装服务机构不得为传播下列内容的卫星节目信号提供卫星地面接收设施安装服务： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉、利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）未经国务院广播影视行政部门批准或者在国务院广播影视行政部门规定的范围及其他特定地区以外落地的境内外电视节目； （十一）法律、行政法规和国家有关规定禁止的其他内容。"},{"i":11,"n":"第十一条","txt":"卫星地面接收设施安装服务机构应当遵守以下规范： （一）确保卫星地面接收设施安装施工质量，遵循牢固稳定、安全可靠、经济适用、便于维护的原则； （二）确保卫星地面接收设施及配件产品来源合法、质量合格。安装施工及维修所涉及产品，应当取得国务院广播影视行政部门颁发的广播电视设备器材入网认定证书，列入国家公布的卫星地面接收设施生产企业及认证产品名录，并通过国家卫星地面接收设施技术性能安全检验审核； （三）应当按照卫星节目运营机构的委托，向用户完整提供可供其选择申请接收的卫星节目名单，所代理、授权用户收视的卫星节目来源和内容应当合法，确保用户收视节目质量，维护卫星节目方和收视方的合法权益； （四）施工完毕后，应当先报请用户审批机关或者其授权的机构实施检验并加贴合格标志，方可为用户开通使用； （五）开通维修服务电话，制定服务标准和流程，及时向用户提供全面的咨询和便捷的服务； （六）建立用户业务档案和"},{"i":12,"n":"第十二条","txt":"省、自治区、直辖市人民政府广播影视行政部门应当根据本办法规定，制定本行政区域内的卫星地面接收设施安装服务管理细则，接受社会监督。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府广播影视行政部门应当对本行政区域内的卫星地面接收设施安装服务机构的服务情况依法监督检查。"},{"i":14,"n":"第十四条","txt":"违反本办法规定，擅自提供卫星地面接收设施安装服务的，由县级以上人民政府广播影视行政部门没收其从事违法活动的设施、工具，对个人可以并处5千元以下的罚款，对单位可以并处5万元以下的罚款。 卫星地面接收设施安装服务机构和卫星地面接收设施生产企业之间，存在违反本办法规定的利益关联的，由县级以上人民政府广播影视行政部门责令改正，可以并处3万元以下的罚款；情节严重的，由原发证机关吊销《卫星地面接收设施安装服务许可证》。 违反本办法其他规定的，由县级以上人民政府广播影视行政部门依据《卫星电视广播地面接收设施管理规定》、《广播电视管理条例》及国家有关规定予以处罚；构成犯罪的，依法追究刑事责任。 广播影视行政部门在查处违反本办法规定的行为时，发现存在无照经营情形的，应当移送工商行政管理部门依法处理。"},{"i":15,"n":"第十五条","txt":"本办法所称用户，是指符合国家规定的设置使用卫星地面接收设施的条件，并持有或者提出申请《接收卫星传送的电视节目许可证》的单位或者个人。 本办法所称用户审批机关，是指依据《卫星电视广播地面接收设施管理规定》、《〈卫星电视广播地面接收设施管理规定〉实施细则》规定，负责审批设置使用卫星地面接收设施的国务院、省和地（市）三级广播影视行政部门。 本办法所称卫星地面接收设施生产企业，是指经国务院工业和信息化行政部门指定，并持有国务院质量监督检验检疫行政部门颁发的卫星电视广播地面接收设施生产许可证的企业。"},{"i":16,"n":"第十六条","txt":"境外节目接收用户、数字电影院线等特定用户的卫星地面接收设施安装服务，由国务院广播影视行政部门指定的机构提供，按照国家有关规定实施管理。"},{"i":17,"n":"第十七条","txt":"本办法自2010年1月1日起施行。 本办法施行前已依法取得卫星地面接收设施安装许可证的单位，应当在本办法施行之日起6个月内，依据本办法重新审核登记，换发许可证；逾期未取得新许可证的，由广播影视行政部门依法予以处理。 本办法施行前已依法设置卫星地面接收设施的单位用户和个人用户，应当在本办法施行之日起一年内，自主选择委托所在服务区内的卫星地面接收设施安装服务机构，纳入其统一运行维护范围；确有特殊需要且具备规定条件的单位用户，可申请设立卫星地面接收设施安装服务机构，自行承担本单位卫星地面接收设施的运行维护。"}],"guojiaguangbodianyingdianshizongjuxingzhengxukeshi1192f0":[{"i":1,"n":"第一条","txt":"为规范总局行政许可行为，推进总局依法行政工作，根据行政许可法的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"总局各司局实施行政许可，应当严格遵循行政许可法和其他法律、法规、规章规定。法律、法规、规章没有具体规定的，适用本办法。 本办法适用于由总局实施的行政许可事项及由法律、法规、国务院决定设立或保留的由总局实施的行政许可事项。"},{"i":3,"n":"第三条","txt":"除法律、法规另有规定的以外，不得授权其他机关、组织实施行政许可。 除法律、法规、规章规定可以委托其他行政机关实施行政许可的情形外，总局各司局不得将总局的行政许可事项擅自委托其他行政机关实施。 不得委托除行政机关之外的任何组织、企业和个人实施行政许可。"},{"i":4,"n":"第四条","txt":"任何规定未经公布，不得作为实施行政许可的依据。实施行政许可的司局应依法履行公示义务，可以通过在总局指定地点张贴、向申请人提供行政许可指南手册、在广播电台、电视台、报刊、杂志和政府网站公布等多种方式公示行政许可法第三十条所规定的各项内容。除依法不得公开的外，下列内容应当公示： （一）行政许可事项、依据、条件、数量、程序、期限，需要提交的全部材料的目录，申请书示范文本及许可证件样式； （二）承办部门及联系方式（电话、通讯地址及电子邮件地址）； （三）需要听证、招标、检测、检验、专家论证和需要其他行政机关协办的事项及期限； 　　（四）授权实施行政许可的组织和被授权实施行政许可的内容； （五）受委托的行政机关和受委托实施行政许可的内容； （六）依法应当先经下级行政机关审查的行政许可事项； （七）对行政许可的实施有异议时可采取的投诉方式（投诉电话、通讯地址及电子邮件地址）； （八）公众有权查询的"},{"i":5,"n":"第五条","txt":"实施行政许可的司局不得擅自更改依法确定的行政许可事项的名称、条件、程序和期限。依法变更的，应及时更新相关公示内容。"},{"i":6,"n":"第六条","txt":"实施行政许可的司局应当制作并向申请人提供行政许可申请书、申请表等格式文本，格式文本中不得包括与申请行政许可事项无直接关系的内容。不得要求申请人提交与所申请的行政许可事项无关的技术资料和其他材料。"},{"i":7,"n":"第七条","txt":"申请人直接提交或按照公示的联系方式通过邮寄、传真或电子邮件方式提交行政许可申请的，以公示的受理部门收到之日为申请日。申请人同时以邮寄、传真或电子邮件方式提交行政许可申请的，其申请日以邮寄方式为准。 依法应当先经下级广播影视行政机关审查的行政许可事项，以该机关公示的受理部门收到之日为申请日。对申请人提交的行政许可申请，一般应在受理当场或收到申请之日作出是否受理的决定，最多不得超过五个工作日。受理或不受理行政许可申请，应分别向申请人出具《行政许可受理通知书》或《行政许可不受理通知书》。 申请人提交的申请材料需要补正的，受理申请的司局应于当场或在收到申请材料之日起五个工作日内向申请人出具《申请材料补正通知书》，一次性列出应补正材料的全部内容。《申请材料补正通知书》应一式两份，一份交申请人，一份自存作为补正后的核对凭证。 《行政许可受理通知书》和《行政许可不受理通知书》样式由总局统一制定，分类"},{"i":8,"n":"第八条","txt":"实施行政许可的有关司局通过邮寄方式将《行政许可受理通知书》、《行政许可不受理通知书》、《申请材料补正通知书》、行政许可决定等文件送达申请人的，以文件发出之日（以邮戳为准）为送达之日。 行政许可文件一般不以传真或电子邮件方式送达。如遇特殊情况，以传真或电子邮件方式送达的，应在条件具备时以邮寄方式补发行政许可文件。"},{"i":9,"n":"第九条","txt":"由两个以上司局共同办理的行政许可事项，主办司局负责统一受理行政许可申请、会同协办司局审查、统一送达行政许可文件等事项。协办司局应将需要审查的材料清单事先提供给主办司局。 《申请材料补正通知书》应当包括协办司局办理行政许可事项所需要的申请材料。"},{"i":10,"n":"第十条","txt":"除法律、法规另有规定外，实施行政许可的司局应当自受理行政许可申请之日起二十个工作日内作出行政许可决定。实施行政许可的司局如需延长审查期限的，报经总局局长或分管副局长批准，可以延长十个工作日，并应当将延长期限的理由告知申请人。 根据法律、法规和规章规定，作出行政许可决定依法需要听证、招标、拍卖、检验、检测、鉴定和专家评审的，应当在规定的期限内完成，实施行政许可的司局应当将所需时间书面告知申请人。 两个以上司局共同办理的事项，主办司局应与协办司局共同确定各自实施行政许可所需要的时限，并按确定的时限完成。"},{"i":11,"n":"第十一条","txt":"实施行政许可需要进行听证的，由受理申请的司局组织，并制作听证笔录，经听证参加人确认无误后签字认可并立卷归档。 听证按照法定程序进行，由审查该行政许可申请的工作人员以外的人员主持，申请人、利害关系人要求主持人回避的，受理申请的司局应尽快作出决定并告知当事人。 听证事项涉及公共利益的，应于举行听证之日的七个工作日前将举行听证的时间、地点通过总局政府网站予以公告。"},{"i":12,"n":"第十二条","txt":"实施行政许可的司局应当对申请人提交的申请材料进行审查。申请人提交的申请材料齐全、符合法定形式的，实施行政许可的司局应当作出书面的行政许可决定。需要对申请材料的实质内容进行核实的，应当指派两名以上工作人员进行核实。"},{"i":13,"n":"第十三条","txt":"除法律、法规另有规定的外，依法应先经下级广播影视行政机关审查的行政许可事项，下级广播影视行政机关决定受理后，应在二十个工作日内按法律、法规、规章的规定进行初审，并按照行政许可法第三十五条的规定将初审意见和全部申请材料直接报送上级广播影视行政机关，不得自行作出准予或不准予行政许可的决定。上级广播影视行政机关不得要求申请人重复提供申请材料。"},{"i":14,"n":"第十四条","txt":"作出不予行政许可书面决定的，应当说明理由，并告知申请人依法享有申请行政复议或者提起行政诉讼的权利。申请人对行政许可决定不服依法提起行政复议的，由总局法规司负责受理。"},{"i":15,"n":"第十五条","txt":"实施行政许可的司局应将实施行政许可形成的全部材料和监督核查被许可人从事行政许可事项的有关情况和处理结果的记录立卷归档。 实施行政许可的司局负责统计受理、批准件数，给予通报、行政处罚的件数等。总局法规司负责统计受理处理行政复议的情况，驻总局监察局负责统计受理投诉、检举情况和处理情况。 凡法律、法规、规章规定公众有权查询的与行政许可实施有关的材料，由实施该行政许可的司局协助查询。"},{"i":16,"n":"第十六条","txt":"实施行政许可的司局负责监督核查被许可人从事行政许可事项的活动，依据行政许可法及广播影视有关法规、规章的规定提出对违法被许可人给予行政处罚的意见，报总局局长或分管副局长批准。 实地核查时，实施行政许可的司局应有两名以上（含两名）工作人员同行，向被许可人或其委托人出示介绍信。负责核查的工作人员将核查情况和处理结果予以记录，由核查人、被核查的被许可人或其委托人签字后归档。被许可人或其委托人不签字的，由核查人注明在场人员和拒绝签字原因等。 需要对行政许可事项进行年检的，应当有法律、法规的规定作为依据。"},{"i":17,"n":"第十七条","txt":"已实施的行政许可有依行政许可法第六十九条、第七十条规定可撤销、应注销情形的，该行政许可实施司局应及时办理撤销、注销手续。"},{"i":18,"n":"第十八条","txt":"其他行政机关、组织和个人反映被许可人违法从事行政许可活动，作出该行政许可决定的司局应当及时核实、处理。"},{"i":19,"n":"第十九条","txt":"总局法规司和驻总局监察局负责监督各司局实施行政许可的情况，可以对行政许可实施情况进行核查，也可直接向申请人、被许可人调查了解有关情况，并根据核查结果， 提出处理建议。"},{"i":20,"n":"第二十条","txt":"驻总局监察局负责受理社会投诉和举报。有违反行政许可法规定的，由有关部门依法给予批评教育、通报批评、调离岗位、免职等行政处分。需要给予党纪处分的，向总局直属机关纪委提出建议。 能主动承认错误，及时纠正违规行为并尚未造成严重后果的，可以对其作出从轻、减轻或免除责任追究的决定。"},{"i":21,"n":"第二十一条","txt":"除行政许可法第七十二条、第七十三条、第七十四条规定外，各司局有下列情形之一的，由总局法规司或驻总局监察局建议改正；情节严重的，由有关部门依法对直接负责的主管人员和其他直接责任人给予相应处分： （一）擅自设立、更改或者取消行政许可事项的； （二）在依法规定的许可条件和标准之外，擅自增加其他条件或者限制的； （三）违反法定程序实施行政许可的； （四）应撤销行政许可决定或吊销行政许可证件未及时撤销、吊销、办理注销手续造成严重后果的； （五）拒绝、妨碍监督部门的监督、检查的。"},{"i":22,"n":"第二十二条","txt":"对于依法先经下级广播影视行政机关审查的行政许可，有关司局对下级广播影视行政机关实施行政许可的行为应加强监督。凡下级广播影视行政机关未按照行政许可法的规定实施行政许可的，有关司局应当给予批评教育，并将情况通报其所属地方人民政府。"},{"i":23,"n":"第二十三条","txt":"由法律、法规授权实施行政许可的组织和受总局委托的行政机关实施被授权、受委托的行政许可时，执行本办法。 地方广播影视行政机关实施行政许可，参照执行本办法。"},{"i":24,"n":"第二十四条","txt":"本办法自2004年8月1日起施行。 国家广播电影电视总局行政许可受理通知书 广发×（司局简称）许可（受）字（×年）第____号 申请人（姓名或单位名称）_____________________________，于______年______月______日就_____________________行政许可事项提交的申请，经审查，予以受理。 　　联系人： 　　联系电话： 　　特此通知。 国家广播电影电视总局 ____年____月____日 国家广播电影电视总局行政许可不受理通知书 广发×（司局简称）许可（不受）字（×年）第____号 申请人（姓名或单位名称）_____________________________，于______年______月______日就_____________________行政许可事项提交的申请，经审查，决定不予受理，理由如下： 1、本申请事项不需要取得行"}],"guojiaguangbodianshizongjulingdi11haoguangbodianshd16bfb":[{"i":1,"n":"第一条","txt":"为维护广播电视和网络视听领域行政管理秩序，保障和规范广播电视行政部门有效实施行政管理，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》《广播电视管理条例》及有关法律、行政法规的规定，制定本规定。"},{"i":2,"n":"第二条","txt":"办理广播电视行政处罚案件，适用本规定。"},{"i":3,"n":"第三条","txt":"实施广播电视行政处罚应当以法律、法规和规章为依据，应当遵循公正、公开的原则，坚持处罚与教育相结合。"},{"i":4,"n":"第四条","txt":"实施广播电视行政处罚，应当依法履行告知义务，保护当事人合法权益。"},{"i":5,"n":"第五条","txt":"广播电视行政部门及其工作人员对实施行政处罚过程中知悉的国家秘密、商业秘密、工作秘密或者个人隐私，应当依法予以保密。"},{"i":6,"n":"第六条","txt":"县级以上广播电视行政部门可以根据工作需要，在法定权限内以书面委托书形式委托符合《中华人民共和国行政处罚法》规定的组织实施行政处罚。委托书应当规定委托的具体事项、权限及期限，并由委托广播电视行政部门和受委托组织向社会公布。"},{"i":7,"n":"第七条","txt":"实施广播电视行政处罚，由违法行为发生地的有行政处罚权的县级以上广播电视行政部门管辖。 违法行为发生地包括：法人住所地，实际经营地，服务许可地或者备案地，网站建立者、管理者、使用者所在地，网络接入地，计算机等终端设备所在地等。"},{"i":8,"n":"第八条","txt":"两个以上广播电视行政部门都有管辖权的案件，由最先立案的广播电视行政部门管辖。 对管辖发生争议的，应当协商解决，协商不成的，报请共同的上一级广播电视行政部门指定管辖；也可以直接由共同的上一级广播电视行政部门指定管辖。 重大、复杂的案件，可以由国家广播电视总局指定管辖。"},{"i":9,"n":"第九条","txt":"实施广播电视行政处罚，适用违法行为发生时的法律、法规、规章的规定。但是，作出行政处罚决定时，法律、法规、规章已被修改或者废止，且新的规定处罚较轻或者不认为是违法的，适用新的规定。"},{"i":10,"n":"第十条","txt":"广播电视行政处罚的立案依据、实施程序和救济渠道等信息应当公示。"},{"i":11,"n":"第十一条","txt":"广播电视行政部门应当依法以文字、音像等形式，对行政处罚的启动、调查取证、审核、决定、送达、执行等进行全过程记录，归档保存。"},{"i":12,"n":"第十二条","txt":"广播电视行政处罚应当由具有行政执法资格的执法人员实施。执法人员不得少于两人，法律另有规定的除外。 执法人员应当文明执法，尊重和保护当事人合法权益。"},{"i":13,"n":"第十三条","txt":"在案件办理过程中，当事人委托代理人的，应当提交授权委托书，载明委托人及其代理人的基本信息、委托事项及代理权限、代理权的起止日期、委托日期和委托人签名或者盖章。 委托人变更委托内容或者提前解除委托的，应当书面告知广播电视行政部门。"},{"i":14,"n":"第十四条","txt":"执法人员有下列情形之一的，应当自行回避，当事人及其代理人有权申请其回避： （一）是案件的当事人或者当事人的近亲属； （二）本人或者其近亲属与案件有直接利害关系； （三）与案件有其他关系，可能影响案件公正处理。"},{"i":15,"n":"第十五条","txt":"执法人员自行回避或者当事人及其代理人要求执法人员回避的，应当提出申请，并且说明理由。 回避申请由广播电视行政部门依法审查，并由本机关负责人作出决定。回避决定作出前，执法人员不停止行政处罚案件调查。"},{"i":16,"n":"第十六条","txt":"听证主持人、记录员、检测人、检验人、技术鉴定人和翻译人员的回避，适用本规定第十四条、第十五条的规定。"},{"i":17,"n":"第十七条","txt":"广播电视行政部门办理行政处罚案件的证据种类主要有： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。 证据必须经查证属实，方可作为认定案件事实的根据。 以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":18,"n":"第十八条","txt":"广播电视行政部门收集的物证、书证应当是原物、原件。收集原物、原件确有困难的，可以拍摄、复制足以反映原物、原件内容或者外形的照片、录像、复制件，并且可以指定或者委托有关单位或者个人对原物、原件予以妥善保管。"},{"i":19,"n":"第十九条","txt":"广播电视行政部门收集电子数据或者录音、录像等视听资料，应当收集原始载体。 收集原始载体确有困难的，可以采取打印、拍照或者录像等方式固定相关证据，并附有关过程等情况的文字说明。"},{"i":20,"n":"第二十条","txt":"期间以时、日、月、年计算。期间开始的时和日，不计算在期间内。期间届满的最后一日是节假日的，以其后的第一个工作日为期间届满日期。 期间不包括在途时间，法定期满前交付邮寄的，不视为逾期。"},{"i":21,"n":"第二十一条","txt":"经当事人或者其代理人同意并签订确认书的，广播电视行政部门可以采用传真、电子邮件等方式，将行政处罚决定书等法律文书送达当事人或者其代理人。 采取前款方式送达的，以传真、电子邮件等到达当事人或者其代理人特定系统的日期为送达日期。"},{"i":22,"n":"第二十二条","txt":"广播电视行政处罚法律文书的送达程序，《中华人民共和国行政处罚法》《中华人民共和国行政强制法》和本规定均未明确的，适用《中华人民共和国民事诉讼法》的相关规定。"},{"i":23,"n":"第二十三条","txt":"对行政处罚案件的法律文书和案件有关材料，应当按照下列顺序及时归档： （一）案卷封面； （二）案卷材料目录； （三）行政处罚决定书； （四）行政处罚决定书送达回证； （五）立案批件； （六）调查笔录、现场笔录； （七）照片等证据材料； （八）先行登记保存、抽样取证相关文书； （九）检验或者鉴定证明； （十）行政处罚告知书； （十一）行政处罚告知书送达回证； （十二）听证相关材料； （十三）财产处理单据； （十四）行政处罚决定审批表； （十五）结案报告； （十六）其他有关材料； （十七）案卷封底。 予以立案，但未作处罚决定的案件材料，也应按前款规定归档。"},{"i":24,"n":"第二十四条","txt":"行政处罚案卷必须一案一卷，并经立卷人签字或者盖章。 任何人不得私自增添或者抽取案卷材料。未经许可，不得擅自借阅。"},{"i":25,"n":"第二十五条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下，对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，广播电视行政部门可以适用简易程序当场作出行政处罚决定。"},{"i":26,"n":"第二十六条","txt":"执法人员当场作出行政处罚决定的，应当向当事人出示执法证件，填写预定格式、编有号码的行政处罚决定书，并当场交付当事人。当事人拒绝签收的，应当在行政处罚决定书上注明。 前款规定的行政处罚决定书应当载明当事人的违法行为，行政处罚的种类和依据、罚款数额、时间、地点，申请行政复议、提起行政诉讼的途径和期限以及作出行政处罚决定机关名称，并由执法人员签名或者盖章。 执法人员当场作出的行政处罚决定，应当报作出行政处罚决定机关备案。"},{"i":27,"n":"第二十七条","txt":"除依法可以当场作出的行政处罚外，广播电视行政部门发现公民、法人或者其他组织有依法应当给予行政处罚的行为的，必须全面、客观、公正地调查，收集有关证据；必要时，依照法律、法规的规定，可以进行检查。符合立案标准的，应当及时立案。"},{"i":28,"n":"第二十八条","txt":"执法人员进行调查或者进行检查时，应当主动向当事人或者有关人员出示执法证件。当事人或者有关人员有权要求执法人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。 当事人或者有关人员应当如实回答询问，并协助调查或者检查，不得拒绝或者阻挠。询问或者检查应当制作笔录。"},{"i":29,"n":"第二十九条","txt":"调查笔录或者现场笔录应当由当事人或者在场的有关人员核对后签字或者盖章。 对拒不签字或者盖章的，可以由在场执法人员签字或者盖章并注明情况，也可以采取录音、拍照、录像等方式记录。"},{"i":30,"n":"第三十条","txt":"执法人员可以采取询问，勘验，检查，抽样取证，鉴定，拍摄，收集、调取和固定电子数据等方式收集证据。 在证据可能灭失或者以后难以取得的情况下，经本机关负责人批准，可以先行登记保存，并填写证据先行登记保存通知书、物品清单和现场笔录。"},{"i":31,"n":"第三十一条","txt":"对先行登记保存的证据应当视情况选择适当场所妥善保存，并于七日内作出处理决定： （一）需要采取证据保全措施的，采取记录、复制、拍照、录像等证据保全措施后予以返还； （二）法律、法规、规章规定的其他处理方式。 对需要进行技术检测、检验或者鉴定的，进行检测、检验或者鉴定的时间不计入作出处理决定期限。 在先行登记保存期间，当事人或者有关人员不得销毁或者转移证据。"},{"i":32,"n":"第三十二条","txt":"执法人员对证据进行抽样取证或者先行登记保存，须经本机关负责人批准，并制发相关通知书。当事人不在场或者拒绝到场的，执法人员可请有关人员参加，或者由在场执法人员签字或者盖章并注明情况，也可以采取录音、拍照、录像等方式记录。 对抽样取证或者先行登记保存的物品应当开列清单，写明物品名称、数量、规格等事项，由执法人员、当事人签名或者盖章，一式两份，一份送达当事人。当事人拒绝签收的，应当由两名以上执法人员在清单上注明情况。"},{"i":33,"n":"第三十三条","txt":"广播电视行政部门在调查终结后、作出行政处罚决定前，应当制作行政处罚告知书，告知当事人拟作出的行政处罚内容及事实、理由、依据，并且告知当事人依法享有的陈述、申辩、要求听证等权利。 广播电视行政部门未依照前款规定履行告知义务，或者拒绝听取当事人的陈述、申辩，不得作出行政处罚决定；当事人明确放弃陈述或者申辩权利的除外。"},{"i":34,"n":"第三十四条","txt":"当事人有权进行陈述和申辩。广播电视行政部门必须充分听取当事人意见，对当事人提出的事实、理由和证据，应当进行复核；当事人提出的事实、理由、证据或者意见成立的，应当采纳。 广播电视行政部门不得因当事人陈述、申辩、要求听证而给予更重的处罚，但是发现新的违法事实的除外。"},{"i":35,"n":"第三十五条","txt":"除因不可抗力或者广播电视行政部门认可的其他正当理由外，当事人应当在收到行政处罚告知书之日起五日内提出书面陈述、申辩和要求听证。逾期视为放弃权利。 当事人因不可抗拒的事由或者其他正当理由耽误期限的，在障碍消除后的十日内可以向广播电视行政部门申请顺延期限，是否准许，由广播电视行政部门决定。"},{"i":36,"n":"第三十六条","txt":"对违法行为调查终结，本机关负责人应当对拟作出的行政处罚决定进行审查，根据不同情况分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。 对情节复杂或者重大违法行为给予行政处罚，应由本机关负责人集体讨论决定。对集体讨论的案件，实行首长负责制。 法律、法规、规章规定应当经上级广播电视行政部门批准的，应当经批准后决定。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一，在本机关负责人作出决定之前，应当由从事行政处罚决定法制审核的人员进行法制审核，未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂，涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 本机关中初次从事行政处罚决定法制审核的人员，应当符合《中华人民共和国行政处罚法》中的相关要求。"},{"i":38,"n":"第三十八条","txt":"广播电视行政部门依照本规定第三十六条的规定应当给予行政处罚的，应当制作行政处罚决定书。 行政处罚决定书应当载明以下内容： （一）当事人的基本情况，包括当事人姓名或者名称、地址等； （二）违反法律、法规、规章的事实和证据； （三）行政处罚的种类和依据； （四）行政处罚的履行方式和期限； （五）申请行政复议或者提起行政诉讼的途径和期限； （六）作出行政处罚决定的行政部门名称和作出决定的日期。 行政处罚决定书必须盖有作出行政处罚决定机关的印章。"},{"i":39,"n":"第三十九条","txt":"广播电视行政部门应当自行政处罚案件立案之日起六个月内作出行政处罚决定；确有必要的，经本机关负责人批准可以延长期限，延长期限不得超过六个月。案情特别复杂或者有其他特殊情况，经延长期限仍不能作出处理决定的，应当由省级以上广播电视行政部门负责人集体讨论决定是否继续延长期限，决定继续延长期限的，应当同时确定延长的合理期限。 上述期间不包括公告、检测、检验、技术鉴定、听证的期间。 在案件办理期间，发现当事人另有违法行为的，自发现之日起重新计算办案期限。"},{"i":40,"n":"第四十条","txt":"广播电视行政部门拟作出下列行政处罚决定，应当告知当事人有要求听证的权利，当事人要求听证的，应当组织听证： （一）对公民处一万元以上罚款、对法人或者其他组织处十万元以上罚款； （二）对公民处没收违法所得一万元以上、对法人或者其他组织处没收违法所得十万元以上； （三）没收公民、法人或者其他组织从事违法活动的工具、设备、节目载体，价值分别超过一万元、十万元； （四）降低资质等级、吊销许可证件； （五）责令停产停业、责令关闭、限制从业； （六）其他较重的行政处罚； （七）法律、法规、规章规定的其他情形。 各省、自治区、直辖市人大常委会或者人民政府对前款第（一）项、第（二）项、第（三）项所列金额另有规定的，可以从其规定。 当事人不承担组织听证的费用。"},{"i":41,"n":"第四十一条","txt":"听证由广播电视行政部门负责行政处罚案件法制审核的部门组织。"},{"i":42,"n":"第四十二条","txt":"除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证公开举行。"},{"i":43,"n":"第四十三条","txt":"广播电视行政部门决定组织听证的，应当自收到听证申请之日起二十日以内举行听证，并在举行听证的七日前将举行听证的时间、地点通知听证参加人和其他人员。"},{"i":44,"n":"第四十四条","txt":"听证结束后，广播电视行政部门应当根据听证笔录，依照本规定第三十六条的规定作出决定。"},{"i":45,"n":"第四十五条","txt":"广播电视行政部门作出行政处罚决定后，当事人应当在行政处罚决定书载明的期限内，予以履行。 广播电视行政部门作出罚款决定的，当事人应当自收到行政处罚决定书之日起十五日内，到指定的银行或者通过电子支付系统缴纳罚款。"},{"i":46,"n":"第四十六条","txt":"当事人确有经济困难向广播电视行政部门提出延期或者分期缴纳罚款的，应当以书面方式提出申请。 广播电视行政部门收到当事人延期、分期缴纳罚款的申请后，应当在十日内作出是否准予延期、分期缴纳罚款的决定。"},{"i":47,"n":"第四十七条","txt":"依照本规定第二十五条的规定当场作出行政处罚决定，有下列情形之一，执法人员可以当场收缴罚款： （一）依法给予一百元以下罚款的； （二）不当场收缴事后难以执行的。"},{"i":48,"n":"第四十八条","txt":"当事人逾期不履行行政处罚决定的，广播电视行政部门可以采取下列措施： （一）到期不缴纳罚款的，每日按照罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额； （二）法律规定的其他行政强制执行方式； （三）依照《中华人民共和国行政强制法》的规定申请人民法院强制执行。"},{"i":49,"n":"第四十九条","txt":"广播电视行政部门实施行政处罚，有下列情形之一的，由上级广播电视行政部门或者有关部门责令改正，可以对直接负责的主管人员和其他直接责任人员依法给予处分： （一）没有法定的行政处罚依据的； （二）擅自改变行政处罚种类、幅度的； （三）违反法定的行政处罚程序的； （四）违反本规定第六条关于委托处罚的规定的； （五）执法人员未取得执法证件的。 广播电视行政部门对符合立案标准的案件不及时立案的，依照前款规定予以处理。"},{"i":50,"n":"第五十条","txt":"执法人员玩忽职守、徇私舞弊、滥用职权、索取或者收受他人财物的，依法给予处分；构成犯罪的，依法追究刑事责任。"},{"i":51,"n":"第五十一条","txt":"广播电视行政部门对应当依法移交司法机关追究刑事责任的案件不移交，以行政处罚代替刑事处罚，由上级行政机关或者有关机关责令改正，对直接负责的主管人员和其他直接责任人员依法给予处分；情节严重构成犯罪的，依法追究刑事责任。"},{"i":52,"n":"第五十二条","txt":"本规定中所称广播电视行政处罚，包括对广播电视和网络视听领域违法行为实施的行政处罚。"},{"i":53,"n":"第五十三条","txt":"本规定所称以上、以下，包括本数。"},{"i":54,"n":"第五十四条","txt":"本规定中“三日”“五日”“七日”“十日”“二十日”的规定是指工作日，不含法定节假日。"},{"i":55,"n":"第五十五条","txt":"本规定自公布之日起施行。1996年12月19日发布的《广播电影电视行政处罚程序暂行规定》（广播电影电视部令第20号）同时废止。"}],"guojiaguangbodianshizongjulingdi12haoguangbodiansh9cbcbd":[{"i":1,"n":"第一条","txt":"为了加强广播电视节目传送业务管理，规范广播电视节目传送秩序，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称广播电视节目传送业务，是指利用有线方式从事广播电视节目传输和接入服务的活动。"},{"i":3,"n":"第三条","txt":"国家广播电视总局（以下简称广电总局）负责全国广播电视节目传送业务的管理。 县级以上人民政府广播电视主管部门负责本行政区域内广播电视节目传送业务的管理。"},{"i":4,"n":"第四条","txt":"国家对广播电视节目传送业务实行许可制度。"},{"i":5,"n":"第五条","txt":"利用有线方式从事广播电视节目传送业务，应当按本办法规定领取《广播电视节目传送业务经营许可证》。 利用无线、微波、卫星等其他方式从事广播电视节目传送业务，应当按照国家有关规定办理相关审批手续。"},{"i":6,"n":"第六条","txt":"下列机构可以申请《广播电视节目传送业务经营许可证》： （一）经批准设立的广播电视播出机构； （二）有线广播电视网络运营服务机构。"},{"i":7,"n":"第七条","txt":"禁止外商投资的机构从事广播电视节目传送业务。"},{"i":8,"n":"第八条","txt":"申请《广播电视节目传送业务经营许可证》，应当具备下列条件： （一）符合国家广播电视节目传送业务总体规划和业务要求； （二）具有确保广播电视节目安全传送所需的设备、技术、人员及相关管理制度； （三）资费标准符合国家有关规定； （四）有从事经营活动的场所及相应网络资源； （五）有长期提供传送服务的信誉和能力； （六）有合法的广播电视节目信号来源； （七）其他法律、行政法规规定的条件。"},{"i":9,"n":"第九条","txt":"申请《广播电视节目传送业务经营许可证》，应当提交下列材料： （一）有线电视网络建设及覆盖情况、传送内容（应写明具体频道、节目名称）、传送范围、技术手段、传送方式等内容的说明； （二）申办机构基本情况。申办机构为企业单位的，应当提供股东背景情况的说明； （三）《广播电视节目传送业务经营许可证》申请表； （四）从事广播电视节目传送业务的技术方案、运营方案、管理制度； （五）广播电视节目安全传送方案； （六）广播电视节目信号来源相关材料。"},{"i":10,"n":"第十条","txt":"申请利用有线方式跨省级行政区域从事广播电视节目传送业务的，应当向广电总局提出申请，并提交符合本办法第九条规定的申报材料，由广电总局审批。 申请利用有线方式在省级行政区域内从事广播电视节目传送业务的，应当向省级人民政府广播电视主管部门提出申请，并提交符合本办法第九条规定的申报材料，由省级人民政府广播电视主管部门审批。"},{"i":11,"n":"第十一条","txt":"负责受理的广播电视主管部门应当按照行政许可法规定的期限和权限，履行受理、审核职责。广播电视主管部门应当自受理之日起二十日内，作出许可或者不予许可的决定。二十日内不能作出决定的，经本机关负责人批准，可以延长十日，并应当将延长期限的理由告知申请机构。需要组织专家评审的，评审期限为三十日。 广播电视主管部门对符合法定条件的，予以许可，颁发《广播电视节目传送业务经营许可证》；对依法作出不予许可决定的，应当书面通知申请机构并说明理由。"},{"i":12,"n":"第十二条","txt":"《广播电视节目传送业务经营许可证》包含传送内容、传送范围、技术手段、传送方式等事项，有效期为三年，自颁发之日起计算。有效期满需继续从事广播电视节目传送业务的，应当在许可证有效期届满六十日前，按照本办法第六条、第八条、第九条、第十条规定提出延续申请，经广播电视主管部门审核同意后换发许可证。经审核不符合延续条件的，不予换证。 持证机构应当按照许可证载明的事项从事广播电视节目传送业务。"},{"i":13,"n":"第十三条","txt":"持证机构变更股东、持股比例，许可证载明的传送内容、传送范围、传送载体、技术手段，以及停止从事广播电视节目传送业务，应当按照本办法规定提前六十日报广播电视主管部门批准。国家对停止从事传送业务有其他规定的，还应当按照有关规定执行。 持证机构营业场所、法定代表人发生变更的，应当自变更之日起三十日内向原发证机关备案。"},{"i":14,"n":"第十四条","txt":"从事广播电视节目传送业务的机构应当在《广播电视频道播出许可证》规定的传输覆盖范围内传送频道节目。"},{"i":15,"n":"第十五条","txt":"广播电视播出机构不得通过未获得广播电视节目传送业务许可的机构传送其节目信号。"},{"i":16,"n":"第十六条","txt":"从事广播电视节目传送业务的机构不得利用所拥有的网络或者频率资源擅自开办广播电视节目，不得为非法开办的节目以及来源非法的广播电视节目信号提供传送服务，不得擅自传送境外卫星电视节目。"},{"i":17,"n":"第十七条","txt":"禁止传送含有下列内容的广播电视节目信号： （一）违反宪法确定的基本原则，煽动抗拒或者破坏宪法、法律、法规实施； （二）危害国家统一、主权和领土完整； （三）泄露国家秘密、危害国家安全或者损害国家尊严、荣誉和利益； （四）诋毁优秀民族文化传统，煽动民族仇恨、民族歧视，侵害民族风俗习惯，歪曲民族历史或者民族历史人物，伤害民族感情，破坏民族团结； （五）违背国家宗教政策，宣扬邪教、迷信； （六）危害社会公德，扰乱社会秩序，破坏社会稳定，宣扬淫秽、赌博、吸毒，渲染暴力、恐怖，教唆犯罪或者传授犯罪方法； （七）侵害未成年人合法权益或者损害未成年人身心健康； （八）侮辱、诽谤他人或者散布他人隐私，侵害他人合法权益； （九）法律、行政法规禁止的其他内容。"},{"i":18,"n":"第十八条","txt":"从事广播电视节目传送业务的机构不得擅自在所传送的节目中插播其他节目、资料、图像、文字及其他信息。"},{"i":19,"n":"第十九条","txt":"从事广播电视节目传送业务的机构应当完整传送广电总局规定必须传送的广播电视节目。"},{"i":20,"n":"第二十条","txt":"从事广播电视节目传送业务的机构应当提供长期、稳定的服务。"},{"i":21,"n":"第二十一条","txt":"从事广播电视节目传送业务的机构应当向广播电视主管部门设立的监测机构提供所传送节目的完整信号，不得干扰、阻碍监测活动。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定，擅自从事广播电视节目传送业务的，由县级以上人民政府广播电视主管部门没收其从事违法活动的设备，并处投资总额1倍以上2倍以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定，有下列行为之一的，由县级以上人民政府广播电视主管部门责令停止违法活动，给予警告，没收违法所得，可以并处二万元以下罚款。构成犯罪的，依法追究刑事责任： （一）未完整传送广电总局规定必须传送的广播电视节目的； （二）擅自在所传送的节目中插播节目、资料、图像、文字及其他信息的； （三）未按照许可证载明事项从事传送业务的； （四）持证机构变更股东、持股比例，许可证载明的传送内容、传送范围、传送载体、技术手段，以及停止从事广播电视节目传送业务，未办理审批手续的； （五）未向广播电视主管部门设立的监测机构提供所传送节目的完整信号，或者干扰、阻碍监测活动的。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，有下列行为之一的，由县级以上人民政府广播电视主管部门责令停止违法活动，给予警告，没收违法所得，可以并处二万元以下罚款；情节严重的，由原发证机关吊销许可证。构成犯罪的，依法追究刑事责任： （一）擅自开办广播电视节目的； （二）为非法开办的节目以及非法来源的广播电视节目信号提供传送服务； （三）擅自传送境外卫星电视节目的。"},{"i":25,"n":"第二十五条","txt":"本办法所称“十日”“二十日”“三十日”，是指工作日，不包括法定节假日。"},{"i":26,"n":"第二十六条","txt":"本办法自公布之日起施行。《广播电视节目传送业务管理办法》（国家广播电影电视总局令第33号）同时废止。"}],"guojiaguangbodianshizongjulingdi13haoguangbodiansh096c7b":[{"i":1,"n":"第一条","txt":"为了保证广播电视无线传输覆盖业务的正常进行，维护广播电视播出秩序，加强对广播电视无线传输覆盖业务的管理，根据《广播电视管理条例》和《广播电视设施保护条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于广播电视无线传输覆盖网（以下简称无线传输覆盖网）的规划、建设、使用和管理等活动。 无线传输覆盖网包括广播电视发射台、转播台、差转台、收转台（站）、微波站、节目传送台（站）、广播电视卫星、卫星地球站、监测台（站）等部分。广播电视无线传输覆盖业务是指利用无线传输覆盖网传送广播电视节目信号、应急广播信息的活动。"},{"i":3,"n":"第三条","txt":"国家广播电视总局（以下简称广电总局）负责全国无线传输覆盖网的管理工作，根据广播电视的发展需要，负责组织制定全国无线传输覆盖网规划，审批广播电视无线传输覆盖业务，指配广播电视专用频段的频率（以下称广播电视频率），并对全国无线传输覆盖网进行管理。 县级以上地方人民政府广播电视主管部门负责本行政区域内无线传输覆盖网的管理工作。"},{"i":4,"n":"第四条","txt":"无线传输覆盖网由县级以上人民政府广播电视主管部门按照国家有关规定组建，并应当确保本行政区域内广播电视传输覆盖的安全和质量。"},{"i":5,"n":"第五条","txt":"无线传输覆盖网的工程选址、设计、施工、安装，应当按照国家有关规定办理，并由依法取得相应资质的单位承担。工程建设和使用的无线广播电视发射设备，应当符合国家标准、行业标准和有关规定。"},{"i":6,"n":"第六条","txt":"国家对广播电视无线传输覆盖业务、利用卫星方式传输广播电视节目、使用广播电视频率、购买无线广播电视发射设备以及迁建无线广播电视设施实行许可制度。 广播电视主管部门应当按照行政许可法规定的期限办理有关许可事项，可根据需要组织专家对重要技术方案进行论证，专家论证时间为三十日。 许可证由广电总局统一印制，严禁伪造、翻印、涂改、出租、转让。"},{"i":7,"n":"第七条","txt":"严禁在无线传输覆盖网中传送法律、法规、规章规定禁止的内容。任何单位或者个人不得擅自使用广播电视频率，不得利用无线传输覆盖网进行违法犯罪活动。"},{"i":8,"n":"第八条","txt":"利用地面无线、微波、卫星等方式从事广播电视传输覆盖业务的，应当按照本办法规定领取《广播电视节目传送业务经营许可证（无线）》。 许可证有效期不超过十年。有效期届满需继续开展业务的，应当于届满前六个月按照本办法规定的审批程序办理手续。"},{"i":9,"n":"第九条","txt":"下列机构可以申请《广播电视节目传送业务经营许可证（无线）》： （一）经广电总局批准设立的广播电视播出机构； （二）经省级以上人民政府广播电视主管部门批准设立的广播电视无线传输覆盖机构（以下简称传输覆盖机构）； （三）具有无线广播电视传输覆盖能力的国有或者国有控股机构。"},{"i":10,"n":"第十条","txt":"申请《广播电视节目传送业务经营许可证（无线）》的，应当具备下列条件： （一）具有独立的法人资格，或者不具有独立的法人资格但直属于广播电视主管部门的传输覆盖机构； （二）符合无线传输覆盖网的总体规划和业务要求； （三）有确保广播电视安全传送所需的场地、设备、技术、人员及经费； （四）有合法的广播电视节目信号来源。"},{"i":11,"n":"第十一条","txt":"申请《广播电视节目传送业务经营许可证（无线）》的，应当提交下列材料： （一）申办机构的基本情况； （二）广播电视无线传输覆盖业务申请表； （三）拟采用的传输覆盖方式、范围、服务区域和节目内容； （四）技术方案和保障机制； （五）合法广播电视节目信号来源、传输方式、传输范围的说明。"},{"i":12,"n":"第十二条","txt":"广电总局负责审批跨省级行政区域经营广播电视节目无线传送业务。申请单位应当向广电总局提出申请，经批准领取《广播电视节目传送业务经营许可证（无线）》。"},{"i":13,"n":"第十三条","txt":"省级人民政府广播电视主管部门负责审批本行政区域内经营广播电视节目无线传送业务。申请单位应当向省级人民政府广播电视主管部门提出申请，经批准领取《广播电视节目传送业务经营许可证（无线）》。"},{"i":14,"n":"第十四条","txt":"开展广播电视节目卫星传送业务的，应当报广电总局审批，领取《广播电视节目传送业务经营许可证（无线）》。"},{"i":15,"n":"第十五条","txt":"为保证广播电视传输安全，广电总局负责指定用于传输广播电视节目的卫星转发器传输参数。任何未取得《广播电视节目传送业务经营许可证（无线）》的单位不得擅自租用或者使用卫星转发器传输广播电视节目。"},{"i":16,"n":"第十六条","txt":"为保证广播电视节目传输安全，广电总局可以要求更换或关闭传输广播电视节目的卫星转发器。"},{"i":17,"n":"第十七条","txt":"《广播电视节目传送业务经营许可证（无线）》由广电总局统一制定许可证制式。许可证应当包含实施传输覆盖业务的方式、主体、传输覆盖的节目内容、传输覆盖的范围、技术手段、工作频段等内容。 持证单位应当按照许可证载明的事项从事广播电视无线传输覆盖业务。"},{"i":18,"n":"第十八条","txt":"广播电视播出机构利用卫星方式传输广播电视节目，应当向广电总局提出申请，并在经批准的覆盖范围内进行覆盖。"},{"i":19,"n":"第十九条","txt":"利用卫星方式传输广播电视节目，应当具备下列条件： （一）申请人应当为经广电总局批准设立的广播电视播出机构； （二）符合国家广播电视事业和产业发展规划； （三）符合广播电视传输覆盖网相关规划和技术要求； （四）有必要的资金、稳定的经费和人员保障； （五）利用卫星方式传输覆盖的范围与广电总局批准的节目覆盖范围一致； （六）具备必要的监测监管条件。"},{"i":20,"n":"第二十条","txt":"广播电视播出机构申请利用卫星方式传输广播电视节目业务的，应当提交下列材料： （一）申办机构的基本情况； （二）利用卫星方式传输广播电视节目业务申请表； （三）拟采用的传输方式、覆盖范围、服务区域、节目内容、集成加密平台和技术参数； （四）拟利用卫星的轨道位置、转发器编号、极化方式、符号率、频率以及入网测试情况； （五）技术方案、技术安全保障机制及评估报告； （六）所在地省级人民政府广播电视主管部门的意见； （七）合法广播电视节目信号来源、传输方式、覆盖范围的说明。"},{"i":21,"n":"第二十一条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，申请使用微波、卫星非广播电视频率等传输广播电视节目，应当向国家无线电管理机构或者省、自治区、直辖市无线电管理机构办理无线电频率使用许可。"},{"i":22,"n":"第二十二条","txt":"持有《广播电视节目传送业务许可证（无线）》的单位，申请使用下列业务的广播电视频率，应当向所在地县级以上人民政府广播电视主管部门提出申请，逐级上报广电总局审批，领取《广播电视频率使用许可证（甲类）》： （一）中、短波广播； （二）调频广播（使用发射机标称功率50瓦（不含）以上发射设备）； （三）调频同步广播； （四）地面数字声音广播； （五）地面数字电视广播。 许可证有效期不超过十年。有效期届满需继续开展业务的，应当于届满前六个月按照本办法规定的审批程序办理手续。"},{"i":23,"n":"第二十三条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，申请使用发射机标称功率50瓦（含）以下转播已批准开办的广播节目、应急广播信息的小功率调频广播频率，广电总局委托省级人民政府广播电视主管部门审批。 申请单位向所在地县级人民政府广播电视主管部门提出申请，逐级上报省级人民政府广播电视主管部门审批，领取《广播电视频率使用许可证（乙类）》。 省级人民政府广播电视主管部门应当遵循高效、便民原则，提高办事效率，在委托的权限范围内按照广电总局统一制定的许可证制式，依法办理广播电视频率使用许可证，并对当月作出的不予受理、准予或者不准予行政审批决定等情况进行汇总，于次月15日前报广电总局备案。"},{"i":24,"n":"第二十四条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，申请使用广播电视频率传输广播电视节目，应当提供下列材料： （一）广播电视频率申请表； （二）申请使用的广播电视频率涉及修改和调整广播电视覆盖网规划的，提供技术评估报告和与相关部门或单位的协调文件； （三）拟开展的广播电视业务的情况说明，包括功能、用途、服务对象和预测规模以及建设计划等； （四）各级广播电视主管部门的书面意见。"},{"i":25,"n":"第二十五条","txt":"持有《广播电视频率使用许可证》的单位，如需设置、使用无线电台（站），应当向国家无线电管理机构或者省、自治区、直辖市无线电管理机构申请办理无线电台执照。"},{"i":26,"n":"第二十六条","txt":"持有《广播电视频率使用许可证》的单位，如需购买无线广播电视发射设备，应当向核发其《广播电视频率使用许可证》的广播电视主管部门申领《无线广播电视发射设备订购证明》（以下简称《订购证明》），并提交下列材料： （一）《订购证明》申请表； （二）《广播电视频率使用许可证》复印件； （三）各级广播电视主管部门的书面意见。"},{"i":27,"n":"第二十七条","txt":"无线传输覆盖网中使用的发射设备应当具有国家无线电发射设备型号核准证和广播电视设备器材入网认定证书。"},{"i":28,"n":"第二十八条","txt":"无线广播电视发射设备安装完毕后，设置该发射设备的单位应当在二十日内向核发其《订购证明》的广播电视主管部门提出验收申请，由相应的广播电视主管部门或者其委托的机构负责组织验收。验收合格后，发射设备方可投入正式运行。"},{"i":29,"n":"第二十九条","txt":"任何单位和个人均有保护广播电视设施的义务。县级以上人民政府广播电视主管部门负责所管辖的广播电视设施的保护工作，并采取措施，确保广播电视设施的安全。"},{"i":30,"n":"第三十条","txt":"因重大工程项目或者当地人民政府认为需要搬迁无线广播电视设施的，城市规划主管部门在审批相关城市规划项目前，应当事先征得广电总局同意。 迁建广播电视设施，申请单位应当向广电总局提出申请，并具备下列条件： （一）符合城乡建设总体规划和国家有关规定； （二）满足广播电视安全播出的技术条件和基础设施； （三）满足广播电视传输覆盖业务要求，避开各种干扰源； （四）周围环境符合国家有关环境电磁波防护标准； （五）确保广播电视设施的各项性能的要求。"},{"i":31,"n":"第三十一条","txt":"申请迁建无线广播电视设施的，应当提交下列材料： （一）设置无线广播电视设施的批准文件和申请迁建的理由； （二）城市规划主管部门的意见； （三）当地人民政府的批准文件； （四）广播电视传输覆盖技术评估报告。"},{"i":32,"n":"第三十二条","txt":"迁建工作应当坚持先建设后拆除的原则。迁建所需费用由造成广播电视设施迁建的单位承担。"},{"i":33,"n":"第三十三条","txt":"违反本办法的，依据《广播电视管理条例》《广播电视设施保护条例》处罚。"},{"i":34,"n":"第三十四条","txt":"本办法所称“二十日”“三十日”，是指工作日，不包括法定节假日。"},{"i":35,"n":"第三十五条","txt":"本办法自公布之日起施行。《广播电视无线传输覆盖网管理办法》（国家广播电影电视总局令第45号）同时废止。"}],"guojiaguangbodianshizongjuguanyuquxiaobufenguizhan65bfde":[],"guojiaguangbodianshizongjulifagongzuoguiding":[{"i":1,"n":"第一条","txt":"为了规范国家广播电视总局（以下简称总局）立法工作，提高立法质量和效率，根据《中华人民共和国立法法》《行政法规制定程序条例》《规章制定程序条例》《法规规章备案条例》等有关法律、行政法规，结合总局实际情况，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于下列立法工作： （一）编制中长期立法规划和年度立法工作计划； （二）根据全国人大常委会、国务院委托或者授权，起草法律、行政法规草案，并提出相关立法建议； （三）根据法律、行政法规、国务院决定和总局职权规定，制定、修订、解释和废止部门规章； （四）其他立法工作。"},{"i":3,"n":"第三条","txt":"立法工作应当坚持和加强党的全面领导，增强“四个意识”，坚定“四个自信”，做到“两个维护”，全面贯彻落实党的路线方针政策和决策部署，切实推动党的宣传思想方针政策通过法定程序成为国家意志。 立法工作应当坚持科学立法、民主立法、依法立法，及时准确反映改革发展要求，积极引导公民、法人和其他组织有序参与立法、表达意见，维护社会主义法制统一，不断提高立法质量和效率。 立法工作应当将社会主义核心价值观融入立法全过程，推动德法统一，推进行业治理体系和治理能力现代化。 立法工作应当落实党管意识形态原则，巩固马克思主义在意识形态领域的指导地位，体现属地管理、分级负责和谁主管谁负责等管理原则。"},{"i":4,"n":"第四条","txt":"涉及重大体制和重大政策调整的立法工作，应当按照有关规定及时报告总局党组；其中涉及法律、行政法规的，或者总局党组认为确有必要的，应当按照有关规定提请上级部门党委（党组）及时报告党中央。"},{"i":5,"n":"第五条","txt":"政策法规司负责组织、协调总局立法工作。 总局其他部门在职责范围内配合政策法规司开展相关立法工作。"},{"i":6,"n":"第六条","txt":"政策法规司根据全国人大常委会、国务院立法工作安排和宣传文化领域立法规划，立足于为依法落实意识形态工作责任制，推动制度创新，引领广播电视高质量创新性发展提供法治保障，紧紧围绕总局党组重大决策部署，按照统筹兼顾、突出重点的原则，组织编制中长期立法规划，报总局党组会议审议通过后向社会公布。 政策法规司根据中长期立法规划，与全国人大常委会、国务院年度立法计划相衔接，结合工作需要，组织编制总局年度立法计划。"},{"i":7,"n":"第七条","txt":"政策法规司在编制下一年度立法计划时，应当向总局其他部门征集法律、行政法规和规章的立项建议。 总局其他部门应当按照法定职能和意识形态工作责任分工，紧密结合总局党组年度重点工作，按照要求的形式和期限提出立项建议。立项建议涉及两个以上总局部门职责的，由所有关联部门共同报送。立项建议涉及国务院其他部门职责的，提出立项建议的总局部门应当在事前征求国务院相关部门的意见。 必要时，政策法规司可以向省、自治区、直辖市人民政府广播电视主管部门和社会公开征集立项建议。"},{"i":8,"n":"第八条","txt":"立法项目属于立法法第八条、第六十五条规定的事项，应当制定为法律、行政法规。 涉及国务院其他部门职责的事项，制定行政法规条件尚不成熟的，应当与国务院相关部门联合制定规章。 在总局职权范围内的下列事项，应当制定规章： （一）依法设定行政处罚的； （二）依法实施行政许可的； （三）依据有关法律、行政法规的授权和国务院的决定、命令，需要制定具体实施办法的； （四）属于其他执行法律、行政法规、国务院决定或者命令的。"},{"i":9,"n":"第九条","txt":"立项建议应当包括下列内容： （一）拟制定、修订的法律、行政法规、规章的名称、起草部门、项目负责人； （二）立法的必要性，贯彻落实党中央、国务院的决策部署等立法依据以及拟通过立法解决的主要问题； （三）拟确立的主要制度、措施。如需设定行政许可、行政处罚、行政强制等措施的，说明设定该项措施的必要性、法律依据及对经济和社会可能产生的影响； （四）起草部门完成时间和进度安排； （五）其他需要说明的问题。"},{"i":10,"n":"第十条","txt":"政策法规司应当对立项建议进行评估论证，与有关部门充分沟通，提出予以立项或者不予立项的意见。"},{"i":11,"n":"第十一条","txt":"政策法规司编制完成总局年度立法计划后，应当将计划及其说明报总局党组会议审议通过后向社会公布。"},{"i":12,"n":"第十二条","txt":"年度立法计划包括以下两类立法项目： （一）一档项目，指调研论证充分、立法条件成熟、立法草案已经报送政策法规司审查、可以在计划年度内提交总局局务会议审议的项目和为贯彻落实党中央、国务院的决策部署，应当在计划年度内提交总局局务会议审议的项目； （二）二档项目，指尚需进一步调研论证或者意见分歧较大的项目。 年度立法计划应当明确立法项目的起草负责部门和工作时限。法律、行政法规和总局局长交办的规章由政策法规司组织起草。其他规章根据职责分工确定相应起草部门；不能确定起草部门的，由总局局长指定。"},{"i":13,"n":"第十三条","txt":"对列入年度立法计划的项目，起草部门应当按照计划执行；政策法规司应当及时跟踪了解计划实施情况，加强组织协调和督促指导。 年度立法计划执行过程中，有关部门根据实际工作情况，认为需要调整个别立法项目的，应当按照本规定第七条至第九条的要求向政策法规司提出调整建议，由政策法规司审核后报总局局长批准。"},{"i":14,"n":"第十四条","txt":"法律、行政法规的立项申请符合有关要求的，经总局局长批准后报送全国人大常委会、国务院。 与国务院相关部门联合制定规章的立项申请，涉及公众权益、社会关注度高等事项的，由提出立项申请的总局部门或者政策法规司报总局局长批准后报国务院审核同意。"},{"i":15,"n":"第十五条","txt":"起草部门应当按照年度立法计划的要求制定工作方案，确定专人或者成立工作小组从事起草工作。 起草法律、行政法规，应当成立领导小组和工作小组。领导小组的组长由总局局长担任。工作小组的组长、副组长由政策法规司和相关部门主要负责人担任，成员由政策法规司和相关部门人员共同组成。人员应当相对固定，并配备必要的资金。原则上应当成立专家咨询小组。 起草专业性较强的法律、行政法规、规章，可以吸收相关领域的专家、总局法律顾问、公职律师参与工作，或者委托有关单位、专家组织起草。"},{"i":16,"n":"第十六条","txt":"起草法律、行政法规、规章，应当深入调查研究，了解行业发展、监管、服务等方面的现状和问题，借鉴国内外成熟立法经验，保障立法草案质量。 起草规章，原则上不再重复法律、行政法规已经明确规定的内容。"},{"i":17,"n":"第十七条","txt":"立法草案应当符合立法用语、形式和技术规范，框架结构严谨，逻辑严密，层次清楚，条文明确、具体，用语准确、简洁，具有可操作性。"},{"i":18,"n":"第十八条","txt":"起草部门应当采取书面征求意见、座谈会、论证会、实地调研等多种形式，广泛听取人大代表、政协委员、广播电视系统从业主体、行业协会、商会、行政相对人等方面意见。 法律、行政法规、规章草案涉及社会公众普遍关注的热点难点问题等事项的，起草部门应当依法开展论证咨询；涉及重大利益调整或者存在重大意见分歧等事项的，应当依法举行听证会。 法律、行政法规、规章草案涉及突出矛盾解决、重大制度调整的，或者影响重大公共利益和公众权益、容易引发社会稳定等问题的，或者可能在国内外造成较大舆论影响的，起草部门应当报总局党组会议审议决定，依法进行风险评估，并做好相关应对工作。"},{"i":19,"n":"第十九条","txt":"法律、行政法规、规章草案涉及总局其他部门职责或者与国务院其他部门关系紧密的，起草部门应当征求该部门意见并进行充分协商。"},{"i":20,"n":"第二十条","txt":"法律、行政法规、规章草案涉及需要国务院决策的重大问题的，起草部门应当拟定解决方案，提请总局局务会议审议后报国务院决定。"},{"i":21,"n":"第二十一条","txt":"起草部门应当认真研究、吸收各方面意见，对法律、行政法规、规章草案进行修改并形成起草说明。 起草说明应当包括以下内容： （一）立法的必要性，包括管理现状、拟通过立法解决的主要问题等； （二）立法依据； （三）起草过程； （四）拟确立的主要制度和措施； （五）征求、协调意见情况，对重大原则问题不能取得一致意见的，应当说明具体情况和取舍理由； （六）现行有关的法律、行政法规、规章是否需要修改或者废止； （七）起草部门的初步公平竞争审查意见； （八）需要说明的其他问题。 起草说明应当附具有关材料，包括意见汇总、听证会笔录、调研报告、风险评估报告、国内外有关立法资料等。"},{"i":22,"n":"第二十二条","txt":"其他部门负责规章起草的，应当将规章草案送审稿（以下简称规章送审稿）及其说明等材料送政策法规司审查。 规章送审稿及其说明应当由起草部门主要负责人签署；多个起草部门共同起草的，应当由相关部门主要负责人共同签署。"},{"i":23,"n":"第二十三条","txt":"政策法规司主要从以下方面对规章送审稿进行审查： （一）是否符合法定权限和程序； （二）是否符合宪法的精神和原则； （三）是否符合社会主义核心价值观的要求； （四）是否符合法律、行政法规和其他上位法的要求，特别是是否存在违法设定行政许可、行政处罚、行政强制等措施的情况； （五）是否适应改革发展要求，有效解决相关领域存在的问题； （六）是否存在排除、限制公平竞争的情况； （七）是否存在应由市场调节、企业和社会自律、公民自我管理的事项； （八）是否正确处理各方面的意见，合理调整行政相对人和相关方的权利义务关系； （九）是否符合立法技术要求； （十）需要审查的其他内容。"},{"i":24,"n":"第二十四条","txt":"规章送审稿有下列情形之一的，政策法规司可以缓办或者退回起草部门： （一）立法基本条件尚不成熟或者发生重大变化的； （二）起草工作或者送审材料不符合本规定第十七条至第二十一条规定的。"},{"i":25,"n":"第二十五条","txt":"起草行政法规、规章草案或者审查规章送审稿，除依法需要保密的外，政策法规司应当将草案、送审稿及其说明等材料向社会公开征求意见，期限一般不少于 30 日。"},{"i":26,"n":"第二十六条","txt":"规章送审稿涉及重大利益调整或者存在重大意见分歧的，政策法规司应当组织座谈会、专家论证会、听证会、委托研究等进行论证咨询。 规章送审稿在起草过程中应当进行而未进行听证的，政策法规司报总局领导批准后，依法举行听证会。"},{"i":27,"n":"第二十七条","txt":"对规章送审稿中涉及的主要措施、管理体制、权限分工等问题有不同意见的，政策法规司应当进行协调。经协调仍达不成一致意见的，政策法规司应当提出倾向性意见报总局领导协调、决定。"},{"i":28,"n":"第二十八条","txt":"根据审查情况，政策法规司会同起草部门对规章送审稿进行修改，形成草案及其说明，由政策法规司和起草部门主要负责人签署后，提请总局局务会议审议。 法律、行政法规和由政策法规司负责起草的规章草案及其说明，由政策法规司主要负责人签署，提请总局局务会议审议。"},{"i":29,"n":"第二十九条","txt":"法律、行政法规、规章草案应当经总局局务会议审议决定。 总局局务会议审议法律、行政法规、规章草案时，由政策法规司主要负责人作说明。"},{"i":30,"n":"第三十条","txt":"总局局务会议审议通过法律、行政法规、规章草案及其说明后，政策法规司会同有关部门根据审议意见对草案及其说明进行修改后，报总局局长签发。其中法律、行政法规形成送审稿及其说明，依法报全国人大常委会审议、国务院审查，规章以总局令形式公布。 规章草案涉及对外开放的方针性、政策性、原则性的制度设定或者调整的，专门规范外国人和外国企业、组织及其活动的制度设定或者调整的，以及在制定过程中有关方面意见分歧较大的，应当在正式公布前向国务院请示报告。 公布规章的总局令应当载明该规章的序号、名称、通过日期、公布日期、施行日期以及总局局长署名等。"},{"i":31,"n":"第三十一条","txt":"总局与国务院相关部门联合公布的规章，应当在草案经总局局务会议审议通过并由总局局长签发后送联合发布的部门签发。 由国务院其他部门主办并与总局联合公布的规章，由政策法规司会同相关部门审查后报总局局长签发。 联合公布的规章由总局局长及联合制定部门的首长共同署名公布，使用主办机关的命令序号。"},{"i":32,"n":"第三十二条","txt":"规章原则上应当自公布之日起30日后施行。"},{"i":33,"n":"第三十三条","txt":"规章签署公布后7日内，政策法规司应当将规章正式文本送总局网站指定栏目刊载，并按照有关规定送国务院公报、中国政府法制信息网和在全国范围内发行的报纸上刊载。 政策法规司可以会同有关部门，通过新闻发言人等形式，对规章的制定背景、起草情况、主要内容等进行解读，做好宣传贯彻落实工作，避免或者回应误解误读情况，并主动收集社会舆情进行分析研究。"},{"i":34,"n":"第三十四条","txt":"政策法规司应当在规章公布后 30 日内，依法向国务院办理备案手续。"},{"i":35,"n":"第三十五条","txt":"全国人大常委会、国务院要求就法律、行政法规条文提出解释意见，或者总局认为需要进一步明确含义、界限或者作出补充规定的，由政策法规司会同有关部门提出意见，经总局领导签发后，报该法律、行政法规制定机关作出解释。"},{"i":36,"n":"第三十六条","txt":"行政工作中涉及法律、行政法规的具体应用问题，由有关司局提出意见初稿，经政策法规司审查，报总局领导同意后，以总局发文形式公布，必要时可以请求全国人大常委会有关部门或者国务院法制机构解释。"},{"i":37,"n":"第三十七条","txt":"规章有下列情形之一的，由总局负责解释： （一）规章的规定需要进一步明确具体含义的； （二）规章制定后出现新的情况，需要明确适用依据的。"},{"i":38,"n":"第三十八条","txt":"规章解释由政策法规司会同起草部门提出意见，报总局领导批准后公布。 规章的解释与规章具有同等效力。"},{"i":39,"n":"第三十九条","txt":"政策法规司负责法律、行政法规和规章的汇编工作。"},{"i":40,"n":"第四十条","txt":"政策法规司应当会同有关部门，对规章进行立法后评估，并把评估结果作为解释、修改、废止规章的重要参考。 政策法规司应当会同总局有关部门，根据全面深化改革、全面依法治国要求和经济社会发展需求，以及上位法制定、修改、废止情况，及时对规章进行清理，并根据清理情况及时解释、修改、废止相关规章。"},{"i":41,"n":"第四十一条","txt":"规章有下列情形之一的，应当予以修改： （一）与法律、行政法规等上位法不一致，应当作出相应修改的； （二）基于政策或者客观实际的需要，有必要调整相关内容的； （三）同一事项在两个以上规章中规定不一致的； （四）其他应予修改的情形。"},{"i":42,"n":"第四十二条","txt":"规章有下列情形之一的，应当予以废止： （一）因有关法律、行政法规等上位法废止或者修改，立法依据缺失的； （二）不适应全面深化改革、全面依法治国要求和经济社会发展需要的； （三）规定的事项已执行完毕或者因实际情况变化，没有必要继续执行的； （四）对同一事项已做出新规定的； （五）其他应予废止的情形。"},{"i":43,"n":"第四十三条","txt":"规章清理结果应当提请总局局务会议审议。清理后继续有效、废止和失效的规章目录，应当向社会公布。 规章清理、修改、废止程序适用本规定第三章、第四章的有关规定。"},{"i":44,"n":"第四十四条","txt":"规章文本的外文翻译工作由政策法规司组织。 规章公布后30日内，起草部门应当将外文译本送审稿送政策法规司。政策法规司应当组织专家进行审查，报总局领导审定后向社会公布。规章以中文文本为标准文本。"},{"i":45,"n":"第四十五条","txt":"各省、自治区、直辖市人民政府广播电视主管部门可以参照本规定，制定本部门的立法工作规定。"},{"i":46,"n":"第四十六条","txt":"本规定自2020年3月1日起施行，2004年6月18日国家广播电影电视总局发布的《广播电影电视立法程序规定》（国家广播电影电视总局令第 23 号）同时废止。"}],"guojiaguangbodianshizongjuxingzhengguifanxingwenji30bdd0":[{"i":1,"n":"第一条","txt":"为了规范国家广播电视总局（以下简称总局）行政规范性文件（以下简称规范性文件）制定工作，全面推进总局依法行政，根据国务院关于法治政府建设的相关规定，结合总局实际情况，制定本规定。"},{"i":2,"n":"第二条","txt":"总局规范性文件的起草、合法性审核、集体审议、发布、清理等事项，适用本规定。 本规定所称总局规范性文件，是指除规章以外，总局为执行有关法律、行政法规、规章和上级文件，依照法定权限、程序制定，涉及公民、法人和其他组织权利义务，具有普遍约束力，在一定期限内反复适用，并以总局名义公开发布的文件。 总局各部门不得以本部门名义发布规范性文件。"},{"i":3,"n":"第三条","txt":"规范性文件制定工作应当坚持和加强党的全面领导，增强“四个意识”，坚定“四个自信”，做到“两个维护”，全面贯彻落实党的路线方针政策和决策部署，切实推动党的宣传思想方针政策通过法定程序成为国家意志。 规范性文件制定工作应当坚持科学、民主、依法，及时准确反映改革发展要求，积极引导公民、法人和其他组织有序参与、表达意见，维护社会主义法制统一，不断提高文件质量和效率。 规范性文件制定工作应当将社会主义核心价值观融入全过程，推动德法统一，推进行业治理体系和治理能力现代化。 规范性文件制定工作应当落实党管意识形态原则，巩固马克思主义在意识形态领域的指导地位，体现属地管理、分级负责和谁主管谁负责等管理原则。"},{"i":4,"n":"第四条","txt":"总局将规范性文件制定和监督管理工作纳入法治政府建设督察内容，作为依法行政考核内容列入法治政府建设考评指标体系，并建立督察情况通报制度。"},{"i":5,"n":"第五条","txt":"总局各部门按照法定职能和意识形态工作责任分工，负责相应规范性文件起草等工作；不能确定起草部门的，由总局领导指定。 政策法规司负责对规范性文件进行合法性审核、清理等工作。 办公厅应当加强规范性文件管理信息化建设，对规范性文件进行统一登记、统一编号、统一发布。"},{"i":6,"n":"第六条","txt":"起草部门应当对所制定规范性文件的合法性、必要性、科学性、可行性、可控性进行全面论证。 法律、行政法规、规章和上级文件已经作出明确规定的，现行规范性文件已有具体规定并且仍然适用的，不得重复制定规范性文件。"},{"i":7,"n":"第七条","txt":"制定规范性文件，应当讲求实际效果，注重针对性和可操作性，并严格文字把关，确保政策措施表述严谨、文字精练、准确无误。 规范性文件不得规定下列事项： （一）增加法律、行政法规、总局规章规定之外的行政权力事项或者减少法定职责； （二）设定行政许可、行政处罚、行政强制、行政征收、行政收费等事项，增加办理行政许可事项的条件，规定出具循环证明、重复证明、无谓证明的内容； （三）减损公民、法人和其他组织的合法权益或者增加其义务，侵犯公民人身权、财产权、人格权、劳动权、休息权等基本权利； （四）含有排除或者限制公平竞争内容、违法干预或者影响市场主体正常生产经营活动的措施，或者违法设置市场准入和退出条件等； （五）规定应由市场调节、企业和社会自律、公民自我管理的事项。"},{"i":8,"n":"第八条","txt":"规范性文件涉及总局其他部门职责的，起草部门应当与有关部门进行充分协商。 规范性文件涉及国务院其他部门职责或者与国务院其他部门关系紧密的，起草部门应当征求该部门意见或者取得其同意。其中，涉及社会公众权益、社会舆论高度关注的，起草部门应当在总局党组会议审议后，向党中央、国务院请示报告。"},{"i":9,"n":"第九条","txt":"起草部门应当对规范性文件中有关行政措施的预期效果和可能产生的影响进行评估，对专业性、技术性较强的内容组织专家论证，并应当在起草说明中写明评估论证结论，作为制定规范性文件的重要依据。"},{"i":10,"n":"第十条","txt":"起草部门应当充分听取地方广播电视主管部门、行业组织、社会团体、行政相对人和社会公众特别是利益相关方的意见；必要时，应当通过召开座谈会、听证会，实地走访等形式充分听取意见。 除依法需要保密或者不宜公开的外，规范性文件涉及重大公共利益或者对公众权益有重大影响的，应当向社会公开征求意见，期限一般不少于15日。起草部门应当通过总局网站、广播电视媒体和政务新媒体等便于群众知晓的方式，公布规范性文件草案及其说明等材料，并明确提出意见的方式和期限。 规范性文件涉及突出矛盾解决、重大制度调整的，或者影响重大公共利益和公众权益、容易引发社会稳定问题的，或者可能在国内外造成较大舆论影响的，起草部门应当在公开征求意见前报总局党组会议审议决定，依法进行风险评估，并做好相关应对工作。"},{"i":11,"n":"第十一条","txt":"规范性文件草案送审稿经起草部门主要负责人签署后，送政策法规司进行合法性审核。不得以征求意见、会签、参加审议等方式代替合法性审核。 送审材料应当包括以下内容： （一）规范性文件草案送审稿及其说明； （二）法律、行政法规、规章和上级文件等制定依据； （三）征求意见及意见采纳情况； （四）起草部门初步的合法性审核和公平竞争审查意见； （五）针对不同审核内容需要的其他材料。"},{"i":12,"n":"第十二条","txt":"起草部门直接将规范性文件草案送审稿等材料送办公厅的，办公厅应当对所送材料的完备性、规范性进行审核。符合要求的，转送政策法规司进行审核；不符合要求的，可以退回，或者要求起草部门在 3 个工作日内补齐材料或者说明情况后送政策法规司进行合法性审核。"},{"i":13,"n":"第十三条","txt":"政策法规司主要从以下方面对规范性文件草案送审稿进行合法性审核： （一）是否超越制定机关法定职权； （二）是否符合宪法的精神和原则； （三）是否符合社会主义核心价值观的要求； （四）是否符合法律、行政法规、总局规章和其他上位法的规定，是否与相关规范性文件相协调、衔接； （五）是否属于执行有关法律、行政法规、规章和上级文件且需要制定规范性文件的事项； （六）是否存在违法设定行政许可、行政处罚、行政强制、行政征收、行政收费以及其他不得由规范性文件设定措施的情况； （七）是否存在没有法律、行政法规依据，减损公民、法人和其他组织权利或者增加其义务的规定，以及增加本部门权力或者减少本部门法定职责的情况； （八）是否存在排除、限制公平竞争的情况； （九）是否符合规范性文件制定程序； （十）需要审核的其他内容。"},{"i":14,"n":"第十四条","txt":"政策法规司建立健全专家协助审核机制，在规范性文件合法性审核过程中充分发挥总局法律顾问、公职律师和有关专家的作用。"},{"i":15,"n":"第十五条","txt":"规范性文件影响面广、情况复杂、社会高度关注，或者存在疑难法律问题的，政策法规司应当在书面征求意见的基础上，采取召开座谈会、论证会等方式听取利益相关方、有关专家等方面意见。"},{"i":16,"n":"第十六条","txt":"除为了预防、应对和处置突发事件，或者执行上级机关的紧急命令和决定需要立即制定实施规范性文件等情形外，合法性审核的时限一般不少于5个工作日，最长不超过15个工作日。"},{"i":17,"n":"第十七条","txt":"政策法规司应当根据合法性审核结果，提出合法、不合法或者应当予以修改的审核意见。 起草部门应当根据审核意见对规范性文件进行必要的修改或者补充；特殊情况下起草部门未完全采纳审核意见的，应当在提请总局局务会议集体审议时详细说明理由和依据。 未经合法性审核或者经审核不合法的规范性文件，不得提交集体审议。"},{"i":18,"n":"第十八条","txt":"规范性文件经审核合法的，由起草部门与政策法规司会签后，报总局局务会议集体审议，审议通过后由分管副局长审阅后报局长签发。 规范性文件经过集体审议后需要进行重大修改的，应当在修改后重新进行合法性审核。"},{"i":19,"n":"第十九条","txt":"规范性文件经总局局长签发后，以总局名义对外公开发布。 规范性文件涉及对外开放的方针性、政策性、原则性的制度设定或者调整的，专门规范外国人和外国企业、组织及其活动的制度设定或者调整的，以及在制定过程中有关方面意见分歧较大的，应当在正式发布前向党中央、国务院请示报告。 规范性文件涉及重大公共利益，公民、法人和其他组织重大权益，社会高度关注或者可能影响政府形象的，起草部门应当进行发布时机评估工作。 规范性文件发布后5个工作日内，起草部门应当将规范性文件正式文本送总局网站指定栏目刊载。 未经公开发布的规范性文件不得作为行政管理依据。"},{"i":20,"n":"第二十条","txt":"规范性文件发布后10个工作日内，起草部门应当将规范性文件正式文本5份及电子文本送政策法规司备案。总局各部门应当于每年1月向政策法规司报送上一年度发布的规范性文件目录。 起草部门可以会同政策法规司，通过新闻发言人等形式，对规范性文件的制定背景、起草情况、主要内容等进行解读，做好宣传贯彻落实工作，避免或者回应误解误读情况，并主动收集社会舆情进行分析研究。 办公厅负责规范性文件的汇编工作。"},{"i":21,"n":"第二十一条","txt":"起草部门应当适时对规范性文件的执行情况、实施效果、存在问题等进行评估，并根据评估结果开展规范性文件解释、修改、废止工作，需要上升为法律规定的，应当及时启动相关工作。"},{"i":22,"n":"第二十二条","txt":"政策法规司应当会同总局有关部门，根据全面深化改革、全面依法治国要求和经济社会发展需要，以及上位法制定、修改、废止情况，及时对规范性文件进行清理，并根据清理情况及时解释、修改、废止相关规范性文件。"},{"i":23,"n":"第二十三条","txt":"规范性文件有下列情形之一的，应当予以解释： （一）规范性文件的规定需要进一步明确具体含义的； （二）规范性文件制定后出现新的情况，需要明确适用依据的。"},{"i":24,"n":"第二十四条","txt":"规范性文件有下列情形之一的，应当予以修改： （一）与法律、行政法规、总局规章等上位法不一致，应当作出相应修改的； （二）基于政策或者客观实际的需要，有必要调整相关内容的； （三）同一事项在两个以上规范性文件中规定不一致的； （四）其他应予修改的情形。"},{"i":25,"n":"第二十五条","txt":"规范性文件有下列情形之一的，应当予以废止： （一）因有关法律、行政法规等上位法废止或者修改，立法依据缺失的； （二）不适应全面深化改革、全面依法治国要求和经济社会发展需要的； （三）规定的事项已执行完毕或者因实际情况变化，没有必要继续执行的； （四）对同一事项已有新规定的； （五）其他应予废止的情形。"},{"i":26,"n":"第二十六条","txt":"规范性文件的解释、修改或者废止由起草部门会同政策法规司提出意见，报总局局务会议审议决定。 规范性文件定期清理结果应当报总局局务会议审议。 清理后继续有效、废止和失效的规范性文件目录，应当向社会公布。"},{"i":27,"n":"第二十七条","txt":"各省、自治区、直辖市人民政府广播电视主管部门可以参照本规定，制定本部门的规范性文件管理规定。"},{"i":28,"n":"第二十八条","txt":"本规定自2020年3月1日起施行，2010年12月6日国家广播电影电视总局发布的《广电总局关于进一步规范发文提高依法行政能力的通知》（广局[2010]543号）同时废止。"}],"jingwaiweixingdianshipindaoluodiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对通过卫星方式传送的境外电视频道（以下简称境外卫星电视频道）在中国境内落地的管理，制定本办法。"},{"i":2,"n":"第二条","txt":"国务院广播电视行政部门负责对境外卫星电视频道落地实行归口管理，对境外卫星电视频道落地实行审批制度。"},{"i":3,"n":"第三条","txt":"经广电总局批准，境外卫星电视频道可以在三星级以上涉外宾馆饭店、专供境外人士办公居住的涉外公寓等规定的范围及其他特定的范围落地。"},{"i":4,"n":"第四条","txt":"申请落地的境外卫星电视频道，应具备下列条件： （一）所播放的内容不违反中国法律、法规、规章的规定； （二）在本国（地区）为合法电视媒体； （三）具备与中国广播电视互利互惠合作的综合实力，承诺并积极协助中国广播电视节目在境外落地； （四）申请落地的频道及其直接相关机构对中国友好，与中国有长期友好的广播电视交流和合作； （五）同意通过广电总局指定的机构（以下简称指定机构）统一定向传送其频道节目，承诺不通过其他途径在中国境内落地； （六）同意并委托指定机构独家代理其在中国境内落地的所有相关事宜。"},{"i":5,"n":"第五条","txt":"广电总局每年审批一次境外卫星电视频道落地申请，每次有效期限一年，一般在每年七月至九月办理。"},{"i":6,"n":"第六条","txt":"对于一个境外广播电视机构，原则上只批准其所属的一个卫星电视频道在规定的范围内落地；原则上不批准新闻类境外卫星电视频道在境内落地；不批准境内广播电视机构及其他有关部门、团体、企业、个人在境外开办、合办的卫星电视频道在境内落地。特殊情况，须报广电总局特殊批准。"},{"i":7,"n":"第七条","txt":"申请境外卫星电视频道落地，由指定机构向广电总局提出。 指定机构在申请前，应对拟代理落地的境外卫星电视频道是否具备第四条规定的条件、代理的技术条件等进行评估，并将有关工作情况报广电总局。广电总局对是否同意指定机构与该境外卫星电视频道洽商落地事宜提出意见，不同意洽商的，广电总局不受理指定机构的该项申请。"},{"i":8,"n":"第八条","txt":"指定机构申请境外卫星电视频道落地，应提交： （一）该境外卫星电视频道填写的《卫星电视频道备忘录》； （二）该境外卫星电视频道提供的符合本办法第四条和第六条规定内容的证明材料以及解码器等收视装置。有关材料应以中文书写，以其他文字书写的，应附中文译本，并以中文译本为准； （三）指定机构的评估报告； （四）指定机构与境外卫星电视频道签署的合作协议。"},{"i":9,"n":"第九条","txt":"广电总局对符合本办法第四条和第六条规定条件的境外卫星电视频道，应依照行政许可法规定的期限作出是否准予落地的决定。"},{"i":10,"n":"第十条","txt":"经批准落地的境外卫星电视频道，必须遵守中国有关境外卫星电视管理的各项规定。"},{"i":11,"n":"第十一条","txt":"经批准落地的境外卫星电视频道，应按照指定机构的要求相应调整原卫星信号的播出覆盖范围、方式等；履行与指定机构的协议；不得擅自在中国境内开展其电视频道及其品牌和有关接收设备的推广活动。"},{"i":12,"n":"第十二条","txt":"经批准落地的境外卫星电视频道，禁止播放载有下列内容的节目： （一）危害中国国家统一、主权和领土完整的； （二）危害中国国家安全，损害中国荣誉和利益，泄露中国国家秘密的； （三）煽动中国民族分裂、民族仇恨、民族歧视，破坏中国民族团结，侵害中国民族风俗习惯的； （四）危害中国社会稳定，宣扬淫秽、暴力、迷信、邪教，教唆犯罪的； （五）诽谤、侮辱他人，侵犯他人合法权益的； （六）危害中国社会公德，诋毁中华民族优秀文化传统的； （七）其他违反中国法律、法规、规章规定的。"},{"i":13,"n":"第十三条","txt":"经批准落地的境外卫星电视频道的下列事项变更，须事先向指定机构通报协商，并由指定机构报广电总局： （一）频道及其直接相关机构的股份结构、经营权、投资人、主要管理人员的变化； （二）频道名称、频道类别、节目构成、播音语言、字幕等《卫星电视频道备忘录》所列重要事项的改变； （三）频道播出信号加密与否的变化、信号传送卫星及其覆盖区域等有关技术参数的变化； （四）涉及本办法第四条和第六条规定内容事项的变更。 广电总局认为因上述事项变更，经批准落地的频道已不符合本办法规定的，可予以相应处理直至停止其落地资格。"},{"i":14,"n":"第十四条","txt":"各级广播电视行政部门依照《卫星电视广播地面接收设施管理规定》（国务院第129号令）及有关规定，管理有关境外卫星电视的接收活动。"},{"i":15,"n":"第十五条","txt":"指定机构应采取必要的措施，协助广播电视行政部门对所代理的境外卫星电视频道的有关行为和播放内容进行监督，配合广电总局实施相关处理，对所发现的问题及时报告。 经批准落地的境外卫星电视频道播出违反本办法第十二条规定内容的，指定机构应即时停止违规内容的传送。"},{"i":16,"n":"第十六条","txt":"经批准落地的境外卫星电视频道违反本办法规定，情节轻微的，由广电总局给予警告，要求其陈述情况和纠正；情节严重的，暂停其特定内容传送、暂停或取消有关频道落地资格。"},{"i":17,"n":"第十七条","txt":"经批准落地的境外卫星电视频道造成不良影响的，除接受相应处理外，应按照广电总局的要求在相同的传播范围内消除不良影响。"},{"i":18,"n":"第十八条","txt":"经广电总局批准在境内特定地区落地的境外电视频道，参照本办法管理。"},{"i":19,"n":"第十九条","txt":"本办法自2004年8月1日起施行。广电总局《境外卫星电视频道落地管理办法》（广电总局令第22号）同时废止。"}],"jingwaijigoushelizhuhuaguangbodianshibanshijigougu811e89":[{"i":1,"n":"第一条","txt":"为规范境外机构设立驻华广播电视办事机构的管理，促进中外广播电视交流活动，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于外国及香港特别行政区、澳门特别行政区和台湾地区的机构（以下简称境外机构）在华设立广播电视办事机构的活动。"},{"i":3,"n":"第三条","txt":"境外机构不得在中国境内设立广播电视代理机构或编辑部。"},{"i":4,"n":"第四条","txt":"国家对境外机构设立驻华广播电视办事机构（以下简称驻华办事机构）实行许可制度。 未经国务院广播电视行政部门许可，不得擅自设立驻华办事机构。"},{"i":5,"n":"第五条","txt":"境外机构申请设立驻华办事机构，应当具备下列条件： （一）申请机构在所在国（地）为合法存续的机构； （二）申请机构对中国友好，具有良好信誉； （三）业务范围符合中国法律、行政法规、规章的规定和申请设立的目的。"},{"i":6,"n":"第六条","txt":"申请设立驻华办事机构，需向广电总局提交以下书面材料： （一）申请机构法定代表人签署的申请书，内容包括：该机构简况、设立驻华办事机构的目的、驻华办事机构的名称、派驻人员（首席代表、代表）、业务范围、驻在期限、办公地址等； （二）申请机构在所在国（地）合法存续的证明； （三）银行出具的资信证明； （四）由申请机构法定代表人签署的委任驻华办事机构首席代表和代表的授权书、首席代表和代表的简历及身份证件复印件。"},{"i":7,"n":"第七条","txt":"驻华办事机构的首席代表或代表，应当是符合下列条件之一的人员： （一）持合法普通护照的外国公民（不含外国在中国的留学生）； （二）在境外已经获得长期居住资格的中国内地公民； （三）持有效身份证件的香港、澳门、台湾人员。 聘请除本条第一款第二项规定外的中国公民任首席代表或代表的，应当委托当地外事服务单位或中国政府指定的其他单位，根据中国有关法律法规办理申报手续。"},{"i":8,"n":"第八条","txt":"驻华办事机构名称应以申请机构国别（地区）+申请机构名称+在华所驻城市名+办事处的方式确定。"},{"i":9,"n":"第九条","txt":"广电总局对提出的申请进行审查时，需要征求相关部门意见的，应征求意见并依照行政许可法规定的期限作出批准或不予批准的决定。不予批准的，应当说明理由。 批准同意的，由办事机构的首席代表向广电总局领取批准文件，持批准文件等材料到工商、公安等部门办理登记注册等相关手续后，方可开展业务活动。"},{"i":10,"n":"第十条","txt":"驻华办事机构批准文件的有效期为三年。期满如需延期，应在有效期届满三十日前向广电总局提出延期申请。"},{"i":11,"n":"第十一条","txt":"境外机构申请驻华办事机构延期，应当提交以下材料： （一）由境外机构法定代表人签署的延期申请书； （二）该驻华办事机构在前一个驻在期内的业务活动情况； （三）银行出具的资信证明； （四）境外机构在所在国（地）合法存续的证明。"},{"i":12,"n":"第十二条","txt":"境外机构要求变更驻华办事机构的名称，更换或增加首席代表或代表，变更办事机构业务范围、驻在期限或办公地址，需由境外机构法定代表人签署申请书（变更办公地址的申请书可由办事机构首席代表签署）报广电总局批准。"},{"i":13,"n":"第十三条","txt":"驻华办事机构的延期、变更申请获得批准后，持批准文件到工商、公安等行政部门办理延期、变更手续。"},{"i":14,"n":"第十四条","txt":"驻华办事机构期限届满、提前终止业务活动或境外机构申请撤销驻华办事机构的，应报原审批机关备案并办理其他注销手续。"},{"i":15,"n":"第十五条","txt":"所有申报材料，应以中文书写。如用其他文字书写，应当附中文译本。 中文译本与原文理解不一致的，以中文译本为准。 审批机关在必要时有权要求境外机构就其全部或部分申报材料提交经所在国（地区）公证的证明，并经中华人民共和国驻该国使领馆、中央政府驻香港、驻澳门机构认证。"},{"i":16,"n":"第十六条","txt":"境外机构对其驻华办事机构在中国境内的一切业务活动，承担法律责任。 驻华办事机构及成员必须遵守中国的法律、法规、规章等规定，按批准的业务范围开展活动。"},{"i":17,"n":"第十七条","txt":"驻华办事机构应按要求每年向广电总局书面报告业务活动情况。 对设在京外的驻华办事机构，当地省级广播电视行政部门应对其开展业务的活动进行监督管理。"},{"i":18,"n":"第十八条","txt":"驻华办事机构违反中国法律、法规等规定的，有关部门依法给予警告、责令暂停业务、撤销办事机构等处罚。"},{"i":19,"n":"第十九条","txt":"本规定自2004年8月1日起施行。"}],"jingwaidianshijiemuyinjinbochuguanliguiding":[{"i":1,"n":"第一条","txt":"为规范引进、播出境外电视节目的管理，促进中外广播电视交流，满足人民群众精神文化生活的需要，根据《广播电视管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于境外电视节目的引进、播出活动。境外电视节目是指供电视台播出的境外电影、电视剧（电视动画片）（以下称境外影视剧）及教育、科学、文化等其他各类电视节目（以下称其他境外电视节目）。 不引进时事性新闻节目。"},{"i":3,"n":"第三条","txt":"国家广播电影电视总局（以下称广电总局）负责境外影视剧引进和以卫星传送方式引进境外其他电视节目的审批工作。 省级广播电视行政部门受广电总局委托，负责本辖区内境外影视剧引进的初审工作和其他境外电视节目引进的审批和播出监管工作。 地（市）级广播电视行政部门负责本辖区内播出境外电视节目的监管工作。"},{"i":4,"n":"第四条","txt":"未经广电总局和受其委托的广播电视行政部门审批的境外电视节目，不得引进、播出。"},{"i":5,"n":"第五条","txt":"引进境外影视剧和以卫星传送方式引进其他境外电视节目，由广电总局指定的单位申报。"},{"i":6,"n":"第六条","txt":"广电总局对引进境外影视剧的总量、题材和产地等进行调控和规划。"},{"i":7,"n":"第七条","txt":"引进境外影视剧和以卫星传送方式引进其他境外电视节目，应符合广电总局的总体规划和本规定第十五条的要求。"},{"i":8,"n":"第八条","txt":"引进境外影视剧和以卫星传送方式引进其他境外电视节目，由引进单位向省级广播电视行政部门提出申请。"},{"i":9,"n":"第九条","txt":"申请引进境外影视剧，应提交下列材料： （一）《引进境外影视剧申请表》（申请表由广电总局统一制定，省级广播电视行政部门凭样本印制使用）； （二）引进合同（中外文）； （三）版权证明（中外文）； （四）具备完整的图像、声音、时码的大1／2录像带一套； （五）每集不少于300字的剧情梗概； （六）与样带字幕一致的片头、片尾中外文字幕。"},{"i":10,"n":"第十条","txt":"申请以卫星传送方式引进其他境外电视节目，应提交下列材料： （一）《引进其他境外电视节目申请表》（申请表由广电总局统一制定，省级广播电视行政部门凭样本印制使用）； （二）引进合同（中外文）； （三）版权证明。"},{"i":11,"n":"第十一条","txt":"引进境外影视剧和以卫星传送方式引进其他境外电视节目的，省级广播电视行政部门正式受理申请后，应在行政许可法规定的期限内作出详细、明确的初审意见，报广电总局审查批准。 广电总局正式受理申请后，在行政许可法规定的期限内作出同意或不同意引进的行政许可决定。其中，引进境外影视剧的审查需要另行组织专家评审，评审时间为三十日。同意引进的，发给《电视剧（电视动画片）发行许可证》或同意以卫星传送方式引进其他境外电视节目的批复；不同意引进的，应当书面通知引进单位并说明理由。"},{"i":12,"n":"第十二条","txt":"同意以卫星传送方式引进其他境外电视节目的，引进单位凭广电总局批复办理《接收卫星传送的电视节目许可证》等相关手续。"},{"i":13,"n":"第十三条","txt":"地（市）级电视台、省级电视台申请引进其他境外电视节目，报省级广播电视行政部门审查批准；题材涉及重大、敏感内容的，由省级广播电视行政部门报广电总局审批。"},{"i":14,"n":"第十四条","txt":"引进其他境外电视节目，应提交下列申请材料： （一）《引进其他境外电视节目申请表》（申请表由广电总局统一制定，地（市）级以上广播电视行政部门凭样本印制使用）； （二）引进单位对节目内容的审查意见； （三）引进合同（中外文）； （四）版权证明。 省级广播电视行政部门正式受理申请后，应在行政许可法规定的期限内作出行政许可决定。同意引进的，发给相关的批准文件；不同意引进的，应当书面通知送审单位并说明理由。"},{"i":15,"n":"第十五条","txt":"引进境外电视节目应严格把握导向和格调，确保内容健康、制作精良。 境外电视节目中不得载有以下内容： （一）反对中国宪法确定的基本原则的； （二）危害中国国家统一、主权和领土完整的； （三）泄露中国国家秘密、危害中国国家安全或者损害中国荣誉和利益的； （四）煽动中国民族仇恨、民族歧视，破坏中国民族团结，或者侵害中国民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱中国社会秩序，破坏中国社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害中国社会公德或者中国民族优秀文化传统的； （十）其他违反中国法律、法规、规章规定的内容。"},{"i":16,"n":"第十六条","txt":"省级广播电视行政部门应于每季度第一周将上季度本辖区引进其他境外电视节目的情况报广电总局备案。"},{"i":17,"n":"第十七条","txt":"经批准引进的其他境外电视节目，应当重新包装、编辑，不得直接作为栏目在固定时段播出。节目中不得出现境外频道台标或相关文字的画面，不得出现宣传境外媒体频道的广告等类似内容。"},{"i":18,"n":"第十八条","txt":"电视台播出境外影视剧，应在片头标明发行许可证编号。各电视频道每天播出的境外影视剧，不得超过该频道当天影视剧总播出时间的百分之二十五；每天播出的其他境外电视节目，不得超过该频道当天总播出时间的百分之十五。 未经广电总局批准，不得在黄金时段（19：00－22：00）播出境外影视剧。"},{"i":19,"n":"第十九条","txt":"违反本规定的，依据《广播电视管理条例》予以处罚。构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"本规定自2004年10月23日起施行。广播电影电视部《关于引进、播出境外电视节目的管理规定》（广播电影电视部令第10号）同时废止。"}],"guangboyingshijiejijiemujiaoliuhuodongguanliguidinb441de":[{"i":1,"n":"第一条","txt":"为规范广播影视节（展）及节目交流活动，促进中外广播影视交流，根据《广播电视管理条例》和《电影管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"举办国际性广播影视节（展）、节目交流活动和设评奖的全国性广播影视节（展），须经国务院广播影视行政部门批准。"},{"i":3,"n":"第三条","txt":"国家鼓励国产电影片、电视剧（含影视动画片）和其它广播影视节目参加境内外广播影视节（展）、节目交流活动。 在境内外广播影视节（展）参赛及展播展映的国产电影片、电视剧（含影视动画片），须取得《电影片公映许可证》或《电视剧（电视动画片）发行许可证》；其它广播电视节目，应符合《广播电视管理条例》有关节目内容的要求。"},{"i":4,"n":"第四条","txt":"在境内外举办国际性广播影视节（展）、中外政府间广播影视节（展）和设评奖的全国性广播影视节（展），由国务院广播影视行政部门举办或与国家相关政府部门、地方政府等联合举办。 全国性广播影视社会团体、行业组织经国务院广播影视行政部门批准可以举办设评奖的全国性广播影视节（展）。"},{"i":5,"n":"第五条","txt":"国家鼓励各相关单位依法与境外国家（地区）开展对等交流互办电影展映等活动。 在京的中央单位及其直属机构在境内举办上述活动须报国务院广播影视行政部门批准。其他单位在境内举办上述活动，如涉及多个国家（地区），该活动须报国务院广播影视行政部门批准；如只涉及单一国家（地区），须报省级广播影视行政部门批准，其拟展映的境外影片须经省级广播影视行政部门审查，批准时应同时抄报国务院广播影视行政部门。"},{"i":6,"n":"第六条","txt":"国际性广播影视科研、学术交流活动可由全国性广播影视社会团体、行业组织或广播影视科研、教学、研究机构举办，须报国务院广播影视行政部门批准。拟展映的境外影片须报国务院广播影视行政部门审查批准。"},{"i":7,"n":"第七条","txt":"在综合性文化活动中举办涉外电影展映活动的，举办单位须持文化行政部门对该综合性文化活动的批准文件，按照本规定的有关规定，报国务院广播影视行政部门或者相关省级广播影视行政部门审查批准。"},{"i":8,"n":"第八条","txt":"国家鼓励我国驻外使、领馆举办非商业性的中国电影展映活动。驻外使、领馆如代表中国选送影片参加在所在国举办的电影节，应商国务院广播影视行政部门同意。"},{"i":9,"n":"第九条","txt":"赴境外举办中国广播影视节（展），可由广播影视行政部门、社会团体、行业组织、企事业单位等举办，须符合国家外交和对我国港、澳、台工作的有关方针、政策，事先报国务院广播影视行政部门备案。"},{"i":10,"n":"第十条","txt":"申请举办国际性广播影视节（展）、节目交流活动和设评奖的全国性广播影视节（展），应当具备下列条件： （一）符合国务院广播影视行政部门的整体布局和规划要求； （二）如设评奖，应符合国家有关文艺评奖的规定； （三）成立举办活动的专门工作机构和制定切实可行的办节（展）方案； （四）举办综合性国际电影节（展）和设评奖的全国性电影节（展）的，还应具备专业标准的放映设备、设施； （五）节（展）活动符合国家有关外交方针、政策。"},{"i":11,"n":"第十一条","txt":"申请举办国际性广播影视节（展）、节目交流活动和设评奖的全国性电影节（展），申请单位应当提交下列材料： （一）申请报告及举办方案，举办方案应包括节（展）名称、活动内容、性质、规模、时间、地点以及活动组织机构等内容； （二）如设评奖项目，还应提供拟设奖项名称、数额、参评条件和评选办法； （三）在境内举办的，须提交拟邀请的境外机构、主要人员及拟参展的境外广播影视节目情况；赴境外举办的，须提交与境外合作方签署的合作文件或境外合作方的邀请函。"},{"i":12,"n":"第十二条","txt":"广播影视节（展）的举办单位、参展单位应遴选内容健康，思想性、艺术性、观赏性较高的影视片（剧）和其它广播影视节目参加节（展）。 入境参赛的境外电影片，须报国务院广播影视行政部门审查批准。入境展映的境外影片，由国务院广播影视行政部门或其委托的省级广播影视行政部门审查批准。赴境外参展的电影片报国务院广播影视行政部门备案。 入境参赛、展播的境外广播电视节目，须经省级以上广播电视行政部门审查批准。赴境外参展的广播电视节目，送展单位应根据《广播电视管理条例》有关节目内容要求进行审查后，事先报省级以上广播电视行政部门备案。"},{"i":13,"n":"第十三条","txt":"拟入境参赛、展映的境外电影片，申请审查时应提交电影片简介和录像带（或DVD光盘），并需有中文（或英文）字幕或其它形式的中、英文翻译。"},{"i":14,"n":"第十四条","txt":"赴境外参展的国产电影片由出品单位报国务院广播影视行政部门备案，合拍电影片由各方出品单位共同报送备案。备案应在节（展）举办二十天前报送，并提交下列材料： （一）《电影片公映许可证》复印件； （二）拟参加电影节（展）的名称、时间、地点； （三）该电影节（展）主办单位的邀请函及中文译文； （四）电影片出品单位联系人、联系电话、传真、电子邮件及通信地址； （五）如需国务院广播影视行政部门向海关出具电影片拷贝临时出入关函，须在申请中提出并注明出入海关的名称及时间。"},{"i":15,"n":"第十五条","txt":"广播影视行政部门应当按照行政许可法的有关要求，自受理申请之日起二十个工作日内提出审查意见或作出审查决定。 对入境参赛、展映的电影片和入境参赛、展播的境外广播电视节目需组织专家评审的，专家评审时间不计算在审批时间内，但应将所需时间书面告知申请人。"},{"i":16,"n":"第十六条","txt":"参加国际性广播电视节（展）、节目交流活动的广播电视节目出入境，须按照海关规定办理相关手续。 获准在境内参赛、参展的境外影片入出境，由节（展）等有关活动的举办单位持国务院广播影视行政部门或者相关省级广播影视行政部门批准文件到海关办理拷贝临时入出境手续；赴境外参加电影节（展）并已备案的影片出入境，由参展单位持国务院广播影视行政部门相关文件到海关办理拷贝临时出入境手续。"},{"i":17,"n":"第十七条","txt":"举办单位应在广播影视节（展）结束后三十日内，将举办节（展）情况报国务院广播影视行政部门备案。"},{"i":18,"n":"第十八条","txt":"在境内举办我国香港特别行政区、澳门特别行政区和台湾地区广播影视节（展）、节目交流活动，参照本规定执行。"},{"i":19,"n":"第十九条","txt":"违反本规定的，依照《广播电视管理条例》、《电影管理条例》进行处罚。"},{"i":20,"n":"第二十条","txt":"本规定自2004年10月10日起施行。《举办、参加中外电影节、展管理规定》（广发影字〔1998〕94号）同时废止。"}],"guangbodiantaidianshitaishenpiguanlibanfa":[{"i":1,"n":"第一条","txt":"为规范广播电台、电视台管理，保障广播电视事业和产业的健康发展，根据《广播电视管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称广播电台、电视台是指采编、制作并通过有线、无线、卫星或其他方式向社会公众播放广播电视节目的广播电视播出机构（含广播电视台、教育电视台、广播影视集团、总台、具备独立法人资格的广播电台、电视台分台等）。"},{"i":3,"n":"第三条","txt":"国家广播电影电视总局（以下简称广电总局）负责制定全国广播电台、电视台的设立规划，确定广播电台、电视台的总量、布局和结构，负责全国广播电台、电视台的设立审批和监督管理工作。县级以上地方广播电视行政部门负责本行政区域内广播电台、电视台的管理工作。"},{"i":4,"n":"第四条","txt":"国家禁止设立外资经营、中外合资经营和中外合作经营的广播电台、电视台。"},{"i":5,"n":"第五条","txt":"广播电台、电视台原则上由县、不设区的市以上广播电视行政部门或经批准的广播影视集团（总台）设立，其中教育电视台可以由设区的市、自治州以上教育行政部门设立。"},{"i":6,"n":"第六条","txt":"广播电台、电视台的设立、合并应当具备下列条件： （一）符合国家广播电视事业和产业发展规划以及相关的国家、行业标准； （二）有符合国家规定的广播电视专业人员、技术设备和必要的场所； （三）有必要的基本建设资金和稳定的资金保障； （四）有明确的频道定位和确定的传输覆盖范围； （五）传输覆盖方式和技术参数符合国家广播电视传输覆盖网规划。"},{"i":7,"n":"第七条","txt":"中央级广播电台、电视台的设立、合并和相关事项变更，直接报广电总局审批。地方级广播电台、电视台的设立和变更，由本级广播电视行政部门向上级广播电视行政部门提出申请，逐级审核后，报广电总局审批。 教育电视台的设立、合并和相关事项的变更，由设区的市、自治州以上教育行政部门征得同级广播电视行政部门同意后，向上级教育行政部门提出申请，逐级审核后，经国务院教育行政部门审核同意，报广电总局审批。"},{"i":8,"n":"第八条","txt":"申请设立、合并广播电台、电视台的，须提交以下申请材料： （一）申请书； （二）可行性报告。报告应载明以下内容： 　1、人力资源； 　2、资金保障及来源； 　3、场地、设备； 　4、节目频道设置规划（含频道定位、栏目设置）； 　5、传输覆盖范围、方式和技术参数； 　6、运营规划。 （三）拟使用的台名、台标、呼号，并附台标设计彩色样稿、创意简述和电子文稿； （四）本级人民政府同意设立、合并的批准文件； （五）筹备计划。"},{"i":9,"n":"第九条","txt":"广播电台、电视台申请调整节目套数和节目设置范围的，须提交以下申请材料： （一）申请书； （二）可行性报告。报告应载明以下内容： 　1、调整节目套数和节目设置范围的理由； 　2、人力资源； 　3、资金保障及来源； 　4、场地、设备； 　5、节目频道设置规划（含频道定位、栏目设置）； 　6、传输覆盖范围、方式和技术参数； 　7、运营规划。 （三）筹备计划。"},{"i":10,"n":"第十条","txt":"广播电台、电视台的台名、呼号等原则上应与国务院确定的行政区划名称一致。 台标可以由图案、汉字、数字和字母组合而成，并与其他广播电台、电视台或其他机构已使用的标识有明显区别，播出时在屏幕左上角标出。广播电台、电视台所属节目频道的标识应以台标为主体，与频道名称或简称、序号等组合而成。"},{"i":11,"n":"第十一条","txt":"广播电台、电视台申请变更台名、台标、呼号的，须提交以下申请材料： （一）申请书； （二）拟变更的台名、台标、呼号及其设计彩色样稿、创意简述和电子文稿。因行政区划变更的，须提交国务院关于变更行政区划的批准文件复印件。 因其他原因变更台名、呼号的，申请书中应充分说明变更的理由。"},{"i":12,"n":"第十二条","txt":"广播电台、电视台申请变更传输覆盖范围、方式、技术参数的，须向本级广播电视行政部门提交以下申请材料： （一）申请书； （二）对技术参数的使用建议、必要的设计文件或技术评估报告。 申请书中应说明变更传输覆盖范围、方式、技术参数的理由及对广播电视传输覆盖网的影响。"},{"i":13,"n":"第十三条","txt":"副省级城市以上广播电视行政部门或经批准的广播影视集团（总台）设立的广播电台、电视台可以按照国家广播电视事业、产业建设和技术发展规划，利用卫星方式传输本台广播电视节目。 利用卫星方式传输本台广播电视节目的，应向本级广播电视行政部门提出申请，由本级广播电视行政部门报经同级人民政府同意后，逐级上报，由广电总局审批。"},{"i":14,"n":"第十四条","txt":"申请利用卫星方式传输本台广播电视节目的，须提交以下申请材料： （一）申请书； （二）可行性报告。报告应载明以下内容： 　1、以卫星方式传输广播电视节目的理由； 　2、人力资源； 　3、资金保障及来源； 　4、场地和设备； 　5、节目频道设置规划（含频道定位、栏目设置）； 　6、运营规划。 （三）节目审查和管理制度； （四）安全传输与播出方案、技术方案； （五）本级人民政府批准文件； （六）筹备计划。"},{"i":15,"n":"第十五条","txt":"副省级城市以上广播电视行政部门或经批准的广播影视集团（总台）设立的广播电台、电视台在合法存续期间，可以向本级广播电视行政部门申请在本行政区域范围内设立分台，经逐级审核后，由广电总局审查批准。 广播电台、电视台设立分台的，须提交以下申请材料： （一）申请书； （二）可行性报告。报告应载明以下内容： 　1、人力资源； 　2、资金来源； 　3、场地、设备； 　4、节目频道设置规划（含频道定位、栏目设置）； 　5、传输覆盖范围、方式和技术参数。 （三）台名、台标、呼号，并附台标设计彩色样稿、创意简述和电子文稿。"},{"i":16,"n":"第十六条","txt":"广播电台、电视台设立的分台，应于开播前向所在地的广播电视行政部门备案，并接受所在地广播电视行政部门的属地管理。"},{"i":17,"n":"第十七条","txt":"申请人提交的所有申请材料均一式五份。负责受理的广播电视行政部门应按照行政许可法规定的期限和权限，履行受理、审核职责。广电总局对申请材料做最终审查，申请人的申请符合法定标准的，作出准予行政许可的书面决定；依法作出不予行政许可决定的，应当书面通知申请人并说明理由。"},{"i":18,"n":"第十八条","txt":"广电总局对经批准设立的广播电台、电视台颁发《广播电视播出机构许可证》，并同时对批准开办的每套广播电视节目颁发《广播电视频道许可证》。 许可证有效期为三年，自颁发之日起计算。期满后如需继续开办，须于有效期届满180日前按本办法第六条、第七条、第八条规定提出申请，经逐级审核同意后换发许可证。 《广播电视播出机构许可证》和《广播电视频道许可证》由广电总局统一印制、换发。"},{"i":19,"n":"第十九条","txt":"广播电台、电视台终止的，应充分说明理由，并按原设立审批程序逐级上报广 电总局审批，其《广播电视播出机构许可证》及《广播电视频道许可证》由广电总局收回。"},{"i":20,"n":"第二十条","txt":"广播电台、电视台应当按照批准的设立主体、台名、呼号、台标、节目设置范围、节目套数、传输覆盖范围、方式、技术参数等制作、播放节目。"},{"i":21,"n":"第二十一条","txt":"广播电台、电视台因特殊情况需要暂时停止播出的，应当经省级以上广播电视 行政部门同意；未经批准，连续停止播出超过30日的或自广电总局批准之日起超过180日尚未开播的，视为终止。"},{"i":22,"n":"第二十二条","txt":"广播电台、电视台频道可区分为公益性频道和经营性频道两类。允许两类频道按照各自不同的特点和目标要求，从机构设置上适当分开，采用相应的组织管理方式和生产经营方式。具体管理办法另行制定。"},{"i":23,"n":"第二十三条","txt":"广播电台、电视台可以跨地区合办经批准设立的广播电视频道或栏目。"},{"i":24,"n":"第二十四条","txt":"合办广播电视频道及栏目，应由该频道或栏目所属广播电台、电视台向本级广播电视行政部门提出申请，经逐级审核后，由广电总局审查批准。 合办广播电视频道或栏目的，应提交以下申请材料： （一）申请书； （二）可行性报告。报告应载明以下内容： 　1、合办广播电视频道或栏目的理由； 　2、人力资源； 　3、资金保障及来源； 　4、场地、设备； 　5、节目资源及设置规划； 　6、传输覆盖范围、方式和技术参数； 　7、运营规划。 （三）合作合同。"},{"i":25,"n":"第二十五条","txt":"县级广播电视台原则上不自办电视频道，其制作的当地新闻和经济类、科技类、法制类、农业类、重大活动类专题、有地方特色的文艺节目以及广告等，在本省、自治区、直辖市行政区域内公共频道预留时段中插播。"},{"i":26,"n":"第二十六条","txt":"广播电视付费频道的审批管理按照广电总局有关规定执行。"},{"i":27,"n":"第二十七条","txt":"广播电台、电视台申报的技术方案、安全传输与播出方案、传输覆盖范围、方式、技术参数应符合广电总局有关规定。"},{"i":28,"n":"第二十八条","txt":"违反本办法的，依照《广播电视管理条例》进行处罚。"},{"i":29,"n":"第二十九条","txt":"本办法自2004年9月20日起施行。广播电影电视部《广播电台、电视台设立审批管理办法》（广播电影电视部第19号令）同时废止。"}],"guangbodianyingdianshixingzhengfuyibanfa":[{"i":1,"n":"第一条","txt":"为了防止和纠正违法的或者不当的广播电影电视具体行政行为，保护公民、法人和其他组织的合法权益，保障和监督广播电影电视行政机关依法行使职权，根据《中华人民共和国行政复议法》(以下简称行政复议法)，并结合本系统实际，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织认为广播电影电视具体行政行为侵犯其合法权益，向上一级广播电影电视行政部门或机构(以下统称广播电影电视行政机关)提出行政复议申请，广播电影电视行政机关受理行政复议申请、作出行政复议决定，适用行政复议法和本办法。"},{"i":3,"n":"第三条","txt":"依照本办法履行行政复议职责的广播电影电视行政机关是广播电影电视行政复议机关。地市级以上广播电影电视行政机关应当明确具体办理行政复议事项的机构和人员。"},{"i":4,"n":"第四条","txt":"广播电影电视行政复议机关负责法制工作的机构具体办理行政复议事项，履行下列职责： (一)受理行政复议申请； (二)向有关组织和人员调查取证，查阅有关文件和资料； (三)审查申请行政复议的具体行政行为是否合法与适当，拟订行政复议决定； (四)处理或转送对有关规范性文件的审查申请； (五)对被申请人违反行政复议法和本办法的行为，依照规定的权限和程序提出处理建议； (六)办理因不服行政复议决定提起行政诉讼的应诉事项； (七)法律、法规规定的其他职责。"},{"i":5,"n":"第五条","txt":"国家广播电影电视总局负责指导全国广播电影电视系统的行政复议工作。 上级广播电影电视行政机关对下级广播电影电视行政机关的行政复议工作进行检查、监督和指导。下级广播电影电视行政复议机关每年应将受理行政复议案件的情况及时向上级广播电影电视行政机关上报。"},{"i":6,"n":"第六条","txt":"广播电影电视行政复议机关履行行政复议职责，应当遵循合法、公正、公开、及时、便民的原则，坚持有错必纠，保障法律、法规的正确实施。"},{"i":7,"n":"第七条","txt":"广播电影电视行政复议机关受理申请人对下列广播电影电视具体行政行为不服提出的行政复议申请： (一)对广播电影电视行政机关作出的警告、罚款、没收违法所得、没收从事违法活动的专用工具、设备和节目载体等非法财物、责令停产停业、暂扣或者吊销许可证(执照)等行政处罚决定不服的； (二)对广播电影电视行政机关作出的行政强制措施决定不服的； (三)对广播电影电视行政机关作出的有关许可证(执照)、资格证等证书的变更、终止、撤销决定不服的； (四)认为符合法定条件，申请广播电影电视行政机关颁发许可证(执照)、资格证等证书，或者申请审批、登记有关事项，行政机关没有依法办理的； (五)认为广播电影电视行政机关侵犯合法的经营自主权，或者违法要求其履行义务的； (六)认为广播电影电视行政机关的其他具体行政行为侵犯其合法权益的。"},{"i":8,"n":"第八条","txt":"公民、法人或者其他组织认为广播电影电视行政机关的具体行政行为所依据的规范性文件不合法，在对具体行政行为申请行政复议时，可以一并提出对该文件的审查申请。对规范性文件的审查申请不含国家广播电影电视总局规章和地方人民政府规章。"},{"i":9,"n":"第九条","txt":"公民、法人或者其他组织认为具体行政行为侵犯其合法权益申请行政复议，应当自知道该具体行政行为之日起六十日内提出。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。在障碍消除后，申请人应提供有关证明。"},{"i":10,"n":"第十条","txt":"认为广播电影电视行政机关的具体行政行为侵犯其合法权益，依法申请行政复议的公民、法人或者其他组织，是申请人。 同申请行政复议的具体行政行为有利害关系的公民、法人或者其他组织，可以作为第三人参加行政复议。 申请人对广播电影电视行政机关的具体行政行为不服申请行政复议，作出具体行政行为的广播电影电视行政机关是被申请人。 申请人、第三人可以委托一至二名代理人代为参加行政复议。委托代理人须向复议机关提交授权委托书，载明委托事项和权限。"},{"i":11,"n":"第十一条","txt":"申请人申请行政复议，一般应当书面申请，如确有困难，也可以口头申请。 书面申请的，应当在申请书中载明申请人的基本情况，被申请人的名称、地址，行政复议请求，申请复议的主要事实、理由和时间。申请书上应有申请人的签字或签章。 口头申请的，复议机关应当当场记录上述情况，并由申请人签字或盖章。"},{"i":12,"n":"第十二条","txt":"对县级以上广播电影电视行政机关作出的具体行政行为不服的，申请人可以向上一级广播电影电视行政机关申请行政复议，也可以向同级人民政府申请行政复议。 对广播电影电视行政机关与其他同级行政机关以共同名义作出的具体行政行为不服的，向其共同上一级行政机关申请行政复议。 对国家广播电影电视总局作出的具体行政行为不服的，向国家广播电影电视总局申请行政复议。"},{"i":13,"n":"第十三条","txt":"凡符合行政复议法和本办法的行政复议申请，广播电影电视行政复议机关必须依据行政复议法规定的受理程序予以受理。行政复议机关无正当理由不予受理的，上级广播电影电视行政机关应当责令其受理；必要时，上级广播电影电视行政机关也可以直接受理。 广播电影电视行政机关的信访或者其他机构收到行政复议申请后，应当及时送交本单位负责行政复议工作的机构。"},{"i":14,"n":"第十四条","txt":"广播电影电视行政复议机关收到行政复议申请后，应当在五个工作日内进行审查。对有下列情形之一的，决定不予受理，并以《不予受理决定书》的形式书面告知申请人： (一)不属于法定行政复议范围的； (二)超过法定申请行政复议期限，且无本办法第九条第二款规定情形的； (三)已向人民法院提起行政诉讼，人民法院已依法受理的； (四)其他不符合行政复议法规定的。 对符合行政复议法规定，但是不属于本机关受理的行政复议申请，应当告知申请人向有关行政复议机关提出。"},{"i":15,"n":"第十五条","txt":"除第十四条规定外，行政复议申请自行政复议机关负责复议工作的机构收到之日起即为受理。行政复议申请一经受理，应及时告知申请人和被申请人。 复议机构收到复议申请的日期，属直接从邮递渠道收到或者从复议机关其他部门、机构及其下属机构转来的，由复议机构的签收章确认；属申请人当面递交的，由复议机构经办人在申请书上注明收到日期，并由递交人签字确认。"},{"i":16,"n":"第十六条","txt":"行政复议期间具体行政行为不停止执行，但有行政复议法第二十一条规定情形之一的，可以停止执行。决定停止执行的，应将对具体行政行为的《停止执行通知书》送达被申请人。"},{"i":17,"n":"第十七条","txt":"广播电影电视行政复议机关对依法受理的行政复议申请，应按照行政复议法的规定进行审查，作出复议决定。审查前，复议机构应做好下列准备工作： (一)确定行政复议工作人员； (二)明确复议参加人； (三)按规定发送复议法律文书。 复议机构审查复议案件时，如认为有必要，可以要求本机关内相关机构的人员参加。"},{"i":18,"n":"第十八条","txt":"行政复议原则上采取书面审查的办法，但有下列情形之一的，复议机构可以向有关组织和人员调查情况，听取申请人、被申请人和第三人的意见： (一)申请人提出要求的； (二)案件主要事实不清的； (三)案情重大、复杂、疑难的； (四)复议机构认为有必要的。 复议机构调查情况、听取意见时，复议人员不得少于两人，并应当制作《行政复议调查笔录》，调查笔录应由被调查人、调查人签名或盖章。"},{"i":19,"n":"第十九条","txt":"广播电影电视行政复议机关负责复议工作的机构应当自行政复议申请受理之日起七个工作日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到申请书副本或者申请笔录复印件之日起十日内，提出书面答复，并提交当初作出具体行政行为的证据、依据和其他有关材料。"},{"i":20,"n":"第二十条","txt":"被申请人提交的《行政复议被申请人答复书》应当载明下列内容： (一)被申请人的名称、地址，法定代表人姓名及职务； (二)作出具体行政行为的事实、证据和依据。对有关事实的陈述应注明相应的证据材料和出处； (三)对申请人的复议要求、所述事实和理由进行答辩和必要的举证； (四)作出书面答复的年、月、日，并加盖印章。"},{"i":21,"n":"第二十一条","txt":"申请人、第三人可以查阅被申请人提出的书面答复、作出具体行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密或者个人隐私外，行政复议机关不得拒绝。查阅有关材料，应符合下列规定： (一)向复议机构提出申请，并出示有关身份证明； (二)查阅时，应有复议机构的工作人员在场； (三)查阅时不得涂改、毁损、拆换、增添、取走查阅的材料。"},{"i":22,"n":"第二十二条","txt":"广播电影电视行政复议机关应当自受理申请之日起六十日内作出行政复议决定。情况复杂，不能在规定期限内作出行政复议决定的，经行政复议机关的负责人批准，可以适当延长，并告知申请人和被申请人；但是延长期限最多不超过三十日。"},{"i":23,"n":"第二十三条","txt":"广播电影电视行政复议机关应当对被申请人作出的具体行政行为的合法性和适当性进行全面审查，依照行政复议法第二十八条的规定作出复议决定。《行政复议决定书》应当载明下列内容： (一)申请人的姓名、性别、年龄、职业、住址(法人或其他组织的名称、地址、法定代表人的姓名和职务)； 如有第三人，并列明第三人的上述情况； (二)被申请人的名称、地址、法定代表人姓名和职务； (三)申请人申请行政复议的请求和理由； (四)被申请人的答复； (五)复议机关认定的事实、证据、理由和依据； (六)复议机关的复议结论； (七)不服复议结论向人民法院起诉的期限； (八)作出复议决定的日期和复议机关的印章。 《行政复议决定书》一经送达，即发生法律效力。"},{"i":24,"n":"第二十四条","txt":"被申请人、申请人应当履行行政复议决定。 被申请人不履行或者无正当理由拖延履行行政复议决定的，行政复议机关或者有关上级行政机关应当责令其限期履行。 对申请人逾期不起诉又不履行行政复议决定的，依行政复议法第三十三条的规定申请人民法院强制执行时，使用《强制执行申请书》。"},{"i":25,"n":"第二十五条","txt":"广播电影电视行政复议审查终结作出复议决定后，复议机构应对有关复议的所有法律文书和材料进行认真清理、鉴别和编号，及时归档。广播电影电视行政复议机关应当在行政复议案件结案后三十日内，将复议情况向上一级广播电影电视行政机关备案。"},{"i":26,"n":"第二十六条","txt":"广播电影电视行政复议机关受理行政复议申请，不得向申请人收取任何费用。行政复议活动所需的经费，应当列入本机关的行政经费，依法予以保障。 行政复议人员必须精通法律和广播电影电视业务，广播电影电视行政机关应当保障复议工作的资金和工作条件，保持复议人员的相对稳定。"},{"i":27,"n":"第二十七条","txt":"广播电影电视行政复议法律文书，参照国家广播电影电视总局制作的统一样式制作。"},{"i":28,"n":"第二十八条","txt":"本办法未尽事宜，按行政复议法的规定办理。"},{"i":29,"n":"第二十九条","txt":"本办法自发布之日起施行。《关于广播电影电视行政复议若干规定》(广播电影电视部第6号令)和《广播电影电视行政复议法律文书使用与管理办法》(广发政字［1993］268号)同时废止。"}],"guangbodianshianquanbochuguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强广播电视安全播出管理，保障广播电视信号安全优质播出，维护用户收听收看广播电视的权益，根据《广播电视管理条例》《广播电视设施保护条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"为保障广播电视安全播出开展的系统建设、技术维护、运行管理、监测监管、指挥调度、应急处置及其他相关活动，适用本规定。"},{"i":3,"n":"第三条","txt":"国家广播电视总局负责全国广播电视安全播出监督管理工作。 县级以上地方人民政府广播电视行政部门负责本行政区域内的广播电视安全播出监督管理工作。"},{"i":4,"n":"第四条","txt":"广播电视安全播出工作应当坚持不间断、高质量、既经济、又安全的方针。"},{"i":5,"n":"第五条","txt":"任何组织、个人不得实施干扰广播电视信号、危害广播电视安全播出的行为。"},{"i":6,"n":"第六条","txt":"广播电视安全播出实行分类分级保障制度。从事广播电视播出、集成、传输、分发、覆盖等业务的单位（以下简称安全播出责任单位）应当符合本规定和国家广播电视总局关于广播电视安全播出的有关要求；不符合的，不得从事相关活动。"},{"i":7,"n":"第七条","txt":"安全播出责任单位应当加强制度建设，采取多种措施保障广播电视安全播出。安全播出责任单位的主要负责人应当对本单位的广播电视安全播出工作全面负责。"},{"i":8,"n":"第八条","txt":"县级以上地方人民政府广播电视行政部门可以依据有关规定，对在广播电视安全播出工作中做出显著成绩的组织、个人给予表彰、奖励。 安全播出责任单位应当依据本规定，建立安全播出工作奖惩制度。"},{"i":9,"n":"第九条","txt":"安全播出责任单位应当建立健全安全播出技术维护和运行管理的机构，合理配备工作岗位和人员，并将其他涉及安全播出的部门和人员纳入安全播出管理，落实安全播出责任制。"},{"i":10,"n":"第十条","txt":"安全播出责任单位的安全播出人员管理，应当符合下列规定： （一）参与节目播出或者技术系统运行维护的人员，应当具有相应的专业技能，并通过岗位培训和考核； （二）新系统、新设备投入使用前，应当对相关人员进行培训； （三）特种作业人员应当按照国家广播电视总局的规定或者其他国家有关规定取得相应资格证书。"},{"i":11,"n":"第十一条","txt":"安全播出责任单位的技术系统配置，应当符合下列规定： （一）符合国家、行业相关技术规范和国家广播电视总局规定的分级配置要求； （二）针对播出系统特点采取相应的防范干扰、插播、阻断、篡改、攻击等恶意破坏的技术措施； （三）采用声音、图像、码流录制或者保存技术监测信息等方式对本单位播出、传输、发射的节目信号的质量和效果，以及相关设备运行状态进行记录。记录方式应当符合省、自治区、直辖市以上人民政府广播电视行政部门的有关规定，记录信息应当保存一周以上，异态节目记录信息应当保存一年以上； （四）使用依法取得广播电视设备器材入网认定的设备、器材和软件，并建立设备更新机制，提高设备运行可靠性； （五）省级以上广播电台、电视台、卫星地球站应当配置完整、有效的容灾系统，保证特殊情况下主要节目安全播出。"},{"i":12,"n":"第十二条","txt":"安全播出责任单位应当建立健全技术维护、运行管理等安全播出管理制度。"},{"i":13,"n":"第十三条","txt":"安全播出责任单位应当保障技术系统运行维护、更新改造和安全防范等安全播出所需经费。"},{"i":14,"n":"第十四条","txt":"鼓励开展对广播电视安全播出管理、技术的研究和创新，不断提高广播电视安全播出水平。"},{"i":15,"n":"第十五条","txt":"安全播出责任单位的广播电视节目源管理，应当符合下列规定： （一）广播电台、电视台在节目制作、节目播出编排、节目交接等环节应当执行复核复审、重播重审制度，避免节目错播、空播，并保证节目制作技术质量符合国家、行业相关标准； （二）广播电台、电视台直播节目应当具备必要的延时手段和应急措施，加强对节目的监听监看，监督参与直播的人员遵守直播管理制度和技术设备操作规范； （三）从事广播电视传输、分发、覆盖业务的安全播出责任单位应当按照有关规定完整传输、分发必转的广播电视节目； （四）不得擅自接入、传送、播出境外广播电视节目； （五）发现广播电视节目中含有法律、行政法规禁止的内容的，应当立即采取措施予以消除或者停止播出、集成、传输、分发、覆盖，保存有关记录，并向广播电视行政部门报告。"},{"i":16,"n":"第十六条","txt":"对新建、扩建或者更新改造广播电视技术系统的工程项目，安全播出责任单位在实施前应当组织相关专家或者委托专业评估机构对技术方案进行安全播出评估；在工程项目完工后应当组织验收，并向广播电视行政部门报告验收情况。"},{"i":17,"n":"第十七条","txt":"新建广播电视技术系统投入使用前，试运行时间不得少于一个月。"},{"i":18,"n":"第十八条","txt":"新建广播电视播出、集成、传输、分发、发射系统需要试播的，安全播出责任单位应当报请省、自治区、直辖市以上人民政府广播电视行政部门批准。 申请材料应当包括申请书、播出保障方案等内容。 试播期不得超过六个月。对安全播出责任单位试播期间的安全播出工作评价纳入广播电视安全播出考核，但非责任性停播事故除外。"},{"i":19,"n":"第十九条","txt":"安全播出责任单位的技术系统运行管理，应当符合下列规定： （一）按照省、自治区、直辖市以上人民政府广播电视行政部门批准的节目、传输方式、覆盖范围以及相关技术参数播出、集成、传输、分发、发射广播电视信号，未经批准不得擅自停止或者变更服务； （二）播出质量、技术运行指标符合国家、行业有关标准； （三）制定完善的安全播出保障方案和播出、运行工作流程，安全播出保障方案应当报广播电视行政部门备案； （四）对主要播出环节的信号进行监听监看，对设备运行状态进行监控，及时发现并处置播出故障； （五）广播电视重点时段和重要节目播出期间，在人员、设施等方面给予保障，做好重点区域、重点部位的防范和应急准备； （六）定期开展安全播出风险、保障能力自查或者委托专业机构进行评估，发现、消除安全隐患。"},{"i":20,"n":"第二十条","txt":"安全播出责任单位的技术系统维护管理，应当符合下列规定： （一）遵守国家、行业有关标准，建立健全维护管理制度； （二）安全播出责任单位之间、播出环节之间做到维护界限清晰、责任明确； （三）安全播出责任单位委托其他单位承担技术维护或者播出运行工作的，应当选择具备相应技术实力的单位，并与其签订委托协议。"},{"i":21,"n":"第二十一条","txt":"广播电视技术系统的检修、施工管理，应当符合下列规定： （一）对技术系统定期进行例行检修，例行检修需要停播（传）广播电视节目的，应当将检修计划按照国家广播电视总局的有关规定进行备案； （二）在例行检修时间之外临时停播（传）广播电视节目进行检修、施工、演练等操作的，应当按照国家广播电视总局的有关规定报请批准或者备案； （三）更新改造在播系统、设备、线路及其附属设施，应当制定工程施工方案和应急预案，与施工单位签订安全协议，落实安全措施。"},{"i":22,"n":"第二十二条","txt":"安全播出责任单位在播出、集成、传输、分发、覆盖及相关活动中，应当遵守有关安全生产的法律、法规和技术标准。 安全播出责任单位应当遵守有关网络安全的法律、法规和技术标准，履行网络安全责任义务，对涉及安全播出的网络和信息系统开展风险评估和等级保护工作。"},{"i":23,"n":"第二十三条","txt":"广播电视安全播出事故管理，应当符合下列规定： （一）广播电视安全播出事故分为责任事故、技术事故、其他事故三类，事故级别分为特大（Ⅰ级）、重大（Ⅱ级）、一般（Ⅲ级）三级； （二）安全播出责任单位发生特大、重大事故后，应当立即向省、自治区、直辖市以上人民政府广播电视行政部门报告； （三）特大安全播出事故由国家广播电视总局组织事故调查，重大事故由省、自治区、直辖市以上人民政府广播电视行政部门组织事故调查； （四）发生安全播出事故的，安全播出责任单位的上级主管部门应当根据调查结果依法予以处理。"},{"i":24,"n":"第二十四条","txt":"安全播出责任单位应当定期向广播电视行政部门报送安全播出统计报表和报告。"},{"i":25,"n":"第二十五条","txt":"全国安全播出重要保障期由国家广播电视总局规定，地方安全播出重要保障期由县级以上地方人民政府广播电视行政部门规定。 重要保障期确定后，广播电视行政部门应当及时告知安全播出责任单位。"},{"i":26,"n":"第二十六条","txt":"重要保障期前，安全播出责任单位应当制定重要保障期预案，做好动员部署、安全防范和技术准备。"},{"i":27,"n":"第二十七条","txt":"重要保障期间，安全播出责任单位应当全面落实重要保障期预案的措施、要求，加强值班和监测，并做好应急准备。重要节目和重点时段，主管领导应当现场指挥。 广播电视行政部门应当对安全播出责任单位在重要保障期的各项工作加强监督、检查。"},{"i":28,"n":"第二十八条","txt":"重要保障期间，安全播出责任单位不得进行例行检修或者有可能影响安全播出的施工；因排除故障等特殊情况必须检修并可能造成广播电视节目停播（传）的，应当报省、自治区、直辖市以上人民政府广播电视行政部门批准。"},{"i":29,"n":"第二十九条","txt":"因重要保障期取消例行检修时段的，广播电台、电视台应当提前做好节目安排和节目单核查，避免造成节目空播。"},{"i":30,"n":"第三十条","txt":"广播电视行政部门对本行政区域内广播电视安全播出突发事件应急管理工作负责。 安全播出责任单位负责本单位安全播出突发事件的应急处置工作，并服从广播电视行政部门的统一管理。"},{"i":31,"n":"第三十一条","txt":"广播电视安全播出突发事件分为破坏侵扰事件、网络安全事件、自然灾害事件、技术安全事件、其他事件五类；突发事件级别分为特大（Ⅰ级）、重大（Ⅱ级）、较大（Ⅲ级）、一般（Ⅳ级）四级。"},{"i":32,"n":"第三十二条","txt":"发生安全播出突发事件时，安全播出责任单位应当遵循下列处置原则： （一）播出、集成、传输、分发、发射、接收的广播电视节目信号受到侵扰或者发现异常信号时，应当立即切断异常信号传播，并在可能的情况下倒换正常信号； （二）发现无线信号受到干扰时，应当及时进行自查，排除由于自身设备故障、用户误操作等内部原因造成的干扰。自查后仍无法消除干扰的，立即向所在地的省、自治区、直辖市无线电管理机构投诉，报请排查干扰； （三）发生网络安全事件时，应当按照有关规定立即采取有效措施，阻止有害信息传播，及时恢复正常播出秩序，并向所在地广播电视行政部门和网络安全有关部门报告； （四）发生危及人身安全或者设施安全的突发事件时，应当在保证人身安全、设施安全的情况下，采取措施尽快恢复播出； （五）恢复节目信号播出时，应当优先保障主频率主频道节目的播出，遵循“先中央、后地方；先公益、后付费”的原则。"},{"i":33,"n":"第三十三条","txt":"安全播出责任单位应当根据安全播出突发事件的分类、级别和处置原则，制定和适时修订应急预案，定期组织演练，并将预案报广播电视行政部门备案。"},{"i":34,"n":"第三十四条","txt":"安全播出责任单位应当投入必要的资金用于应急资源储备和维护更新，应急资源储备目录、维护更新情况应当报广播电视行政部门备案。 在紧急状态下，安全播出责任单位应当服从广播电视行政部门对应急资源的统一调配，确保重要节目安全播出。"},{"i":35,"n":"第三十五条","txt":"广播电视行政部门履行下列广播电视安全播出监督管理职责： （一）组织制定并实施运行维护规程及安全播出相关的技术标准、管理规范； （二）对本行政区域内安全播出情况进行监督、检查，对发现的安全播出事故隐患，督促安全播出责任单位予以消除； （三）组织对安全播出事件事故的调查并依法处理； （四）建立健全监测机制，掌握本行政区域内节目播出、传输、覆盖情况，发现和快速通报播出异态； （五）建立健全指挥调度机制，保证安全播出责任单位和相关部门的协调配合； （六）组织安全播出考核，并根据考核结果进行表扬或者批评。"},{"i":36,"n":"第三十六条","txt":"广播电视行政部门设立的广播电视监测监管、指挥调度机构，按照广播电视行政部门的要求，负责广播电视信号监测、安全播出保障体系建设、安全播出风险评估、事件事故接报、调查检查等安全播出日常管理以及应急指挥调度的具体工作。"},{"i":37,"n":"第三十七条","txt":"广播电视监测监管、指挥调度机构应当安排专人二十四小时值班，了解与安全播出有关的突发事件，及时向广播电视行政部门报告；建立健全技术监测系统，避免漏监、错监；建立健全指挥调度系统，保证快速、准确发布预警和调度指令。"},{"i":38,"n":"第三十八条","txt":"安全播出责任单位应当按照广播电视行政部门的规定，积极配合广播电视监测监管、指挥调度机构的工作，如实无偿提供节目信号、解密授权及相关信息，并提供安装监测设备的机房环境。"},{"i":39,"n":"第三十九条","txt":"广播电视行政部门应当建立广播电视安全播出举报制度，公布举报电话、信箱或者电子邮件地址；任何组织、个人有权对违反安全播出管理的行为进行举报。 广播电视行政部门受理有关安全播出的举报，应当进行记录；经调查核实的，应当通知有关安全播出责任单位并督促其整改。"},{"i":40,"n":"第四十条","txt":"违反本规定，有下列行为之一的，对直接负责的主管人员和直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： （一）发生安全播出特大、重大责任事故造成恶劣影响的； （二）造成广播电视技术系统严重损害的； （三）对特大、重大安全播出事故、事件隐瞒不报、谎报或者拖延不报的。"},{"i":41,"n":"第四十一条","txt":"违反本规定，有下列行为之一的，由县级以上人民政府广播电视行政部门给予警告，下达《安全播出整改通知书》；逾期未改正的，给予通报批评，可并处三万元以下罚款；情节严重的，对直接负责的主管人员和直接责任人员依法给予处分： （一）机构和人员设置、技术系统配置、管理制度、运行流程、应急预案等不符合有关规定，导致播出质量达不到要求的； （二）对技术系统的代维单位管理不力，引发重大安全播出事故的； （三）安全播出责任单位之间责任界限不清晰，导致故障处置不及时的； （四）节目播出、传送质量不好影响用户正常接收广播电视节目的； （五）从事广播电视传输、分发、覆盖业务的安全播出责任单位未按照有关规定完整传输、分发必转的广播电视节目的； （六）未按照规定向广播电视行政部门设立的监测监管、指挥调度机构提供完整节目信号、解密授权及相关信息，或者干扰、阻碍监测监管、指挥调度活动的； （七）妨碍广播电视行政部门监督检"},{"i":42,"n":"第四十二条","txt":"广播电台、电视台及广播电视监测监管、指挥调度机构违反本规定，县级以上人民政府广播电视行政部门可以依照《广播电视管理条例》和国家有关规定予以处理。"},{"i":43,"n":"第四十三条","txt":"广播电视行政部门及其工作人员在广播电视安全播出管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。"},{"i":44,"n":"第四十四条","txt":"本规定下列用语的含义： （一）安全播出，是指在广播电视节目播出、集成、传输、分发过程中的内容完整、信号安全、网络安全和技术安全。其中，内容完整，是指安全播出责任单位完整并准确地播出、集成、传输、分发预定的广播电视内容；信号安全，是指承载广播电视内容的电、光信号不间断、高质量；网络安全，是指广播电视相关业务网络处于稳定可靠运行状态，所承载的广播电视业务数据完整、保密、可用；技术安全，是指广播电视播出、集成、传输、分发、覆盖及相关活动参与人员的人身安全和广播电视设施安全。 （二）技术系统，是指与广播电视安全播出有关的系统、设备、线路及其附属设施的统称。包括：广播电视播出、集成、传输、分发、发射系统以及相关监测、监控系统，相关供配电系统，相关附属设施（含机房以及机房内空调、消防、防雷接地、光电缆所在杆路、管道，天线所在桅塔等）。 （三）紧急状态，是指发生特大、重大安全播出突发事件，需要立即启"},{"i":45,"n":"第四十五条","txt":"本规定自2010年2月6日起施行。1992年6月17日原广播电影电视部发布的《有线电视系统技术维护运行管理暂行规定》、2002年4月2日国家广播电影电视总局发布的《有线广播电视传输覆盖网安全管理办法》和2002年8月23日国家广播电影电视总局发布的《有线广播电视传输覆盖网缆线安全防范管理办法》同时废止。"}],"guangbodianshiguanggaobochuguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范广播电视广告播出秩序，促进广播电视广告业健康发展，保障公民合法权益，依据《中华人民共和国广告法》、《广播电视管理条例》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"广播电台、电视台（含广播电视台）等广播电视播出机构（以下简称“播出机构”）的广告播出活动，以及广播电视传输机构的相关活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称广播电视广告包括公益广告和商业广告（含资讯服务、广播购物和电视购物短片广告等）。"},{"i":4,"n":"第四条","txt":"广播电视广告播出活动应当坚持以人为本，遵循合法、真实、公平、诚实信用的原则。"},{"i":5,"n":"第五条","txt":"广播电视行政部门对广播电视广告播出活动实行属地管理、分级负责。 国务院广播电视行政部门负责全国广播电视广告播出活动的监督管理工作。 县级以上地方人民政府广播电视行政部门负责本行政区域内广播电视广告播出活动的监督管理工作。"},{"i":6,"n":"第六条","txt":"广播电视行政部门鼓励广播电视公益广告制作和播出，对成绩显著的组织、个人予以表彰。"},{"i":7,"n":"第七条","txt":"广播电视广告是广播电视节目的重要组成部分，应当坚持正确导向，树立良好文化品位，与广播电视节目相和谐。"},{"i":8,"n":"第八条","txt":"广播电视广告禁止含有下列内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整，危害国家安全，或者损害国家荣誉和利益的； （三）煽动民族仇恨、民族歧视，侵害民族风俗习惯，伤害民族感情，破坏民族团结，违反宗教政策的； （四）扰乱社会秩序，破坏社会稳定的； （五）宣扬邪教、淫秽、赌博、暴力、迷信，危害社会公德或者民族优秀文化传统的； （六）侮辱、歧视或者诽谤他人，侵害他人合法权益的； （七）诱使未成年人产生不良行为或者不良价值观，危害其身心健康的； （八）使用绝对化语言，欺骗、误导公众，故意使用错别字或者篡改成语的； （九）商业广告中使用、变相使用中华人民共和国国旗、国徽、国歌，使用、变相使用国家领导人、领袖人物的名义、形象、声音、名言、字体或者国家机关和国家机关工作人员的名义、形象的； （十）药品、医疗器械、医疗和健康资讯类广告中含有宣传治愈率、有效率，或者以医生、"},{"i":9,"n":"第九条","txt":"禁止播出下列广播电视广告： （一）以新闻报道形式发布的广告； （二）烟草制品广告； （三）处方药品广告； （四）治疗恶性肿瘤、肝病、性病或者提高性功能的药品、食品、医疗器械、医疗广告； （五）姓名解析、运程分析、缘分测试、交友聊天等声讯服务广告； （六）出现“母乳代用品”用语的乳制品广告； （七）法律、行政法规和国家有关规定禁止播出的其他广告。"},{"i":10,"n":"第十条","txt":"时政新闻类节（栏）目不得以企业或者产品名称等冠名。有关人物专访、企业专题报道等节目中不得含有地址和联系方式等内容。"},{"i":11,"n":"第十一条","txt":"投资咨询、金融理财和连锁加盟等具有投资性质的广告，应当含有“投资有风险”等警示内容。"},{"i":12,"n":"第十二条","txt":"除福利彩票、体育彩票等依法批准的广告外，不得播出其他具有博彩性质的广告。"},{"i":13,"n":"第十三条","txt":"广播电视广告播出应当合理编排。其中，商业广告应当控制总量、均衡配置。"},{"i":14,"n":"第十四条","txt":"广播电视广告播出不得影响广播电视节目的完整性。除在节目自然段的间歇外，不得随意插播广告。"},{"i":15,"n":"第十五条","txt":"播出机构每套节目每小时商业广告播出时长不得超过12分钟。其中，广播电台在11:00至13:00之间、电视台在19:00至21:00之间，商业广告播出总时长不得超过18分钟。 在执行转播、直播任务等特殊情况下，商业广告可以顺延播出。"},{"i":16,"n":"第十六条","txt":"播出机构每套节目每日公益广告播出时长不得少于商业广告时长的3%。其中，广播电台在11:00至13:00之间、电视台在19:00至21:00之间，公益广告播出数量不得少于4条（次）。"},{"i":17,"n":"第十七条","txt":"播出电视剧时，不得在每集（以四十五分钟计）中间以任何形式插播广告。播出电影时，插播广告参照前款规定执行。"},{"i":18,"n":"第十八条","txt":"除电影、电视剧剧场或者节（栏）目冠名标识外，禁止播出任何形式的挂角广告。"},{"i":19,"n":"第十九条","txt":"电影、电视剧剧场或者节（栏）目冠名标识不得含有下列情形： （一）单独出现企业、产品名称，或者剧场、节（栏）目名称难以辨认的； （二）标识尺寸大于台标，或者企业、产品名称的字体尺寸大于剧场、节（栏）目名称的； （三）翻滚变化，每次显示时长超过5分钟，或者每段冠名标识显示间隔少于10分钟的； （四）出现经营服务范围、项目、功能、联系方式、形象代言人等文字、图像的。"},{"i":20,"n":"第二十条","txt":"电影、电视剧剧场或者节（栏）目不得以治疗皮肤病、癫痫、痔疮、脚气、妇科、生殖泌尿系统等疾病的药品或者医疗机构作冠名。"},{"i":21,"n":"第二十一条","txt":"转播、传输广播电视节目时，必须保证被转播、传输节目的完整性。不得替换、遮盖所转播、传输节目中的广告；不得以游动字幕、叠加字幕、挂角广告等任何形式插播自行组织的广告。"},{"i":22,"n":"第二十二条","txt":"经批准在境内落地的境外电视频道中播出的广告，其内容应当符合中国法律、法规和本办法的规定。"},{"i":23,"n":"第二十三条","txt":"播出商业广告应当尊重公众生活习惯。在6:30至7:30、11:30至12:30以及18:30至20:00的公众用餐时间，不得播出治疗皮肤病、痔疮、脚气、妇科、生殖泌尿系统等疾病的药品、医疗器械、医疗和妇女卫生用品广告。"},{"i":24,"n":"第二十四条","txt":"播出机构应当严格控制酒类商业广告，不得在以未成年人为主要传播对象的频率、频道、节（栏）目中播出。广播电台每套节目每小时播出的烈性酒类商业广告，不得超过2条；电视台每套节目每日播出的烈性酒类商业广告不得超过12条，其中19:00至21:00之间不得超过2条。"},{"i":25,"n":"第二十五条","txt":"在中小学生假期和未成年人相对集中的收听、收视时段，或者以未成年人为主要传播对象的频率、频道、节（栏）目中，不得播出不适宜未成年人收听、收视的商业广告。"},{"i":26,"n":"第二十六条","txt":"播出电视商业广告时不得隐匿台标和频道标识。"},{"i":27,"n":"第二十七条","txt":"广告主、广告经营者不得通过广告投放等方式干预、影响广播电视节目的正常播出。"},{"i":28,"n":"第二十八条","txt":"县级以上人民政府广播电视行政部门应当加强对本行政区域内广播电视广告播出活动的监督管理，建立、完善监督管理制度和技术手段。"},{"i":29,"n":"第二十九条","txt":"县级以上人民政府广播电视行政部门应当建立公众举报机制，公布举报电话，及时调查、处理并公布结果。"},{"i":30,"n":"第三十条","txt":"县级以上地方人民政府广播电视行政部门在对广播电视广告违法行为作出处理决定后5个工作日内，应当将处理情况报上一级人民政府广播电视行政部门备案。"},{"i":31,"n":"第三十一条","txt":"因公共利益需要等特殊情况，省、自治区、直辖市以上人民政府广播电视行政部门可以要求播出机构在指定时段播出特定的公益广告，或者作出暂停播出商业广告的决定。"},{"i":32,"n":"第三十二条","txt":"播出机构从事广告经营活动应当取得合法资质，非广告经营部门不得从事广播电视广告经营活动，记者不得借采访名义承揽广告业务。"},{"i":33,"n":"第三十三条","txt":"播出机构应当建立广告经营、审查、播出管理制度，负责对所播出的广告进行审查。"},{"i":34,"n":"第三十四条","txt":"播出机构应当加强对广告业务承接登记、审核等档案资料的保存和管理。"},{"i":35,"n":"第三十五条","txt":"药品、医疗器械、医疗、食品、化妆品、农药、兽药、金融理财等须经有关行政部门审批的商业广告，播出机构在播出前应当严格审验其依法批准的文件、材料。不得播出未经审批、材料不全或者与审批通过的内容不一致的商业广告。"},{"i":36,"n":"第三十六条","txt":"制作和播出药品、医疗器械、医疗和健康资讯类广告需要聘请医学专家作为嘉宾的，播出机构应当核验嘉宾的医师执业证书、工作证、职称证明等相关证明文件，并在广告中据实提示，不得聘请无有关专业资质的人员担当嘉宾。"},{"i":37,"n":"第三十七条","txt":"因广告主、广告经营者提供虚假证明文件导致播出的广告违反本办法规定的，广播电视行政部门可以对有关播出机构减轻或者免除处罚。"},{"i":38,"n":"第三十八条","txt":"国务院广播电视行政部门推动建立播出机构行业自律组织。该组织可以按照章程的规定，采取向社会公告、推荐和撤销“广播电视广告播出行业自律示范单位”等措施，加强行业自律。"},{"i":39,"n":"第三十九条","txt":"违反本办法第八条、第九条的规定，由县级以上人民政府广播电视行政部门责令停止违法行为或者责令改正，给予警告，可以并处三万元以下罚款；情节严重的，由原发证机关吊销《广播电视频道许可证》、《广播电视播出机构许可证》。"},{"i":40,"n":"第四十条","txt":"违反本办法第十五条、第十六条、第十七条的规定，以及违反本办法第二十一条规定插播广告的，由县级以上人民政府广播电视行政部门依据《广播电视管理条例》第五十条、第五十一条的有关规定给予处罚。"},{"i":41,"n":"第四十一条","txt":"违反本办法第十条、第十二条、第十八条、第十九条、第二十条、第二十三条至第二十七条、第三十三条、第三十五条、第三十六条的规定，或者违反本办法第二十一条规定替换、遮盖广告的，由县级以上人民政府广播电视行政部门责令停止违法行为或者责令改正，给予警告，可以并处二万元以下罚款。"},{"i":42,"n":"第四十二条","txt":"违反本办法规定的播出机构，由县级以上人民政府广播电视行政部门依据国家有关规定予以处理。"},{"i":43,"n":"第四十三条","txt":"广播电视行政部门工作人员滥用职权、玩忽职守、徇私舞弊或者未依照本办法规定履行职责的，对负有责任的主管人员和直接责任人员依法给予处分。"},{"i":44,"n":"第四十四条","txt":"本办法自2010年1月1日起施行。2003年9月15日国家广播电影电视总局发布的《广播电视广告播放管理暂行办法》同时废止。"}],"guangbodianshiwuxianchuanshufugaiwangguanlibanfa":[{"i":1,"n":"第一条","txt":"为保证广播电视无线传输覆盖业务的正常进行，维护广播电视播出秩序，加强对广播电视无线传输覆盖业务的管理，根据《广播电视管理条例》和《广播电视设施保护条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于广播电视无线传输覆盖网（以下简称无线传输覆盖网）的规划、建设、使用和管理等活动。 无线传输覆盖网包括广播电视发射台、转播台、差转台、收转台（站）、微波站、节目传送台（站）、广播电视卫星、卫星地球站、监测台（站）等部分。 广播电视无线传输覆盖业务是指利用无线传输覆盖网传送广播电视节目信号、应急广播信息的活动。"},{"i":3,"n":"第三条","txt":"国家广播电视总局（以下简称广电总局）负责全国无线传输覆盖网的管理工作，根据广播电视的发展需要，负责组织制定全国无线传输覆盖网规划，审批广播电视无线传输覆盖业务，指配广播电视专用频段的频率（以下称广播电视频率），并对全国无线传输覆盖网进行管理。 县级以上地方人民政府广播电视行政部门负责本行政区域内无线传输覆盖网的管理工作。"},{"i":4,"n":"第四条","txt":"无线传输覆盖网由县级以上人民政府广播电视行政部门按照国家有关规定组建，并应当确保本行政区域内广播电视传输覆盖的安全和质量。"},{"i":5,"n":"第五条","txt":"无线传输覆盖网的工程选址、设计、施工、安装，应当按照国家有关规定办理，并由依法取得相应资质的单位承担。工程建设和使用的无线广播电视发射设备，应当符合国家标准、行业标准和有关规定。"},{"i":6,"n":"第六条","txt":"国家对广播电视无线传输覆盖业务、使用广播电视频率、购买无线广播电视发射设备以及迁建无线广播电视设施实行许可制度。 广播电视行政部门应当按照行政许可法规定的期限办理有关许可事项。 许可证由广电总局统一印制，严禁伪造、翻印、涂改、出租、转让。"},{"i":7,"n":"第七条","txt":"严禁在无线传输覆盖网中传送法律、行政法规、规章规定禁止的内容。任何单位或者个人不得擅自使用广播电视频率，不得利用无线传输覆盖网进行违法犯罪活动。"},{"i":8,"n":"第八条","txt":"利用地面无线、微波、卫星等方式从事广播电视传输覆盖业务的，应当按照本办法规定领取《广播电视节目传送业务经营许可证（无线）》。 许可证有效期不超过十年。有效期届满需继续开展业务的，应当于届满前六个月按照本办法规定的审批程序办理手续。"},{"i":9,"n":"第九条","txt":"下列机构可以申请《广播电视节目传送业务经营许可证（无线）》： （一）经广电总局批准设立的广播电视播出机构； （二）经省、自治区、直辖市以上人民政府广播电视行政部门批准设立的广播电视无线传输覆盖机构（以下简称传输覆盖机构）； （三）具有无线广播电视传输覆盖能力的国有或者国有控股机构。"},{"i":10,"n":"第十条","txt":"申请《广播电视节目传送业务经营许可证（无线）》的，应当具备以下条件： 　　（一）具有独立的法人资格，或者不具有独立的法人资格但直属于广播电视行政部门的传输覆盖机构； （二）符合无线传输覆盖网的总体规划和业务要求； （三）有确保广播电视安全传送所需的设备、技术、人员及相关管理制度； 　　（四）有合法的广播电视节目信号来源。"},{"i":11,"n":"第十一条","txt":"申请《广播电视节目传送业务经营许可证（无线）》的，应当提交下列材料： （一）申办机构的基本情况； （二）广播电视无线传输覆盖业务申请表； （三）拟采用的传输覆盖方式、范围、服务区域和节目内容； （四）技术方案和技术安全保障机制； （五）合法广播电视节目信号来源、传输方式、传输范围的说明。 申请经营国内广播电视节目卫星传送业务的，还应当提交下列材料： （一）合法广播电视节目来源、传输方式、传输范围的说明； （二）确保广播电视传输安全的技术措施和应急预案； （三）卫星的轨道位置、转发器编号、极化方式、符号率、频率以及入网测试情况； （四）安全播出、运行维护制度； （五）专业技术人员和设备情况。"},{"i":12,"n":"第十二条","txt":"广电总局负责审批跨省广播电视节目无线传送业务。申请单位应当向本级人民政府广播电视行政部门提出申请，经逐级审核后，报广电总局审批，领取《广播电视节目传送业务经营许可证（无线）》。"},{"i":13,"n":"第十三条","txt":"省、自治区、直辖市人民政府广播电视行政部门负责审批本行政区域内广播电视节目无线传送业务。申请单位应当向所在地县级以上人民政府广播电视行政部门提出申请，经逐级审核后，报省、自治区、直辖市人民政府广播电视行政部门审批，领取《广播电视节目传送业务经营许可证（无线）》。"},{"i":14,"n":"第十四条","txt":"开展广播电视节目卫星传输业务的，应当向省、自治区、直辖市以上人民政府广播电视行政部门提出申请，经审核后，报广电总局审批，领取《广播电视节目传送业务经营许可证（无线）》。"},{"i":15,"n":"第十五条","txt":"为保证广播电视传输安全，广电总局负责指定用于传输广播电视节目的卫星转发器传输参数。任何未取得《广播电视节目传送业务经营许可证（无线）》的单位不得擅自租用或者使用卫星转发器传输广播电视节目。"},{"i":16,"n":"第十六条","txt":"为保证广播电视节目传输安全，广电总局可以要求更换或者关闭传输广播电视节目的卫星转发器。"},{"i":17,"n":"第十七条","txt":"《广播电视节目传送业务经营许可证（无线）》应当包含实施传输覆盖业务的方式、主体、传输覆盖的节目内容、传输覆盖的范围、技术手段、工作频段等内容。持证单位应当按照许可证载明的事项从事广播电视无线传输覆盖业务。"},{"i":18,"n":"第十八条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，申请使用微波、卫星非广播电视频率等传输广播电视节目，应当向国家无线电管理机构或者省、自治区、直辖市无线电管理机构办理无线电频率使用许可。"},{"i":19,"n":"第十九条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，申请使用广播电视频率传输广播电视节目，应当提交下列材料： （一）广播电视频率申请表； （二）申请使用的广播电视频率涉及修改和调整广播电视覆盖网规划的，提供技术评估报告和与相关部门或者单位的协调文件； （三）相关广播电视行政部门的审核意见。"},{"i":20,"n":"第二十条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，如需申请使用以下业务的广播电视频率，应当向所在地县级以上人民政府广播电视行政部门提出申请，经逐级审核后，报广电总局审批，领取《广播电视频率使用许可证（甲类）》： （一）中、短波广播； （二）调频广播（使用发射机标称功率50瓦（不含）以上发射设备）； （三）调频同步广播； （四）地面数字声音广播； （五）地面数字电视广播。 许可证有效期不超过十年。有效期届满需继续开展业务的，应当于届满前六个月按照本办法规定的审批程序办理手续。"},{"i":21,"n":"第二十一条","txt":"持有《广播电视节目传送业务经营许可证（无线）》的单位，如需使用小功率调频发射设备（发射机标称功率50瓦（含）以下）转播已经批准开办的广播节目、开展应急广播信息服务申请使用广播电视频率，应当向所在地县级以上人民政府广播电视行政部门提出申请，经逐级审核后，报省、自治区、直辖市人民政府广播电视行政部门审批，领取《广播电视频率使用许可证（乙类）》。 许可证有效期不超过十年。省、自治区、直辖市人民政府广播电视行政部门应当在作出许可后的三十日内将许可证核发情况向广电总局备案。有效期届满需继续开展业务的，应当于届满前六个月按照本办法规定的审批程序办理手续。"},{"i":22,"n":"第二十二条","txt":"持有《广播电视频率使用许可证》的单位，如需设置、使用无线电台（站），应当向国家无线电管理机构或者省、自治区、直辖市无线电管理机构申请办理无线电台执照。"},{"i":23,"n":"第二十三条","txt":"持有《广播电视频率使用许可证》的单位，如需购买无线广播电视发射设备，应当向核发其《广播电视频率使用许可证》的广播电视行政部门申领《无线广播电视发射设备订购证明》（以下简称《订购证明》），并提交下列材料： （一）《订购证明》申请表； （二）《广播电视频率使用许可证》复印件； （三）相关广播电视行政部门审核意见。"},{"i":24,"n":"第二十四条","txt":"无线传输覆盖网中使用的发射设备应当具有国家无线电发射设备型号核准证和广播电视设备器材入网认定证书。"},{"i":25,"n":"第二十五条","txt":"生产企业应当严格按照《订购证明》所载明的技术参数生产和销售发射设备，并在设备上加贴《订购证明》编号，同时将《订购证明》回执寄回核发《订购证明》的广播电视行政部门。订购证明作为企业生产无线广播电视发射设备的凭证存档备查。"},{"i":26,"n":"第二十六条","txt":"无线广播电视发射设备安装完毕后，设置该发射设备的单位应当在二十日内向核发其《订购证明》的广播电视行政部门提出验收申请，由相应的广播电视行政部门或者其委托的机构负责组织验收。验收合格后，发射设备方可投入正式运行。"},{"i":27,"n":"第二十七条","txt":"任何单位和个人均有保护广播电视设施的义务。县级以上人民政府广播电视行政部门负责所管辖的广播电视设施的保护工作，并采取措施，确保广播电视设施的安全。"},{"i":28,"n":"第二十八条","txt":"因重大工程项目或者当地人民政府认为需要搬迁无线广播电视设施的，城市规划行政部门在审批相关城市规划项目前，应当事先征得广电总局同意。迁建广播电视设施，应当具备以下条件： （一）符合城乡建设总体规划和国家有关规定； （二）满足广播电视安全播出的技术条件和基础设施； （三）满足广播电视传输覆盖业务要求，避开各种干扰源； （四）周围环境符合国家有关环境电磁波防护标准； （五）确保广播电视设施的各项效能的要求。"},{"i":29,"n":"第二十九条","txt":"申请迁建无线广播电视设施的，应当提交下列材料： （一）设置无线广播电视设施的批准文件和申请迁建的理由； （二）城市规划部门的意见； （三）当地人民政府的批准文件； （四）广播电视传输覆盖技术评估报告。"},{"i":30,"n":"第三十条","txt":"申请单位应当向所在地县级以上人民政府广播电视行政部门提出申请，经逐级审核后，报广电总局审批。"},{"i":31,"n":"第三十一条","txt":"迁建工作应当坚持先建设后拆除的原则。迁建所需费用由造成广播电视设施迁建的单位承担。"},{"i":32,"n":"第三十二条","txt":"违反本办法的，依据《广播电视管理条例》《广播电视设施保护条例》处罚。"},{"i":33,"n":"第三十三条","txt":"本办法自2004年12月15日起施行。广电总局《广播电视无线电管理暂行办法》（广发技字〔2001〕817号）同时废止。"}],"guangbodianshizhanshenpiguanlizanxingguiding":[{"i":1,"n":"第一条","txt":"为规范广播电视站的管理，依据《广播电视管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"省级广播电视行政部门根据国家广播电视发展规划和当地广播电视发展的实际情况，制定本辖区内广播电视站的规划和布局，负责本辖区内广播电视站的审批和日常管理工作。"},{"i":3,"n":"第三条","txt":"市辖区、乡镇以及企事业单位、大专院校可申请设立广播电视站。 每个申请单位只能设立一个广播电视站，并只能在广播电视行政部门核定的区域范围内播出广播电视节目。"},{"i":4,"n":"第四条","txt":"设立广播电视站，应当具备下列条件： （一）符合国家和本辖区广播电视事业和产业建设发展规划； （二）有符合国家规定的广播电视专业人员； （三）有符合国家规定的广播电视技术设备； （四）有必要的基本建设资金和稳定的资金保障； （五）有必要的场所； （六）省级广播电视行政部门规定的其他条件。"},{"i":5,"n":"第五条","txt":"申请设立广播电视站，须由申请单位向当地县级以上广播电视行政部门提出申请，逐级审核同意后，报省级广播电视行政部门审批。 申请设立广播电视站，应提交以下材料： （一）申请书； （二）广播电视节目转播技术方案、覆盖范围以及自办广播业务或电视业务的主要内容； （三）人员、资金、场地、设备的相关材料； （四）省级广播电视行政部门要求提交的其它文件。"},{"i":6,"n":"第六条","txt":"县级以上各级广播电视行政部门应按照《行政许可法》规定的期限，履行受理、审核职责。申请人符合法定条件的，由省级广播电视行政部门作出准予行政许可书面决定；依法作出不予行政许可决定的，应当书面通知申请人并说明理由。"},{"i":7,"n":"第七条","txt":"广播电视站应按规定转播好中央、省级和当地的广播电视节目。条件具备的，应与当地区域性有线广播电视传输覆盖网联网。 广播电视站不得称广播电台、电视台，不得接收、传送境外电视节目，不得在转播节目中插播自办节目和广告，不得将广播电视站出租、转让、承包给其他单位或个人。"},{"i":8,"n":"第八条","txt":"广播电视站可自办广播节目，通过有线方式传输。 市辖区、大专院校和国有或国有控股特大型企业设立的广播电视站确有需要，可在公共频道中插播少量自办的本单位新闻、专题以及广告等电视节目，通过有线方式传输。 乡镇设立的广播电视站不得自办电视节目。"},{"i":9,"n":"第九条","txt":"市辖区、乡镇广播电视站原则上应当由当地广播电视行政部门实施垂直统一管理。"},{"i":10,"n":"第十条","txt":"省级广播电视行政部门须将广播电视站的审批、管理情况，于每年的6月份和12月份以书面形式报国务院广播电视行政部门备案。"},{"i":11,"n":"第十一条","txt":"省级广播电视行政部门可以根据当地实际，依照本规定制定本辖区内广播电视站的审批管理办法。"},{"i":12,"n":"第十二条","txt":"违反本规定有关条款的，由县级以上广播电视行政部门按照《广播电视管理条例》进行处罚。"},{"i":13,"n":"第十三条","txt":"本办法自2004年8月10日起施行。"}],"guangbodianshibianjijizheboyinyuanzhuchirenzigegua2497b9":[{"i":1,"n":"第一条","txt":"为规范广播电视编辑记者、播音员主持人执业资格管理，提高从业人员素质，加强广播电视队伍建设，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于广播电视编辑记者、播音员主持人资格考试、执业注册、证书发放与管理等活动。"},{"i":3,"n":"第三条","txt":"国家对广播电视编辑记者、播音员主持人实行资格认定制度。 在依法设立的广播电视节目制作、广播电视播出机构（以下简称制作、播出机构）连续从事广播电视采访编辑、播音主持工作满一年的人员，应当依照本规定通过考试和注册取得执业资格并持有执业证书。"},{"i":4,"n":"第四条","txt":"国务院广播电视行政部门负责全国广播电视编辑记者、播音员主持人资格认定的管理和监督。 省级广播电视行政部门负责实施本行政区域内广播电视编辑记者、播音员主持人资格考试、执业注册、证书发放与监督管理。"},{"i":5,"n":"第五条","txt":"广播电视编辑记者资格考试与播音员主持人资格考试（以下简称资格考试）分别举行，实行全国统一大纲、统一命题、统一组织、统一标准的制度。 资格考试原则上每年上半年举行一次。报名、考试的时间由广电总局确定，在受理报名前三个月向社会公告。"},{"i":6,"n":"第六条","txt":"广电总局负责确定考试科目、组织编写考试大纲、建立考试试题库、组织命题等工作；负责组织资格考试、确定考试合格标准，监督、检查、指导省级广播电视行政部门实施本行政区域内的考务工作。"},{"i":7,"n":"第七条","txt":"资格考试试卷从资格考试试题库中随机抽取生成。"},{"i":8,"n":"第八条","txt":"符合下列条件的人员，可以报名参加资格考试： （一）遵守宪法、法律、广播电视相关法规、规章； （二）坚持四项基本原则，拥护中国共产党的基本理论、基本路线和方针政策； （三）具有完全民事行为能力； （四）具有大学专科及以上学历（含应届毕业生）。"},{"i":9,"n":"第九条","txt":"有下列情形之一的，不能报名参加考试，已经办理报名手续的，报名无效： （一）因故意犯罪受过刑事处罚的； （二）受过党纪政纪开除处分的。"},{"i":10,"n":"第十条","txt":"报名参加考试的人员，到报名点办理报名手续。经审查合格后，领取准考证。凭准考证、身份证，在指定的时间、地点参加考试。"},{"i":11,"n":"第十一条","txt":"广电总局自考试结束之日起六十个工作日内公布考试成绩和合格标准。 参加考试的人员可以通过广电总局政府网站或指定的其他方式查询考试成绩。"},{"i":12,"n":"第十二条","txt":"考试合格的，由省级广播电视行政部门颁发《广播电视编辑记者资格考试合格证》或《广播电视播音员主持人资格考试合格证》。"},{"i":13,"n":"第十三条","txt":"考试中有违反考场纪律、扰乱考场秩序等行为的，视情节轻重，给予取消相关科目成绩、本次考试成绩、下一年度考试资格的处理。"},{"i":14,"n":"第十四条","txt":"任何行政机关或行业组织不得组织强制性的资格考试考前培训，不得指定教材或者其他助考材料。"},{"i":15,"n":"第十五条","txt":"从事广播电视采访编辑、播音主持工作，应当取得相关执业资格。 未取得相关执业资格的人员，应当在持有相关执业证书的人员指导下从事实习等辅助性工作。"},{"i":16,"n":"第十六条","txt":"具备下列条件的人员，可以申请相关执业资格注册： （一）已取得《广播电视编辑记者资格考试合格证》或《广播电视播音员主持人资格考试合格证》； （二）在制作、播出机构相应岗位实习满一年； （三）身体状况能胜任所申请执业的工作岗位要求； （四）无本规定第九条所列情形； （五）以普通话为基本用语的播音员主持人，取得与岗位要求一致的普通话水平测试等级证书。"},{"i":17,"n":"第十七条","txt":"执业资格注册，按以下程序办理： （一）由申请人所在的制作、播出机构统一向省级广播电视行政部门（以下称注册机关）提交以下材料： 1、申请人填写的《注册申请表》、相关资格考试合格证和学历证书复印件； 2、申请人所在的制作、播出机构同意聘用申请人从事广播电视编辑记者或播音主持工作的书面意见。 （二）符合条件的，由注册机关在法定期限内办理注册手续，发放《中华人民共和国广播电视编辑记者证》或《中华人民共和国播音员主持人证》。"},{"i":18,"n":"第十八条","txt":"《中华人民共和国广播电视编辑记者证》和《中华人民共和国播音员主持人证》由广电总局统一印制，由注册机关统一注册，有效期为二年。注册机关应将注册情况在一个月内报广电总局备案。 《中华人民共和国广播电视编辑记者证》和《中华人民共和国播音员主持人证》是广播电视编辑记者、播音员主持人的执业凭证，在全国范围内有效。"},{"i":19,"n":"第十九条","txt":"注册有效期届满需要延续的，申请人应当在有效期届满三十日前提出延续申请，填写《延续注册申请表》，由所在的制作、播出机构向注册机关办理延续注册手续。"},{"i":20,"n":"第二十条","txt":"注册有效期内，持证人变更工作单位并继续从事广播电视采访编辑、播音主持工作的，应当在变更工作单位后一个月内填写《变更注册申请表》，并提交执业证书，由变更后所在的制作、播出机构向所在地注册机关办理变更注册手续。 因工作变更或退休不再执业的，由原所在的制作、播出机构收回执业证书，并交原注册机关统一销毁。"},{"i":21,"n":"第二十一条","txt":"广电总局和注册机关应当向社会公布注册人员名单等信息。"},{"i":22,"n":"第二十二条","txt":"持证人应妥善保管执业证书，不得出借、出租、转让、涂改和损毁。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，注册机关不予办理注册手续；制作、播出机构应将责任人调离广播电视采访编辑或播音主持岗位： （一）出现本规定第九条所列情形的； （二）因本人过错造成重大宣传事故的； （三）违反职业纪律、违背职业道德，造成恶劣影响的； （四）品行不端、声誉较差的。 出现本条第（一）、（二）、（三）项情形的，申请人在三年内不得再次提出注册申请。"},{"i":24,"n":"第二十四条","txt":"以欺骗、贿赂等不正当手段取得的执业证书无效，注册机关应予以撤销。申请人在三年内不得再次提出注册申请。"},{"i":25,"n":"第二十五条","txt":"当事人对注册机关的有关决定持有异议的，可以自接到决定之日起六十日内向广电总局申请复议。"},{"i":26,"n":"第二十六条","txt":"广播电视编辑记者、播音员主持人在执业活动中享有以下权利： （一） 以所在的制作、播出机构的名义从事广播电视节目采访编辑或播音主持工作，制作、播出机构应当提供完成工作所必需的物质条件； （二） 人身安全、人格尊严依法不受侵犯； （三） 参加继续教育和业务培训； （四） 指导实习人员从事采访编辑、播音主持工作； （五） 依法享有的其他权利。"},{"i":27,"n":"第二十七条","txt":"广播电视编辑记者、播音员主持人在执业活动中应当履行以下义务： （一） 遵守法律、法规、规章； （二） 尊重公民、法人和其他组织的合法权益； （三） 坚持正确的舆论导向； （四） 恪守职业道德，坚持客观、真实、公正的原则； （五） 严守工作纪律，服从所在机构的管理,认真履行岗位职责； （六） 努力钻研业务，更新知识，不断提高政策理论水平和专业素养； （七） 树立良好的公众形象和健康向上的精神风貌； （八） 依法应当履行的其他义务。"},{"i":28,"n":"第二十八条","txt":"本规定实施前，在广播电视播出机构工作并取得编辑记者、播音员主持人从业资格的人员，符合广电总局规定条件的，经本人申请，可以通过审核取得本规定要求的执业资格，获得执业证书。具体办法由广电总局另行规定。"},{"i":29,"n":"第二十九条","txt":"聘请境外人员从事广播电视采访编辑、播音主持工作的，依照国家有关规定执行。"},{"i":30,"n":"第三十条","txt":"本规定自2004年8月1日起施行,广电总局《播音员主持人持证上岗规定》（广电总局令第10号）同时废止。"}],"guangbodianshijiemuchuansongyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强广播电视节目传送业务管理，规范广播电视节目传送秩序，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称广播电视节目传送业务，是指利用有线方式从事广播电视节目传输和接入服务的活动。"},{"i":3,"n":"第三条","txt":"国务院广播电视行政部门负责全国广播电视节目传送业务的管理。县级以上广播电视行政部门负责本行政区域内广播电视节目传送业务的管理。"},{"i":4,"n":"第四条","txt":"国家对广播电视节目传送业务实行许可制度。"},{"i":5,"n":"第五条","txt":"利用有线方式从事广播电视节目传送业务，须按本办法规定领取《广播电视节目传送业务经营许可证》。 利用无线、微波、卫星等其它方式从事广播电视节目传送业务，应当按照国家有关规定办理相关审批手续。"},{"i":6,"n":"第六条","txt":"下列机构可以申请《广播电视节目传送业务经营许可证》： （一）经广电总局批准设立的广播电视播出机构； （二）经广电总局批准设立的广播影视集团（总台）及所属机构； （三）拥有有线广播电视网络经营权的国有或国有控股机构。"},{"i":7,"n":"第七条","txt":"禁止外商独资、中外合作、中外合资机构从事广播电视节目传送业务。"},{"i":8,"n":"第八条","txt":"申请《广播电视节目传送业务经营许可证》，应当具备以下条件： （一）符合国家广播电视节目传送业务总体规划和业务要求； （二）具有确保广播电视节目安全传送所需的设备、技术、人员及相关管理制度； （三）资费标准符合国家有关规定； （四）有从事经营活动的场所及相应网络资源； （五）有长期提供传送服务的信誉和能力； （六）有合法的广播电视节目信号来源； （七）其它法律、行政法规规定的条件。"},{"i":9,"n":"第九条","txt":"申请《广播电视节目传送业务经营许可证》，须提交以下材料： （一）有线电视网络建设及覆盖情况、传送内容（应写明具体频道、节目名称）、传送范围、技术手段（数字传输或模拟传输）、传送方式（节目传输或接入服务）等内容的说明； （二）申办机构基本情况。申办机构为企业单位的，应提供营业执照、股东背景情况的说明，事业单位应提供事业单位法人代码证； （三）《广播电视节目传送业务经营许可证》申请表； （四）从事广播电视节目传送业务的技术方案、运营方案、管理制度； （五）广播电视节目安全传送方案； （六）广播电视节目信号来源相关材料。"},{"i":10,"n":"第十条","txt":"申请利用有线方式在省级行政区域内或跨省（市）从事广播电视节目传送业务的，应向地（市）级以上广播电视行政部门提出申请，并提交符合本办法第九条规定的申报材料，经逐级审核，报广电总局审批。符合条件的，广电总局予以颁发《广播电视节目传送业务经营许可证》。 申请利用有线方式在同一地（市）行政区域内从事广播电视节目传送业务的，应向县级以上广播电视行政部门提出申请，经逐级审核，报省级广播电视行政部门审批。符合条件的，省级广播电视行政部门予以颁发《广播电视节目传送业务经营许可证》。 在同一省（市）内两个以上地（市）级行政区域经营广播电视节目传送业务的，视为在省级行政区域内经营广播电视节目传送业务，依照本条第一款规定报广电总局审批。"},{"i":11,"n":"第十一条","txt":"负责受理的广播电视行政部门应按照行政许可法规定的期限和权限，履行受理、审核职责。申请人的申请符合法定标准的，有权作出决定的广播电视行政部门应作出准予行政许可的书面决定；依法作出不予行政许可决定的，应当书面通知申请人并说明理由。"},{"i":12,"n":"第十二条","txt":"《广播电视节目传送业务经营许可证》包含传送内容、传送范围、技术手段、传送方式等事项。 持证机构应当按照许可证载明的事项从事广播电视节目传送业务。"},{"i":13,"n":"第十三条","txt":"持证机构变更许可证事项、股东、持股比例及停止从事广播电视节目传送业务，应提前六十日报原发证机关批准。国家对停止从事传送业务有其它规定的，还应当按照有关规定做执行。 持证机构营业场所、法定代表人等重要事项发生变更的，应在三十日内书面告知原发证机关。 持证机构为广播电视播出机构、广播电视节目制作经营机构传送节目素材的，不须另行申请变更许可证事项。"},{"i":14,"n":"第十四条","txt":"从事广播电视节目传送业务的机构应当在《广播电视频道播出许可证》规定的传输覆盖范围内传送频道节目。"},{"i":15,"n":"第十五条","txt":"广播电视播出机构不得通过未获得广播电视节目传送业务许可的机构传送其节目信号。"},{"i":16,"n":"第十六条","txt":"从事广播电视节目传送业务的机构不得利用所拥有的网络或频率资源擅自开办广播电视节目，不得为非法开办的节目以及来源非法的广播电视节目信号提供传送服务，不得擅自传送境外卫星电视节目。"},{"i":17,"n":"第十七条","txt":"禁止传送含有下列内容的广播电视节目信号： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄漏国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣传淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其它内容的。"},{"i":18,"n":"第十八条","txt":"从事广播电视节目传送业务的机构不得在所传送的节目中插播其它节目、资料、图像、文字及其它信息。"},{"i":19,"n":"第十九条","txt":"从事接入服务的持证机构，在有线电视网络停止模拟电视信号播出前，应当在模拟频道中完整传送广电总局规定必须传送的广播电视节目。"},{"i":20,"n":"第二十条","txt":"从事接入服务的持证机构应当提供长期、稳定的服务。"},{"i":21,"n":"第二十一条","txt":"从事广播电视节目传送业务的机构应当向广播电视行政部门设立的监测机构提供所传送节目的完整信号，不得干扰、阻碍监测活动。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定，擅自从事广播电视节目传送业务的，由县级以上广播电视行政部门责令停止违法活动，没收违法所得，并处一万元以上三万元以下罚款。构成犯罪的，依法追究刑事责任。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定，有下列行为之一的，由县级以上广播电视行政部门责令停止违法活动，给予警告，没收违法所得，可以并处二万元以下罚款。构成犯罪的，依法追究刑事责任： （一）未完整传送广电总局规定必须传送的广播电视节目的； （二）擅自在所传送的节目中插播节目、资料、图像、文字及其它信息的； （三）未按照许可证载明事项从事传送业务的； （四）营业场所、股东及持股比例、法定代表人等重要事项发生变更，未在规定期限内书面通知原发证机关的； （五）未向广播电视行政部门设立的监测机构提供所传送节目的完整信号，或干扰、阻碍监测活动的。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，有下列行为之一的，由县级以上广播电视行政部门责令停止违法活动，给予警告，没收违法所得，可以并处二万元以下罚款；情节严重的，由原发证机关吊销许可证。构成犯罪的，依法追究刑事责任： （一）擅自开办广播电视节目的； （二）为非法开办的节目以及非法来源的广播电视节目信号提供传送服务； （三）擅自传送境外卫星电视节目的。"},{"i":25,"n":"第二十五条","txt":"本办法自2004年8月10日起施行。广电总局《经营广播电视节目传送业务审批管理暂行办法》（广发社字〔1997〕714号）和《关于广播电视节目传输管理的实施细则（试行）》（广发办字〔2001〕1497号）同时废止。"}],"guangbodianshijiemuzhizuojingyingguanliguiding":[{"i":1,"n":"第一条","txt":"为坚持广播电视节目正确导向，促进广播电视节目制作产业繁荣发展，服务社会主义物质文明和精神文明建设，根据国家有关法律、法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于设立广播电视节目制作经营机构或从事专题、专栏、综艺、动画片、广播剧、电视剧等广播电视节目的制作和节目版权的交易、代理交易等活动的行为。 专门从事广播电视广告节目制作的机构，其设立及经营活动根据《广告法》等有关法律、法规管理。"},{"i":3,"n":"第三条","txt":"国务院广播电视行政部门负责制定全国广播电视节目制作产业的发展规划、布局和结构，管理、指导、监督全国广播电视节目制作经营活动。 县级以上地方广播电视行政部门负责本行政区域内广播电视节目制作经营活动的管理工作。"},{"i":4,"n":"第四条","txt":"国家对设立广播电视节目制作经营机构或从事广播电视节目制作经营活动实行许可制度。 设立广播电视节目制作经营机构或从事广播电视节目制作经营活动应当取得《广播电视节目制作经营许可证》。"},{"i":5,"n":"第五条","txt":"国家鼓励境内社会组织、企事业机构（不含在境内设立的外商独资企业或中外合资、合作企业）设立广播电视节目制作经营机构或从事广播电视节目制作经营活动。"},{"i":6,"n":"第六条","txt":"申请《广播电视节目制作经营许可证》应当符合国家有关广播电视节目制作产业发展规划、布局和结构，并具备下列条件： （一）具有独立法人资格，有符合国家法律、法规规定的机构名称、组织机构和章程； （二）有适应业务范围需要的广播电视及相关专业人员和工作场所； （三）在申请之日前三年，其法定代表人无违法违规记录或机构无被吊销过《广播电视节目制作经营许可证》的记录； （四）法律、行政法规规定的其它条件。"},{"i":7,"n":"第七条","txt":"申请《广播电视节目制作经营许可证》，申请机构应当向审批机关同时提交以下材料： （一）申请报告； （二）广播电视节目制作经营机构章程； （三）《广播电视节目制作经营许可证》申领表； （四）主要人员材料： 1．法定代表人身份证明（复印件）及简历； 2．主要管理人员（不少于三名）的广播电视及相关专业简历、业绩或曾参加相关专业培训等材料。 （五）办公场地证明； （六）企事业单位执照或工商行政部门的企业名称核准件。"},{"i":8,"n":"第八条","txt":"在京的中央单位及其直属机构申请《广播电视节目制作经营许可证》，报广电总局审批；其它机构申请《广播电视节目制作经营许可证》，向所在地广播电视行政部门提出申请，经逐级审核后，报省级广播电视行政部门审批。 审批机关应当自收到齐备的申请材料之日起十五日内，作出许可或者不予许可的决定。对符合条件的，予以许可，颁发《广播电视节目制作经营许可证》；对不符合条件的，不予许可，书面通知申请机构并说明理由。 省级广播电视行政部门应当在作出许可或者不予许可决定之日起的一周内，将审批情况报广电总局备案。 《广播电视节目制作经营许可证》由广电总局统一印制。有效期为两年。"},{"i":9,"n":"第九条","txt":"经批准取得《广播电视节目制作经营许可证》的企业，凭许可证到工商行政管理部门办理注册登记或业务增项手续。"},{"i":10,"n":"第十条","txt":"已经取得《广播电视节目制作经营许可证》的机构需在其它省、自治区、直辖市设立具有独立法人资格的广播电视节目制作经营分支机构的，须按本规定第七条的规定，向分支机构所在地的省级广播电视行政部门另行申领《广播电视节目制作经营许可证》，并向原审批机关备案；设立非独立法人资格分支机构的，无须另行申领《广播电视节目制作经营许可证》。"},{"i":11,"n":"第十一条","txt":"依法设立的广播电台、电视台制作经营广播电视节目无需另行申领《广播电视节目制作经营许可证》。"},{"i":12,"n":"第十二条","txt":"电视剧由持有《广播电视节目制作经营许可证》的机构、地市级（含）以上电视台（含广播电视台、广播影视集团）和持有《摄制电影许可证》的电影制片机构制作，但须事先另行取得电视剧制作许可。"},{"i":13,"n":"第十三条","txt":"电视剧制作许可证分为《电视剧制作许可证（乙种）》和《电视剧制作许可证（甲种）》两种，由广电总局统一印制。 《电视剧制作许可证（乙种）》仅限于该证所标明的剧目使用，有效期限不超过一年。特殊情况下经发证机关批准后，可适当延期。 《电视剧制作许可证（甲种）》有效期限为两年，有效期届满前，对持证机构制作的所有电视剧均有效。"},{"i":14,"n":"第十四条","txt":"《电视剧制作许可证（乙种）》由省级以上广播电视行政部门核发。其中，在京的中央单位及其直属机构直接向广电总局提出申请，其它机构向所在地广播电视行政部门提出申请，经逐级审核后，报省级广播电视行政部门审批。"},{"i":15,"n":"第十五条","txt":"申领《电视剧制作许可证（乙种）》，申请机构须提交以下申请材料： （一）申请报告； （二）《电视剧制作许可证（乙种）申领登记表》； （三）广电总局题材规划立项批准文件复印件； （四）编剧授权书； （五）申请机构与制片人、导演、摄像、主要演员等主创人员和合作机构（投资机构）等签定的合同或合作意向书复印件。其中，如聘请境外主创人员参与制作的，还需提供广电总局的批准文件复印件； （六）《广播电视节目制作经营许可证》（复印件）或电视台、电影制片机构的相应资质证明； （七）持证机构制作资金落实相关材料。"},{"i":16,"n":"第十六条","txt":"省级广播电视行政部门应在核发《电视剧制作许可证（乙种）》后的一周内将核发情况报广电总局备案。"},{"i":17,"n":"第十七条","txt":"电视剧制作机构在连续两年内制作完成六部以上单本剧或三部以上连续剧（3集以上/部）的，可按程序向广电总局申请《电视剧制作许可证（甲种）》资格。"},{"i":18,"n":"第十八条","txt":"申领《电视剧制作许可证（甲种）》，申请机构须提交以下申请材料： （一）申请报告； （二）《电视剧制作许可证（甲种）》申请表； （三）最近两年申领的《电视剧制作许可证（乙种）》（复印件）； （四）最近两年持《电视剧制作许可证（乙种）》制作完成的电视剧目录及相应的《电视剧发行许可证》（复印件）。"},{"i":19,"n":"第十九条","txt":"《电视剧制作许可证（甲种）》有效期届满后，持证机构申请延期的，如符合本规定第十七条规定且无违规纪录的，准予延期；不符合上述条件的，不予延期。"},{"i":20,"n":"第二十条","txt":"境内广播电视播出机构和广播电视节目制作经营机构与境外机构合作制作广播电视节目，按有关规定向广电总局申报。"},{"i":21,"n":"第二十一条","txt":"取得《广播电视节目制作经营许可证》的机构应严格按照许可证核准的制作经营范围开展业务活动。 广播电视时政新闻及同类专题、专栏等节目只能由广播电视播出机构制作，其它已取得《广播电视节目制作经营许可证》的机构不得制作时政新闻及同类专题、专栏等广播电视节目。"},{"i":22,"n":"第二十二条","txt":"广播电视节目制作经营活动必须遵守国家法律、法规和有关政策规定。禁止制作经营载有下列内容的节目： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其它内容的。"},{"i":23,"n":"第二十三条","txt":"制作重大革命和历史题材电视剧、理论文献电视专题片等广播电视节目，须按照广电总局的有关规定执行。"},{"i":24,"n":"第二十四条","txt":"发行、播放电视剧、动画片等广播电视节目，应取得相应的发行许可。"},{"i":25,"n":"第二十五条","txt":"广播电视播出机构不得播放未取得《广播电视节目制作经营许可证》的机构制作的和未取得发行许可的电视剧、动画片。"},{"i":26,"n":"第二十六条","txt":"禁止以任何方式涂改、租借、转让、出售和伪造《广播电视节目制作经营许可证》和《电视剧制作许可证》。"},{"i":27,"n":"第二十七条","txt":"《广播电视节目制作经营许可证》和《电视剧制作许可证（甲种）》载明的制作机构名称、法定代表人、地址和章程、《电视剧制作许可证（乙种）》载明的制作机构名称、剧名、集数等发生变更，持证机构应报原发证机关履行变更审批手续；终止广播电视节目制作经营活动的，应在一周内到原发证机关办理注销手续。"},{"i":28,"n":"第二十八条","txt":"《广播电视节目制作经营许可证》和《电视剧制作许可证》的核发情况由广电总局向社会公告。"},{"i":29,"n":"第二十九条","txt":"违反本规定的，依照《广播电视管理条例》进行处罚。构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"本规定自2004年8月20日起施行。广播电影电视部《影视制作经营机构管理暂行规定》（广播电影电视部令第16号）、《电视剧制作许可证管理规定》（广播电影电视部令第17号）和广电总局《关于实行广播电视节目制作、发行行业准入制度的实施细则（试行）》（广发办字〔2001〕1476号）同时废止。"}],"guangbodianshihangyetongjiguanliguiding":[{"i":1,"n":"第一条","txt":"为加强对广播电视行业统计工作的管理，充分发挥广播电视统计的信息咨询与监督作用，提升广播电视统计服务水平，根据《中华人民共和国统计法》《中华人民共和国统计法实施条例》和国家有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于广播电视主管部门依法调查、搜集、整理、研究和提供广播电视、网络视听节目服务统计资料（包括大数据统计资料）的广播电视行业统计活动。"},{"i":3,"n":"第三条","txt":"本规定所称广播电视行业各单位，是指从事广播电视、网络视听节目服务相关业务活动的各类法人单位。"},{"i":4,"n":"第四条","txt":"广播电视行业统计工作要坚持和加强党的全面领导，增强“四个意识”，坚定“四个自信”，做到“两个维护”，切实发挥统计工作在广播电视高质量创新性发展中的重要基础性作用。 广播电视行业统计工作要依法统计，建立健全与行业发展要求相适应的统计指标体系、统计标准和统计调查制度，保障统计资料的真实性、准确性、完整性和及时性。"},{"i":5,"n":"第五条","txt":"国务院广播电视主管部门主管全国范围内的广播电视行业统计监督和管理工作，并接受国务院统计主管部门的业务指导。 县级以上地方人民政府广播电视主管部门主管本行政区域内的广播电视行业统计监督和管理工作，同时接受本级人民政府统计机构的业务指导。"},{"i":6,"n":"第六条","txt":"广播电视行业各单位负责本单位的综合统计工作。 广播电视行业各单位的年度预算中应当列有必要的统计工作经费。"},{"i":7,"n":"第七条","txt":"广播电视行业各单位应当加快推广和应用现代信息技术，建立健全统计信息系统，拓展数据采集方式和服务渠道，推进统计信息公开和数据共享利用，提高广播电视统计工作效率和服务质量。"},{"i":8,"n":"第八条","txt":"广播电视行业统计工作实行统一领导、分级负责。"},{"i":9,"n":"第九条","txt":"国务院广播电视主管部门设立综合统计机构，履行下列职责： （一）按照国家有关规定，制定广播电视行业统计工作管理办法、统计标准、统计调查制度、调查任务和调查方案，监督统计法律、行政法规、规章以及统计标准、统计调查制度的实施情况； （二）搜集、整理全国广播电视行业统计资料，组织推进全国广播电视统计调查任务，对广播电视行业的发展情况进行统计分析、预测和监督； （三）组织建立、管理全国广播电视统计信息系统（含大数据统计信息系统），建立完善全国广播电视统计信息数据库； （四）审定、管理、公布、出版、提供广播电视行业统计资料，定期发布全国广播电视行业发展统计公报； （五）组织培训中央和国家机关、省级部门所属广播电视单位的统计人员。"},{"i":10,"n":"第十条","txt":"县级以上地方人民政府广播电视主管部门履行下列职责： （一）组织、协调、指导、监督本地区的广播电视统计工作，监督统计法律、法规、规章在本地区广播电视单位的实施情况； （二）搜集、整理本地区的广播电视统计资料，完成国家广播电视统计调查制度确定的调查任务和地方统计调查任务。按规定向上级广播电视主管部门报送本地区的统计报表、统计分析报告和其他统计资料，对本地区的广播电视发展情况进行统计分析、预测和监督； （三）管理本地区的广播电视统计信息系统，完成统计数据采集、处理、传递、存储等工作，配合上级部门建立、管理地区性的广播电视统计信息数据库； （四）审定、管理、公布、出版、提供本地区的广播电视统计资料； （五）组织培训本地区广播电视单位的统计人员。"},{"i":11,"n":"第十一条","txt":"广播电视行业各单位履行下列职责： （一）组织、协调本单位和所属机构的统计工作，完成广播电视统计任务，按时报送本单位统计报表、统计分析报告和其他统计资料； （二）对本单位的业务和管理情况进行统计分析，开展统计咨询和统计监督； （三）加强统计基础工作，建立健全原始记录和统计台账，严格统计工作责任制，加强统计人员培训； （四）管理本单位的统计调查表、统计资料和数据库。"},{"i":12,"n":"第十二条","txt":"广播电视主管部门应当统筹各项行政管理职能和流程，加强内部联动、协同配合，共同推进广播电视统计工作。"},{"i":13,"n":"第十三条","txt":"广播电视主管部门应当依托大数据统计信息系统，统筹收视收听率（点击率）统计工作，对数据的采集、发布进行监督。 任何机构和个人不得干扰、破坏广播电视主管部门依法开展的收视收听率（点击率）统计工作，不得制造虚假的收视收听率（点击率）。"},{"i":14,"n":"第十四条","txt":"广播电视行业各单位应当依法加强统计力量，配备专职或者指定兼职统计人员，保持统计人员的相对稳定。统计人员应当具备完成统计任务的专业知识。"},{"i":15,"n":"第十五条","txt":"统计机构、统计人员依法独立行使统计调查权、统计报告权、统计监督权及其他法定权利。"},{"i":16,"n":"第十六条","txt":"国务院广播电视主管部门负责制定、调整、修改全国广播电视统计调查制度，报国务院统计主管部门批准后实施。 县级以上地方人民政府广播电视主管部门负责制定补充性的地方广播电视统计调查制度，报上一级广播电视主管部门和本级人民政府统计机构备案后实施。 地方广播电视主管部门自行开展的广播电视统计调查的主要内容不得与全国性广播电视统计调查内容重复。"},{"i":17,"n":"第十七条","txt":"根据广播电视行业管理工作需要可以开展广播电视专项统计调查。 广播电视专项部门统计调查项目（含大数据统计调查项目），由国务院广播电视主管部门制定并报国务院统计主管部门批准或者备案后实施。 地方性广播电视专项地方统计调查项目，由本级人民政府广播电视主管部门制定并报本级人民政府统计机构批准后实施。 专项调查能够满足需要的不做全面统计调查，一次性调查能够满足需要的不做经常性调查，专项调查的内容原则上不与全面统计调查的内容重复。"},{"i":18,"n":"第十八条","txt":"广播电视行业各单位应当认真组织本单位有关机构、人员完成国家广播电视统计调查任务和其他专项统计调查任务，并配合统计机构和统计人员开展统计检查工作。"},{"i":19,"n":"第十九条","txt":"广播电视行业各单位应当建立健全统计工作责任制，并按照“集体领导与个人分工相结合”、“谁主管、谁负责，谁经办、谁负责”的原则，完善落实防范和惩治统计造假、弄虚作假责任体系。 出现统计造假、弄虚作假行为的，所在单位的主要负责人承担第一责任，分管负责人承担主要责任，统计人员承担直接责任。"},{"i":20,"n":"第二十条","txt":"广播电视行业各单位应当建立统计数据质量控制责任制，对原始记录和原始台账进行归纳和整理，对所填报统计报表的完整性、真实性和有效性进行审查、复核，并由单位负责人审核签署盖章，在规定时限内报送广播电视主管部门。报表报送后发现有误的，应当在规定期限内予以更正。"},{"i":21,"n":"第二十一条","txt":"广播电视行业各单位负责人不得擅自修改统计人员依法搜集、整理的统计资料，不得以任何方式要求统计人员伪造、篡改统计资料，不得对依法履行职责或者拒绝、抵制统计违法行为的统计人员打击报复。"},{"i":22,"n":"第二十二条","txt":"广播电视行业各单位应当建立健全广播电视统计资料审核制度，保障统计资料的准确性和及时性。统计资料由相关职能机构分工负责，综合统计机构统一管理。 统计调查中取得的原始资料应当至少保存2年。汇总性统计资料应当至少保存10年，重要的统计资料应当永久保存。"},{"i":23,"n":"第二十三条","txt":"全国性广播电视行业统计资料由国务院广播电视主管部门审核后，向社会公布。 全国性广播电视行业统计数据以国务院广播电视主管部门公布的数据为准。 地方性广播电视行业统计资料由本级人民政府广播电视主管部门审核后，向社会公布。"},{"i":24,"n":"第二十四条","txt":"广播电视行业各单位应当依法加强对统计资料的保密管理。 任何单位和个人对在统计调查中获得的能够识别和推断单个统计调查对象身份的资料，依法负有保密责任。 统计机构和统计人员对在统计工作中知悉的国家秘密、商业秘密和个人信息，应当依法予以保密。"},{"i":25,"n":"第二十五条","txt":"广播电视行业各单位应当建立统计档案制度。统计数据文件的保管、调用、移交，应当遵守国家有关规定。"},{"i":26,"n":"第二十六条","txt":"广播电视行业各单位应当做好统计信息咨询工作，为社会公众提供服务。"},{"i":27,"n":"第二十七条","txt":"广播电视主管部门应当对广播电视行业统计工作情况进行监督，主要内容包括： （一）统计法律、法规、规章和有关制度的执行情况； （二）统计机构和统计人员的配置情况； （三）统计原始记录与台账建立管理情况； （四）统计资料的真实、准确、完整程度等； （五）统计资料的使用与公布情况； （六）其他与统计工作有关的情况。 广播电视主管部门应当支持配合国务院统计主管部门的统计督察工作，并提供必要的条件保障。"},{"i":28,"n":"第二十八条","txt":"广播电视主管部门应当定期对广播电视行业统计工作情况进行考核评定，并依据有关规定对统计机构和统计人员给予奖惩。 广播电视行业各单位应当依据本规定，建立统计工作奖惩制度。"},{"i":29,"n":"第二十九条","txt":"违反本规定的，依照《中华人民共和国统计法》《中华人民共和国统计法实施条例》等有关法律、法规进行处罚、处理。"},{"i":30,"n":"第三十条","txt":"境外组织、个人需要在中华人民共和国境内进行广播电视统计调查活动的，应当按照国家有关规定，委托境内具有涉外统计调查资格的机构进行。"},{"i":31,"n":"第三十一条","txt":"本规定自2020年5月5日起施行，2005年1月27日原国家广播电影电视总局发布、2016年5月4日原国家新闻出版广电总局修订的《广播电影电视行业统计管理办法》（国家广播电影电视总局令第47号）同时废止。"}],"guangbodianshishipindianboyewuguanlibanfa":[{"i":1,"n":"第一条","txt":"为促进广播电视视频点播业务健康发展，加强监督管理，促进社会主义精神文明建设，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称的广播电视视频点播（以下简称视频点播），是指通过广播电视技术系统以实时点播、准视频点播(轮播)、下载播放等点播形式供用户自主选择收看广播电视节目的业务活动。"},{"i":3,"n":"第三条","txt":"国家广播电影电视总局（以下简称广电总局）负责全国视频点播业务的管理，制定全国视频点播业务总体规划，确定视频点播开办机构的总量、布局。 县级以上地方广播电视行政部门负责本辖区内视频点播业务的管理。"},{"i":4,"n":"第四条","txt":"国家对视频点播业务实行许可制度。未经许可，任何机构和个人均不得开办视频点播业务。 禁止外商独资、中外合资中外合作机构申请开办视频点播业务，但符合本办法第八条第一款的除外。"},{"i":5,"n":"第五条","txt":"开办视频点播业务须取得《广播电视视频点播业务许可证》。"},{"i":6,"n":"第六条","txt":"《广播电视视频点播业务许可证》分为甲、乙两种。 持有《广播电视视频点播业务许可证(甲种)》的机构，可在许可证载明的行政区域内从事视频点播业务。 持有《广播电视视频点播业务许可证（乙种）》的机构，可在许可证载明的宾馆饭店内从事视频点播业务。"},{"i":7,"n":"第七条","txt":"下列机构可以申请《广播电视视频点播业务许可证（甲种）》： （一）经批准设立的地（市）级以上广播电台、电视台； （二）经批准设立的广播影视集团（总台）。"},{"i":8,"n":"第八条","txt":"下列机构可以申请《广播电视视频点播业务许可证（乙种）》： （一）三星级以上或相当于三星级以上的宾馆饭店； （二）具有同时为10家以上三星级或相当于三星级以上的宾馆饭店提供视频点播业务能力的机构。"},{"i":9,"n":"第九条","txt":"申请《广播电视视频点播业务许可证》必须具备以下条件： （一）符合国家视频点播业务总体规划； （二）有符合本办法规定的节目资源； （三）具备与视频点播业务开办规模相适应的场所、技术、人员等条件； （四）所使用的系统和设备符合国家和行业技术标准； （五）有健全的节目内容审查制度、播出管理制度； （六）有确定的传播范围； （七）具备与开办视频点播业务相适应的信誉和服务能力； （八）有与广播电视行政部门监控系统实现联网的方案； （九）其它法律、行政法规规定的条件。"},{"i":10,"n":"第十条","txt":"申请《广播电视视频点播业务许可证》的，须提交以下材料： （一）申请报告，内容应包括：申请许可证类别（甲种、乙种）、传播方式（实时点播、准视频点播、下载播放）、播放范围等； （二）《广播电视视频点播业务许可证》申请表； （三）从事广播电视视频点播业务的节目开办方案、技术方案、运营方案、管理制度； （四）向政府监管部门提供监控信号的监控方案； （五）主管人员简要情况介绍和设备、场所的证明资料。 申请《广播电视视频点播业务许可证（乙种）》的，还应提交营业执照和宾馆饭店星级评定的相关证明；其中，由宾馆饭店以外的机构申请《广播电视视频点播业务许可证（乙种）》的，还需要提交公司章程以及宾馆饭店同意在其宾馆饭店从事视频点播业务的书面文件。"},{"i":11,"n":"第十一条","txt":"申请《广播电视视频点播业务许可证（甲种）》的，应向当地广播电视行政部门提出申请，并提交符合第十条规定的申报材料。经逐级审核后，报广电总局审批。 广电总局对申报材料进行审核，审核合格的，组织有关专家进行论证，论证期限为三十日。广电总局根据论证结论做出决定，符合条件的，颁发《广播电视视频点播业务许可证（甲种）》；不符合条件的，书面通知申办机构并说明理由。"},{"i":12,"n":"第十二条","txt":"申请《广播电视视频点播业务许可证（乙种）》，应向当地县级以上广播电视行政部门提出申请，并提交符合第十条规定的申报材料。经逐级审核后，报省级广播电视行政部门审批。 省级广播电视行政部门对申报材料进行审核，审核合格的，申办机构可以安装视频点播设备。设备安装完毕，省级广播电视行政部门组织验收，根据验收结论做出决定，符合条件的，颁发《广播电视视频点播业务许可证（乙种）》，并在九十日内报广电总局备案；不符合条件的，书面通知申办机构并说明理由。"},{"i":13,"n":"第十三条","txt":"负责受理的广播电视行政部门应按照行政许可法规定的期限和权限，履行受理、审核职责。"},{"i":14,"n":"第十四条","txt":"《广播电视视频点播业务许可证》有效期为三年，自颁发之日起计算。有效期届满，需继续经营视频点播业务的，应于期满前六个月按本办法规定的审批程序办理续办手续。"},{"i":15,"n":"第十五条","txt":"开办机构应在领取《广播电视视频点播业务许可证》之后九十日内开播。如因特殊理由不能如期开播，应经发证机关同意，否则按终止业务处理。"},{"i":16,"n":"第十六条","txt":"持有《广播电视视频点播业务许可证》的机构需终止业务的，应提前六十日向原发证机关申报，其《广播电视视频点播业务许可证》由原发证机关予以公告注销。"},{"i":17,"n":"第十七条","txt":"《广播电视视频点播业务许可证》包含开办主体、开办范围、节目类别、传送方式等项目。 开办机构必须按照许可证载明的事项从事视频点播业务。"},{"i":18,"n":"第十八条","txt":"开办机构变更许可证登记项目、股东及持股比例的，应提前六十日报原发证机关批准。"},{"i":19,"n":"第十九条","txt":"开办机构的营业场所、法定代表人、节目总编等重要事项发生变更，应在三十日内书面告知原发证机关。"},{"i":20,"n":"第二十条","txt":"宾馆饭店不得允许未获得《广播电视视频点播业务许可证》的机构在其宾馆饭店内从事视频点播业务。 宾馆饭店同意其它机构作为开办主体在本宾馆饭店内从事视频点播业务的，应对其经营活动进行必要的监督。如发现有违反本办法规定行为的，应予以制止并立即报告当地广播电视行政部门。"},{"i":21,"n":"第二十一条","txt":"视频点播节目禁止载有下列内容： （一）反对宪法确定的基本原则的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密、危害国家安全或者损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，破坏民族团结，或者侵害民族风俗、习惯的； （五）宣扬邪教、迷信的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力或者教唆犯罪的； （八）侮辱或者诽谤他人，侵害他人合法权益的； （九）危害社会公德或者民族优秀文化传统的； （十）有法律、行政法规和国家规定禁止的其它内容的。"},{"i":22,"n":"第二十二条","txt":"用于视频点播业务的节目，应符合《著作权法》的规定。"},{"i":23,"n":"第二十三条","txt":"用于视频点播业务的节目，应以国产节目为主。"},{"i":24,"n":"第二十四条","txt":"引进用于视频点播的境外影视剧，应按有关规定报广电总局审查。"},{"i":25,"n":"第二十五条","txt":"用于视频点播的节目限于以下五类： （一）取得《电视剧发行许可证》、《电影片公映许可证》的影视剧； （二）依法设立的广播电视播出机构制作、播出的节目； （三）依法设立的广播电视节目制作经营机构制作的节目； （四）经省级以上广播电视行政部门审查批准的境外广播电视节目； （五）从合法途径取得的天气预报、股票行情等信息类节目。"},{"i":26,"n":"第二十六条","txt":"用于视频点播的新闻类或信息类节目应真实、公正。"},{"i":27,"n":"第二十七条","txt":"开办机构应配备节目审查员，健全节目审查制度，实行节目总编负责制，对其播放的节目内容进行审查。节目总编应具备必要的业务素质和相关的从业经验。"},{"i":28,"n":"第二十八条","txt":"持有《广播电视视频点播业务许可证（甲种）》开办机构的播出前端应与广电总局视频点播业务监控系统实现联网；持有《广播电视视频点播业务许可证（乙种）》开办机构的播出前端应与所在地广播电视行政部门视频点播业务监控系统实现联网。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，未经批准，擅自开办视频点播业务的，由县级以上广播电视行政部门予以取缔，可以并处一万元以上三万元以下的罚款；构成犯罪的，依法追究刑事责任。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，有下列行为之一的，由县级以上广播电视行政部门责令停止违法活动、给予警告、限期整改，可以并处三万元以下的罚款： （一）未按《广播电视视频点播业务许可证》载明的事项从事视频点播业务的； （二）未经批准，擅自变更许可证事项、股东及持股比例或者需终止开办视频点播业务的； （三）播放不符合本办法规定的广播电视节目的； （四）未按本办法第二十一条、第二十四条、第二十五条规定播放视频点播节目的； （五）违反本办法第十八条，第十九条规定，有重要事项发生变更未在规定期限内通知原发证机关的； （六）违反本办法第二十八条规定，播出前端未按规定与广播电视行政部门监控系统进行联网的。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，节目总编或节目审查员未履行应尽职责，出现三次以上违规内容的，广电总局可以对相关责任人予以警告；相关责任人三年内不得担任视频点播开办机构的节目总编或节目审查员。"},{"i":32,"n":"第三十二条","txt":"违反本办法第二十条规定，宾馆饭店允许未获得《广播电视视频点播业务许可证》的机构在其宾馆饭店内经营视频点播业务的，由县级以上广播电视行政部门予以警告，可以并处三万元以下罚款。"},{"i":33,"n":"第三十三条","txt":"本办法施行前经广播电视行政部门批准开办视频点播业务的机构，应自本办法实施之日起六个月内，按照本办法规定申换许可证。"},{"i":34,"n":"第三十四条","txt":"本办法自2004年8月10日起施行。广电总局《有线电视视频点播管理暂行办法》（广电总局令第4号）和《宾馆饭店视频点播管理暂行办法》（广电总局令第6号）同时废止。"}],"guangbodianshishebeiqicairuwangrendingguanlibanfa":[{"i":1,"n":"第一条","txt":"为保障广播电视播出与网络安全，维护广播电视用户合法权益，规范广播电视设备器材入网认定管理，根据国务院有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"国务院广播电视主管部门负责全国广播电视设备器材入网认定(以下简称入网认定)管理工作。 县级以上地方人民政府广播电视主管部门依照本办法负责本行政区域内的入网认定管理工作。"},{"i":3,"n":"第三条","txt":"国家对拟进入广播电视播出机构、广播电视传输覆盖网和监测监管网的有关设备器材实行入网认定，由国务院广播电视主管部门颁发广播电视设备器材入网认定证书（以下简称入网认定证书）。未获得入网认定证书的，不得在广播电视播出机构、广播电视传输覆盖网和监测监管网使用。"},{"i":4,"n":"第四条","txt":"下列广播电视设备器材应当进行入网认定： （一）广播电视网络安全设备器材； （二）广播电视中心节目制作与播出设备器材； （三）有线广播电视系统前端设备器材； （四）有线广播电视传输与接入设备器材； （五）无线广播电视发射与传输设备器材； （六）卫星广播电视设备器材； （七）广播电视信号条件接收、用户管理等业务集成与支撑设备器材； （八）广播电视监测监管设备器材； （九）广播电视系统专用电源等设备器材； （十）其他应当进行入网认定的设备器材。 实行入网认定的广播电视设备器材目录由国务院广播电视主管部门制定和公布。"},{"i":5,"n":"第五条","txt":"生产企业申请入网认定，应当向国务院广播电视主管部门提交下列材料： （一）入网认定申请书； （二）质量管理体系相关材料； （三）产品的技术资料，包括产品使用说明书、功能介绍、性能指标、原理框图及设备外观照片、产品的企业标准以及企业标准和相关国家标准或者行业标准区别的说明等； （四）企业法人营业执照复印件。委托代理机构申请的，还应当提供委托书和代理机构企业法人营业执照和质量管理体系相关材料复印件； （五）实行生产许可证管理的产品，生产企业应当出示生产许可证复印件； （六）实行安全认证和安全检测的产品，生产企业应当出示安全认证证书或者安全检测报告； （七）商标注册证书等有关材料复印件。 对尚未公布国家标准、行业标准的广播电视设备器材新产品入网认定时，除提交上述申请材料外，还应当提供相应的技术方案。 提交的入网认定申请书一律用中文填写。外文的文件资料，应当具有中文对照文字。"},{"i":6,"n":"第六条","txt":"申请材料不齐全或者不符合法定形式的，国务院广播电视主管部门应当在收到申请材料之日起5个工作日内一次告知申请人需要补正的全部材料。 国务院广播电视主管部门应当逐步完善广播电视设备器材入网认定电子政务服务平台。"},{"i":7,"n":"第七条","txt":"国务院广播电视主管部门委托检测机构依据相关国家标准、行业标准或者相关入网技术规范对抽样产品进行检测，1个月内出具入网抽样检测报告，按检测标准要求测试时间需超过1个月的除外。"},{"i":8,"n":"第八条","txt":"国务院广播电视主管部门应当对申请材料和入网抽样检测报告等进行全面审查，根据行政许可法的规定作出决定。 对符合条件的，颁发入网认定证书；对不符合条件的，作出不予认定决定，说明理由并书面通知申请企业。自作出不予认定决定之日起3个月后，申请企业方可重新提出入网认定申请。"},{"i":9,"n":"第九条","txt":"入网认定证书由国务院广播电视主管部门统一印制，有效期为3年。入网认定证书不得伪造、涂改、出租、出借、倒卖和转让。 有效期届满需继续获得入网认定的，应当在有效期届满前3个月，按本办法的规定重新办理。"},{"i":10,"n":"第十条","txt":"已获入网认定证书的生产企业，其产品的技术、名称、型号或者质量管理体系发生改变的，应当按本办法的规定重新办理入网认定申请；企业名称发生改变的，应当凭原入网认定证书并持企业名称变更有关材料向国务院广播电视主管部门申请办理变更手续。"},{"i":11,"n":"第十一条","txt":"国务院广播电视主管部门应当向社会公布获得入网认定证书的广播电视设备器材产品和生产企业。"},{"i":12,"n":"第十二条","txt":"生产企业可以在获得入网认定证书的广播电视设备器材外包装上标注入网认定证书编号和有效期，以及产品名称、型号、产地等符合国家有关规定的中文标识的质量标志。"},{"i":13,"n":"第十三条","txt":"生产企业应当健全完善质量管理和售后服务体系，保证广播电视设备器材产品的质量稳定、可靠，不得降低产品质量和性能。"},{"i":14,"n":"第十四条","txt":"国务院广播电视主管部门应当委托检测资质、检测能力和检测范围与入网认定检测业务相符的检测机构。受委托检测机构的检测资质、检测能力不再适合进行入网认定检测的，国务院广播电视主管部门应当取消、变更检测委托。"},{"i":15,"n":"第十五条","txt":"受委托检测机构应当严格按照标准进行检测，对检测结果负责，保证检测报告、检测数据的真实准确。受委托检测机构应当依法保守秘密。 受委托检测机构对申请入网设备器材进行检测的，不得向申请入网认定生产企业收取检测费用，检测样品一律返回申请生产企业。"},{"i":16,"n":"第十六条","txt":"省级地方人民政府广播电视主管部门应当对本行政区域内获得入网认定证书的广播电视设备器材生产企业和产品进行监督检查和抽查，向社会公布抽查结果并汇总报送国务院广播电视主管部门。"},{"i":17,"n":"第十七条","txt":"国务院广播电视主管部门将严重违反本办法的生产企业记入违规失信名单，并向社会公布。"},{"i":18,"n":"第十八条","txt":"任何单位和个人有权向广播电视主管部门投诉、举报违反本办法的行为。"},{"i":19,"n":"第十九条","txt":"广播电视播出机构、广播电视传输覆盖网和监测监管网运营单位违反本办法，擅自使用未获得入网认定证书的设备器材的，由县级以上人民政府广播电视主管部门予以警告，责令改正；对造成安全播出事故的，由广播电视主管部门或者其他有权机构对负有责任的主管人员和直接责任人员依法给予处分、处理；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"已获得入网认定证书的生产企业有下列情况之一的，由县级以上人民政府广播电视主管部门予以警告，并由国务院广播电视主管部门向社会公告。 （一）未按照入网认定标准生产产品，产品质量或者性能明显下降的； （二）质量管理体系及管理水平不能达到认定时水平的； （三）不落实售后服务的。"},{"i":21,"n":"第二十一条","txt":"已获得入网认定证书的生产企业有下列情况之一的，由县级以上人民政府广播电视主管部门予以警告，可处1万元以上3万元以下罚款，并由国务院广播电视主管部门向社会公告；构成犯罪的，依法追究刑事责任。 （一）产品质量或者性能严重下降，发生严重质量事故或者造成严重后果的； （二）产品技术、名称、型号或者质量管理体系发生改变，未按本办法的规定重新办理入网认定申请，仍使用原入网认定证书的； （三）涂改、出租、出借、倒卖或者转让入网认定证书的； （四）伪造或者盗用入网认定证书的。"},{"i":22,"n":"第二十二条","txt":"生产企业采用欺骗、贿赂等不正当手段取得入网认定证书的，由国务院广播电视主管部门撤销入网认定证书。自撤销证书之日起，3年内不受理其入网认定申请。"},{"i":23,"n":"第二十三条","txt":"检测机构出具虚假检测报告、虚假证明材料、错误数据或者不按标准进行检测造成严重影响或者损失的，由国务院广播电视主管部门予以警告，并取消对其检测任务的委托；构成犯罪的，依法追究刑事责任。对负有责任的主管人员和直接责任人员，由广播电视主管部门或者其他有权机构依法给予处分、处理。"},{"i":24,"n":"第二十四条","txt":"广播电视主管部门工作人员在入网认定中未按本办法履行职责，滥用职权、玩忽职守、徇私舞弊的，由县级以上人民政府广播电视主管部门对负有责任的主管人员和直接责任人员依法给予处分、处理；构成犯罪的，依法追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本办法自2018年8月20日起施行。国家广播电影电视总局2004年6月18日颁布的《广播电视设备器材入网认定管理办法》同时废止。"}],"youxianguangbodianshiyunyingfuwuguanlizanxingguidid16fc5":[{"i":1,"n":"第一条","txt":"为了规范有线广播电视运营服务行为，提高服务质量，维护用户合法权益，根据《广播电视管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定所称有线广播电视运营服务，是指依法设立的有线广播电视运营服务提供者，利用有线广播电视传输覆盖网向用户提供服务的活动。"},{"i":3,"n":"第三条","txt":"有线广播电视运营服务工作应当遵循用户为本、安全畅通、公平合理、公益优先的原则。 有线广播电视运营服务提供者应当按照科学审慎、安全可靠、提高效率的原则，推进有线电视与新一代信息通信技术深度融合，提供智慧化广播电视服务和数据传输服务，持续改进服务质量，使有线广播电视网络成为国家重要信息基础设施建设的战略性资源平台。"},{"i":4,"n":"第四条","txt":"有线广播电视运营服务监督管理工作应当遵循公开、公平、公正的原则，实行政府监管、行业自律、社会监督相结合的机制，促进有线广播电视运营服务提供者不断提升公共服务水平，提高用户覆盖率和服务质量。"},{"i":5,"n":"第五条","txt":"国家广播电视总局负责全国有线广播电视运营服务监督管理工作。 县级以上地方人民政府广播电视行政部门负责本行政区域内的有线广播电视运营服务监督管理工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府广播电视行政部门按照有关规定，对在有线广播电视运营服务工作中做出突出贡献的组织、个人给予奖励。"},{"i":7,"n":"第七条","txt":"有线广播电视运营服务提供者应当向社会公布其业务种类、服务范围、服务时限、资费标准，并向省、自治区、直辖市人民政府广播电视行政部门备案。 有线广播电视运营服务提供者向用户提供的业务质量指标和服务质量指标应当符合国家和行业标准、要求。"},{"i":8,"n":"第八条","txt":"有线广播电视运营服务提供者应当向社会公布所传送的基本收视频道目录。 基本收视频道中应当包括国家广播电视总局要求转播的广播电视节目和县级以上地方人民政府广播电视行政部门要求转播的经国家广播电视总局批准的本地广播电视节目。"},{"i":9,"n":"第九条","txt":"除下列情况外，有线广播电视运营服务提供者不得更改所传送的基本收视频道： （一）国家广播电视总局依法作出的决定； （二）信号源不符合传送条件或者已停止播出的； （三）与节目提供方的协议有效期满或者节目提供方承担违约责任的； （四）法律、行政法规、规章规定的其他情形。 终止传送基本收视频道的，有线广播电视运营服务提供者应当向所涉及用户公告，并采取措施保证基本收视频道数量。有前款第二项规定情形的，有线广播电视运营服务提供者应当于当日向省、自治区、直辖市人民政府广播电视行政部门报告。"},{"i":10,"n":"第十条","txt":"有线广播电视运营服务提供者停止经营某项业务时，应当至少提前十五个工作日公告或者通知有关用户，并公平合理地做好用户善后工作。"},{"i":11,"n":"第十一条","txt":"有线广播电视运营服务提供者应当以书面或者其他形式，明确与用户的权利和义务。格式合同条款应当公平合理、准确全面、简单明了，并采取适当方式提醒用户注意免除或者限制服务提供者责任的条款。"},{"i":12,"n":"第十二条","txt":"有线广播电视运营服务提供者应当根据网络规模和用户分布情况设置服务网店，合理安排服务时间，方便用户办理有关事项。 有线广播电视运营服务提供者应当按照当地人民政府的要求，向残疾人和行动不便的老年人等用户提供便捷的服务，对低保户、特困人群等用户给予资费减免等优惠。"},{"i":13,"n":"第十三条","txt":"有线广播电视运营服务提供者向用户提供的服务项目应当包括安装、业务开通、迁移、变更、暂停、恢复、终止（注销）、故障维修、缴费、咨询、投诉和公告等内容。"},{"i":14,"n":"第十四条","txt":"有线广播电视运营服务提供者应当在用户办理业务时，真实准确地向用户说明该项业务的功能、使用范围、取消方式、资费标准及缴纳办法、服务保障、客服电话等内容。"},{"i":15,"n":"第十五条","txt":"有线广播电视运营服务提供者在接到用户的安装或者业务开通申请后，对城镇地区的用户应当在两个工作日内答复，对农村或者交通不便地区的用户应当在五个工作日内答复；未予受理的，应当向用户告知原因。"},{"i":16,"n":"第十六条","txt":"有线广播电视运营服务提供者应当设立统一的客服电话，为用户提供7×24小时故障报修、咨询和投诉等服务。其中故障报修应当提供7×24小时人工服务。"},{"i":17,"n":"第十七条","txt":"有线广播电视运营服务提供者接到用户故障报修后，需要上门维修的，应当自接报后二十四小时内与用户预约上门维修时间。"},{"i":18,"n":"第十八条","txt":"城镇用户的网络和设备故障，有线广播电视运营服务提供者应当自接报之日的次日起或者用户同意的上门维修时间起二十四小时内修复，重大故障应当在四十八小时内修复；农村或者交通不便地区用户的故障，有线广播电视运营服务提供者应当自接报之日的次日起或者用户同意的上门维修时间起七十二小时内修复。"},{"i":19,"n":"第十九条","txt":"因不可抗力原因造成不能按时上门维修或者修复的，有线广播电视运营服务提供者应当及时向用户说明，修复时限从不可抗力原因消失后开始计算。"},{"i":20,"n":"第二十条","txt":"有线广播电视运营服务提供者委派的上门维修人员应当遵守预约时间，出示工作证明并佩带本单位标识，爱护用户设施。需要收取费用的，应当事先向用户说明。"},{"i":21,"n":"第二十一条","txt":"有线广播电视运营服务提供者更改、调整数字广播电视频道序号，或者因系统设备及线路计划检修、设备搬迁、工程割接、网络及软件升级等可预见的原因影响用户收看或者使用的，应当提前七十二小时向所涉及的用户公告；影响用户的时间超过二十四小时的，应当同时向所在地县级以上地方人民政府广播电视行政部门报告。 前款规定的原因消除后，有线广播电视运营服务提供者应当及时恢复服务。"},{"i":22,"n":"第二十二条","txt":"因不可抗力、重大网络故障或者突发性事件影响用户使用的，有线广播电视运营服务提供者应当向所涉及用户公告；因其他不可预见的原因影响用户使用的，可以不予公告，但应当在用户咨询时告知原因。"},{"i":23,"n":"第二十三条","txt":"有线广播电视运营服务提供者应当执行国家有关价格管理的规定，明码标价，需要调整资费标准、计费方式等重要事项时，应当向用户公告。 有线广播电视运营服务提供者应当为用户缴费和查询费用等提供便利，并为用户免费提供一年内的缴费记录查询。"},{"i":24,"n":"第二十四条","txt":"用户逾期未按照约定缴纳有线广播电视基本收视维护费的，有线广播电视运营服务提供者可以暂停或者终止相应业务服务，但应当提前二十四小时通知用户。暂停服务期间，不得终止中央电视台第一套节目信号传送服务。 用户补足应缴费用的，有线广播电视运营服务提供者应当及时恢复服务，最迟不得超过二十四小时。"},{"i":25,"n":"第二十五条","txt":"有线广播电视运营服务提供者应当建立用户投诉处理机制，形成包括受理、调查、处理、反馈、评估、报告、改进、存档等环节的完整工作流程。对用户关于服务的投诉，应当在十个工作日内答复。 有线广播电视运营服务提供者收到广播电视行政部门或者其设立的投诉处理机构转来的用户投诉后，应当在要求的期限内完成有关投诉处理事宜；不能按时完成的，应当向有关广播电视行政部门或者投诉处理机构提前说明情况。"},{"i":26,"n":"第二十六条","txt":"有线广播电视运营服务提供者如需委托其他单位向用户提供安装、故障维修、缴费等服务，应当选择有相应技术实力、服务和管理能力、在工商管理机构注册登记、无不良记录的单位，并应当签订委托协议，对受委托单位进行定期检查和评估，加强日常管理。 受委托单位因其服务行为与用户产生纠纷的，由有线广播电视运营服务提供者依法承担责任。"},{"i":27,"n":"第二十七条","txt":"有线广播电视运营服务提供者应当建立用户信息安全监管体系，如实登记用户个人信息，并依法负有保密义务。未经用户许可，不得泄露用户个人信息。"},{"i":28,"n":"第二十八条","txt":"有线广播电视运营服务提供者应当对从业人员进行服务规范方面的培训。"},{"i":29,"n":"第二十九条","txt":"有线广播电视运营服务提供者应当配合广播电视行政部门依法实施的监督检查,如实提供有关资料和情况。"},{"i":30,"n":"第三十条","txt":"有线广播电视运营服务提供者应当建立健全服务质量管理体系，按照省、自治区、直辖市以上人民政府广播电视行政部门的要求，对本单位服务质量进行自查，并向社会公布本单位服务质量状况。 有线广播电视运营服务提供者应当每年将自查情况通过省、自治区、直辖市人民政府广播电视行政部门向国家广播电视总局报告。"},{"i":31,"n":"第三十一条","txt":"为应对突发事件，有线广播电视运营服务提供者应当按照所在地人民政府的部署和要求，接受广播电视行政部门的指挥调度以及对有线网络资源的调配。"},{"i":32,"n":"第三十二条","txt":"有线广播电视运营服务提供者应当创造条件，积极整合、运营和管理有线电视系统，向其用户提供符合本规定要求的服务。"},{"i":33,"n":"第三十三条","txt":"省、自治区、直辖市以上人民政府广播电视行政部门应当制定工作规划，组织开展有线广播电视运营服务质量评价活动，及时掌握服务动态，督促有线广播电视运营服务提供者不断提高服务质量。"},{"i":34,"n":"第三十四条","txt":"省、自治区、直辖市以上人民政府广播电视行政部门应当不定期组织对本行政区域内有线广播电视运营服务提供者的服务质量进行抽查，并向社会公布抽查结果。"},{"i":35,"n":"第三十五条","txt":"县级以上人民政府广播电视行政部门应当根据实际情况建立有线广播电视运营服务投诉处理机构，积极处理和妥善解决用户投诉，并将用户投诉情况作为有线广播电视运营服务质量评价的指标和内容。"},{"i":36,"n":"第三十六条","txt":"广播电视行政部门或者投诉处理机构接到用户投诉后，应当予以记录并及时调查、处理；用户需要回复意见的，应当将处理结果告知用户。"},{"i":37,"n":"第三十七条","txt":"广播电视行政部门的工作人员在监督检查有线广播电视运营服务质量和处理用户投诉时，可以行使下列职权： （一）询问被检查的单位及有关人员，并要求提供相关资料； （二）进入被检查单位的工作场所，查询、复制有关资料和原始记录。"},{"i":38,"n":"第三十八条","txt":"广播电视行政部门的工作人员实施的监督检查工作应当由两名以上工作人员共同进行。执法人员应当出示执法证件，并对查询、复制的资料依法负有保密义务。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府广播电视行政部门可以聘请社会义务监督员，对有线广播电视运营服务提供者侵害用户权益的行为和有关部门工作人员在监督检查工作中的违法失职行为进行监督。"},{"i":40,"n":"第四十条","txt":"有线广播电视运营服务提供者违反本规定第七条、第八条、第九条、第二十七条、第二十九条、第三十条的，由县级以上人民政府广播电视行政部门责令改正，给予警告；情节严重的，并处一万元以上三万元以下的罚款。"},{"i":41,"n":"第四十一条","txt":"有线广播电视运营服务提供者违反本规定第十条、第二十一条、第二十二条的，由县级以上人民政府广播电视行政部门责令改正，给予警告；情节严重的，并处五千元以上两万元以下的罚款。"},{"i":42,"n":"第四十二条","txt":"有线广播电视运营服务提供者违反本规定第十六条、第十七条、第十八条、第二十条、第二十五条、第二十八条的，由县级以上人民政府广播电视行政部门给予警告；情节严重的，并处五千元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"广播电视行政部门、投诉处理机构的工作人员未按照本规定履行职责或者有其他滥用职权、玩忽职守、徇私舞弊行为的，依法给予处分。"},{"i":44,"n":"第四十四条","txt":"有线广播电视运营服务提供者可以根据所服务区域实际情况，制定不低于本规定要求的具体服务标准。"},{"i":45,"n":"第四十五条","txt":"本规定自2012年3月1日起施行。"}],"weichengnianrenjiemuguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范未成年人节目，保护未成年人身心健康，保障未成年人合法权益，教育引导未成年人，培育和弘扬社会主义核心价值观，根据《中华人民共和国未成年人保护法》《广播电视管理条例》等法律、行政法规，制定本规定。"},{"i":2,"n":"第二条","txt":"从事未成年人节目的制作、传播活动，适用本规定。 本规定所称未成年人节目，包括未成年人作为主要参与者或者以未成年人为主要接收对象的广播电视节目和网络视听节目。"},{"i":3,"n":"第三条","txt":"从事未成年人节目制作、传播活动，应当以培养能够担当民族复兴大任的时代新人为着眼点，以培育和弘扬社会主义核心价值观为根本任务，弘扬中华优秀传统文化、革命文化和社会主义先进文化，坚持创新发展，增强原创能力，自觉保护未成年人合法权益，尊重未成年人发展和成长规律，促进未成年人健康成长。"},{"i":4,"n":"第四条","txt":"未成年人节目管理工作应当坚持正确导向，注重保护尊重未成年人的隐私和人格尊严等合法权益，坚持教育保护并重，实行社会共治，防止未成年人节目出现商业化、成人化和过度娱乐化倾向。"},{"i":5,"n":"第五条","txt":"国务院广播电视主管部门负责全国未成年人节目的监督管理工作。 县级以上地方人民政府广播电视主管部门负责本行政区域内未成年人节目的监督管理工作。"},{"i":6,"n":"第六条","txt":"广播电视和网络视听行业组织应当结合行业特点，依法制定未成年人节目行业自律规范，加强职业道德教育，切实履行社会责任，促进业务交流，维护成员合法权益。"},{"i":7,"n":"第七条","txt":"广播电视主管部门对在培育和弘扬社会主义核心价值观、强化正面教育、贴近现实生活、创新内容形式、产生良好社会效果等方面表现突出的未成年人节目，以及在未成年人节目制作、传播活动中做出突出贡献的组织、个人，按照有关规定予以表彰、奖励。"},{"i":8,"n":"第八条","txt":"国家支持、鼓励含有下列内容的未成年人节目的制作、传播： （一）培育和弘扬社会主义核心价值观； （二）弘扬中华优秀传统文化、革命文化和社会主义先进文化； （三）引导树立正确的世界观、人生观、价值观； （四）发扬中华民族传统家庭美德，树立优良家风； （五）符合未成年人身心发展规律和特点； （六）保护未成年人合法权益和情感，体现人文关怀； （七）反映未成年人健康生活和积极向上的精神面貌； （八）普及自然和社会科学知识； （九）其他符合国家支持、鼓励政策的内容。"},{"i":9,"n":"第九条","txt":"未成年人节目不得含有下列内容： （一）渲染暴力、血腥、恐怖，教唆犯罪或者传授犯罪方法； （二）除健康、科学的性教育之外的涉性话题、画面; （三）肯定、赞许未成年人早恋； （四）诋毁、歪曲或者以不当方式表现中华优秀传统文化、革命文化、社会主义先进文化； （五）歪曲民族历史或者民族历史人物，歪曲、丑化、亵渎、否定英雄烈士事迹和精神； （六）宣扬、美化、崇拜曾经对我国发动侵略战争和实施殖民统治的国家、事件、人物； （七）宣扬邪教、迷信或者消极颓废的思想观念； （八）宣扬或者肯定不良的家庭观、婚恋观、利益观； （九）过分强调或者过度表现财富、家庭背景、社会地位； （十）介绍或者展示自杀、自残和其他易被未成年人模仿的危险行为及游戏项目等； （十一）表现吸毒、滥用麻醉药品、精神药品和其他违禁药物； （十二）表现吸烟、售烟和酗酒； （十三）表现违反社会公共道德、扰乱社会秩序等不良举止行为； （十四）"},{"i":10,"n":"第十条","txt":"不得制作、传播利用未成年人或者未成年人角色进行商业宣传的非广告类节目。 制作、传播未成年人参与的歌唱类选拔节目、真人秀节目、访谈脱口秀节目应当符合国务院广播电视主管部门的要求。"},{"i":11,"n":"第十一条","txt":"广播电视播出机构、网络视听节目服务机构、节目制作机构应当根据不同年龄段未成年人身心发展状况，制作、传播相应的未成年人节目，并采取明显图像或者声音等方式予以提示。"},{"i":12,"n":"第十二条","txt":"邀请未成年人参与节目制作，应当事先经其法定监护人同意。不得以恐吓、诱骗或者收买等方式迫使、引诱未成年人参与节目制作。 制作未成年人节目应当保障参与制作的未成年人人身和财产安全，以及充足的学习和休息时间。"},{"i":13,"n":"第十三条","txt":"未成年人节目制作过程中，不得泄露或者质问、引诱未成年人泄露个人及其近亲属的隐私信息，不得要求未成年人表达超过其判断能力的观点。 对确需报道的未成年人违法犯罪案件，不得披露犯罪案件中未成年人当事人的姓名、住所、照片、图像等个人信息，以及可能推断出未成年人当事人身份的资料。对于不可避免含有上述内容的画面和声音，应当采取技术处理，达到不可识别的标准。"},{"i":14,"n":"第十四条","txt":"邀请未成年人参与节目制作，其服饰、表演应当符合未成年人年龄特征和时代特点，不得诱导未成年人谈论名利、情爱等话题。 未成年人节目不得宣扬童星效应或者包装、炒作明星子女。"},{"i":15,"n":"第十五条","txt":"未成年人节目应当严格控制设置竞赛排名，不得设置过高物质奖励，不得诱导未成年人现场拉票或者询问未成年人失败退出的感受。 情感故事类、矛盾调解类等节目应当尊重和保护未成年人情感，不得就家庭矛盾纠纷采访未成年人，不得要求未成年人参与节目录制和现场调解，避免未成年人亲眼目睹家庭矛盾冲突和情感纠纷。 未成年人节目不得以任何方式对未成年人进行品行、道德方面的测试，放大不良现象和非理性情绪。"},{"i":16,"n":"第十六条","txt":"未成年人节目的主持人应当依法取得职业资格，言行妆容不得引起未成年人心理不适，并在节目中切实履行引导把控职责。 未成年人节目设置嘉宾，应当按照国务院广播电视主管部门的规定，将道德品行作为首要标准，严格遴选、加强培训，不得选用因丑闻劣迹、违法犯罪等行为造成不良社会影响的人员，并提高基层群众作为节目嘉宾的比重。"},{"i":17,"n":"第十七条","txt":"国产原创未成年人节目应当积极体现中华文化元素，使用外国的人名、地名、服装、形象、背景等应当符合剧情需要。 未成年人节目中的用语用字应当符合有关通用语言文字的法律规定。"},{"i":18,"n":"第十八条","txt":"未成年人节目前后播出广告或者播出过程中插播广告，应当遵守以下规定： （一）未成年人专门频率、频道、专区、链接、页面不得播出医疗、药品、保健食品、医疗器械、化妆品、酒类、美容广告、不利于未成年人身心健康的网络游戏广告，以及其他不适宜未成年人观看的广告，其他未成年人节目前后不得播出上述广告； （二）针对不满十四周岁的未成年人的商品或者服务的广告，不得含有劝诱其要求家长购买广告商品或者服务、可能引发其模仿不安全行为的内容； （三）不得利用不满十周岁的未成年人作为广告代言人； （四）未成年人广播电视节目每小时播放广告不得超过12分钟； （五）未成年人网络视听节目播出或者暂停播出过程中，不得插播、展示广告，内容切换过程中的广告时长不得超过30秒。"},{"i":19,"n":"第十九条","txt":"未成年人专门频率、频道应当通过自制、外购、节目交流等多种方式，提高制作、播出未成年人节目的能力，提升节目质量和频率、频道专业化水平，满足未成年人收听收看需求。 网络视听节目服务机构应当以显著方式在显著位置对所传播的未成年人节目建立专区，专门播放适宜未成年人收听收看的节目。 未成年人专门频率频道、网络专区不得播出未成年人不宜收听收看的节目。"},{"i":20,"n":"第二十条","txt":"广播电视播出机构、网络视听节目服务机构对所播出的录播或者用户上传的未成年人节目，应当按照有关规定履行播前审查义务；对直播节目，应当采取直播延时、备用节目替换等必要的技术手段，确保所播出的未成年人节目中不得含有本规定第九条第一款禁止内容。"},{"i":21,"n":"第二十一条","txt":"广播电视播出机构、网络视听节目服务机构应当建立未成年人保护专员制度，安排具有未成年人保护工作经验或者教育背景的人员专门负责未成年人节目、广告的播前审查，并对不适合未成年人收听收看的节目、广告提出调整播出时段或者暂缓播出的建议，暂缓播出的建议由有关节目审查部门组织专家论证后实施。"},{"i":22,"n":"第二十二条","txt":"广播电视播出机构、网络视听节目服务机构在未成年人节目播出过程中，应当至少每隔30分钟在显著位置发送易于辨认的休息提示信息。"},{"i":23,"n":"第二十三条","txt":"广播电视播出机构在法定节假日和学校寒暑假每日8:00至23:00，以及法定节假日和学校寒暑假之外时间每日15:00至22:00，播出的节目应当适宜所有人群收听收看。 未成年人专门频率频道全天播出未成年人节目的比例应当符合国务院广播电视主管部门的要求，在每日17:00-22:00之间应当播出国产动画片或者其他未成年人节目，不得播出影视剧以及引进节目，确需在这一时段播出优秀未成年人影视剧的，应当符合国务院广播电视主管部门的要求。 未成年人专门频率频道、网络专区每日播出或者可供点播的国产动画片和引进动画片的比例应当符合国务院广播电视主管部门的规定。"},{"i":24,"n":"第二十四条","txt":"网络用户上传含有未成年人形象、信息的节目且未经未成年人法定监护人同意的，未成年人的法定监护人有权通知网络视听节目服务机构采取删除、屏蔽、断开链接等必要措施。网络视听节目服务机构接到通知并确认其身份后应当及时采取相关措施。"},{"i":25,"n":"第二十五条","txt":"网络视听节目服务机构应当对网络用户上传的未成年人节目建立公众监督举报制度。在接到公众书面举报后经审查发现节目含有本规定第九条第一款禁止内容或者属于第十条第一款禁止节目类型的，网络视听节目服务机构应当及时采取删除、屏蔽、断开链接等必要措施。"},{"i":26,"n":"第二十六条","txt":"广播电视播出机构、网络视听节目服务机构应当建立由未成年人保护专家、家长代表、教师代表等组成的未成年人节目评估委员会，定期对未成年人节目、广告进行播前、播中、播后评估。必要时，可以邀请未成年人参加评估。评估意见应当作为节目继续播出或者调整的重要依据，有关节目审查部门应当对是否采纳评估意见作出书面说明。"},{"i":27,"n":"第二十七条","txt":"广播电视播出机构、网络视听节目服务机构应当建立未成年人节目社会评价制度，并以适当方式及时公布所评价节目的改进情况。"},{"i":28,"n":"第二十八条","txt":"广播电视播出机构、网络视听节目服务机构应当就未成年人保护情况每年度向当地人民政府广播电视主管部门提交书面年度报告。 评估委员会工作情况、未成年人保护专员履职情况和社会评价情况应当作为年度报告的重要内容。"},{"i":29,"n":"第二十九条","txt":"广播电视主管部门应当建立健全未成年人节目监听监看制度，运用日常监听监看、专项检查、实地抽查等方式，加强对未成年人节目的监督管理。"},{"i":30,"n":"第三十条","txt":"广播电视主管部门应当建立未成年人节目违法行为警示记录系统。 对列入警示记录的严重违反本规定的广播电视节目制作经营机构、广播电视播出机构、网络视听节目服务机构，广播电视主管部门应当及时向社会公布，并告知其有陈述、申辩的权利。"},{"i":31,"n":"第三十一条","txt":"广播电视主管部门应当会同有关部门建立健全违规失信联合惩戒机制，对严重违反本规定的广播电视节目制作经营机构、广播电视播出机构、网络视听节目服务机构及其主要责任人开展联合惩戒。"},{"i":32,"n":"第三十二条","txt":"广播电视主管部门应当设立未成年人节目违法行为举报制度，公布举报电话、邮箱等联系方式。 任何单位或者个人有权举报违反本规定的未成年人节目。广播电视主管部门接到举报，应当记录并及时依法调查、处理；对不属于本部门职责范围的，应当及时移送有关部门。"},{"i":33,"n":"第三十三条","txt":"全国性广播电视、网络视听行业组织应当依据本规定，制定未成年人节目内容审核具体行业标准，加强从业人员培训，并就培训情况向国务院广播电视主管部门提交书面年度报告。"},{"i":34,"n":"第三十四条","txt":"违反本规定，制作、传播含有本规定第九条第一款禁止内容的未成年人节目的，或者在以科普、教育、警示为目的制作的节目中，包含本规定第九条第一款禁止内容但未设置明确提醒、进行技术处理的，或者制作、传播本规定第十条禁止的未成年人节目类型的，依照《广播电视管理条例》第四十九条的规定予以处罚。"},{"i":35,"n":"第三十五条","txt":"违反本规定，播放、播出广告的时间超过规定或者播出国产动画片和引进动画片的比例不符合国务院广播电视主管部门规定的，依照《广播电视管理条例》第五十条的规定予以处罚。"},{"i":36,"n":"第三十六条","txt":"违反本规定第十一条至第十七条、第十九条至第二十二条、第二十三条第一款和第二款、第二十四条至第二十八条的规定，由县级以上人民政府广播电视主管部门责令限期改正，给予警告，可以并处三万元以下的罚款。 违反第十八条第一项至第三项的规定，由有关部门依法予以处罚。"},{"i":37,"n":"第三十七条","txt":"广播电视节目制作经营机构、广播电视播出机构、网络视听节目服务机构违反本规定，其主管部门或者有权处理单位，应当依法对负有责任的主管人员或者直接责任人员给予处分、处理；造成严重社会影响的，广播电视主管部门可以向被处罚单位的主管部门或者有权处理单位通报情况，提出对负有责任的主管人员或者直接责任人员的处分、处理建议，并可函询后续处分、处理结果。"},{"i":38,"n":"第三十八条","txt":"广播电视主管部门工作人员滥用职权、玩忽职守、徇私舞弊或者未依照本规定履行职责的，对负有责任的主管人员和直接责任人员依法给予处分。"},{"i":39,"n":"第三十九条","txt":"本规定所称网络视听节目服务机构，是指互联网视听节目服务机构和专网及定向传播视听节目服务机构。 本规定所称学校寒暑假是指广播电视播出机构所在地、网络视听节目服务机构注册地教育行政部门规定的时间段。"},{"i":40,"n":"第四十条","txt":"未构成本规定所称未成年人节目，但节目中含有未成年人形象、信息等内容，有关内容规范和法律责任参照本规定执行。"},{"i":41,"n":"第四十一条","txt":"本规定自2019年4月30日起施行。"}],"dianshijuneirongguanliguiding":[{"i":1,"n":"第一条","txt":"为了规范电视剧内容管理工作，繁荣电视剧创作，促进电视剧产业的健康发展，根据《广播电视管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"从事电视剧内容的制作、发行、播出活动，适用本规定。"},{"i":3,"n":"第三条","txt":"本规定所称电视剧是指： （一）用于境内电视台播出或者境内外发行的电视剧（含电视动画片），包括国产电视剧（以下简称国产剧）和与境外机构联合制作的电视剧（以下简称合拍剧）； （二）用于境内电视台播出的境外引进电视剧（含电视动画片、电影故事片，以下简称引进剧）。"},{"i":4,"n":"第四条","txt":"电视剧内容的制作、播出应当坚持为人民服务、为社会主义服务的方向和百花齐放、百家争鸣的方针，坚持贴近实际、贴近生活、贴近群众，坚持社会效益第一、社会效益与经济效益相结合的原则，确保正确的文艺导向。"},{"i":5,"n":"第五条","txt":"电视剧不得载有下列内容： （一）违反宪法确定的基本原则，煽动抗拒或者破坏宪法、法律、行政法规和规章实施的； （二）危害国家统一、主权和领土完整的； （三）泄露国家秘密，危害国家安全，损害国家荣誉和利益的； （四）煽动民族仇恨、民族歧视，侵害民族风俗习惯，伤害民族感情，破坏民族团结的； （五）违背国家宗教政策，宣扬宗教极端主义和邪教、迷信，歧视、侮辱宗教信仰的； （六）扰乱社会秩序，破坏社会稳定的； （七）宣扬淫秽、赌博、暴力、恐怖、吸毒，教唆犯罪或者传授犯罪方法的； （八）侮辱、诽谤他人的； （九）危害社会公德或者民族优秀文化传统的； （十）侵害未成年人合法权益或者有害未成年人身心健康的； （十一）法律、行政法规和规章禁止的其他内容。 国务院广播影视行政部门依据前款规定，制定电视剧内容管理的具体标准。"},{"i":6,"n":"第六条","txt":"国务院广播影视行政部门负责全国的电视剧内容管理和监督工作。 省、自治区、直辖市人民政府广播影视行政部门负责本行政区域内的电视剧内容管理和监督工作。"},{"i":7,"n":"第七条","txt":"国务院广播影视行政部门和省、自治区、直辖市人民政府广播影视行政部门应当积极建立和完善电视剧审批管理的电子办公系统，推行电子政务。"},{"i":8,"n":"第八条","txt":"国产剧、合拍剧的拍摄制作实行备案公示制度。"},{"i":9,"n":"第九条","txt":"国务院广播影视行政部门负责全国拍摄制作电视剧的公示。 省、自治区、直辖市人民政府广播影视行政部门负责受理本行政区域内制作机构拍摄制作电视剧的备案，经审核报请国务院广播影视行政部门公示。 按照有关规定向国务院广播影视行政部门直接备案的制作机构（以下简称直接备案制作机构），在将其拍摄制作的电视剧备案前，应当经其上级业务主管部门同意。"},{"i":10,"n":"第十条","txt":"符合下列条件之一的制作机构，可以申请电视剧拍摄制作备案公示： （一）持有《电视剧制作许可证（甲种）》； （二）持有《广播电视节目制作经营许可证》； （三）设区的市级以上电视台（含广播电视台、广播影视集团）； （四）持有《摄制电影许可证》； （五）其他具备申领《电视剧制作许可证（乙种）》资质的制作机构。"},{"i":11,"n":"第十一条","txt":"省、自治区、直辖市人民政府广播影视行政部门、直接备案制作机构向国务院广播影视行政部门申请电视剧拍摄制作备案公示，应当提交下列材料： （一）《电视剧拍摄制作备案公示表》或者《重大革命和重大历史题材电视剧立项申报表》，并加盖对应的公章； （二）如实准确表述剧目主题思想、主要人物、时代背景、故事情节等内容的不少于1500字的简介； （三）重大题材或者涉及政治、军事、外交、国家安全、统战、民族、宗教、司法、公安等敏感内容的（以下简称特殊题材），应当出具省、自治区、直辖市以上人民政府有关主管部门或者有关方面的书面意见。"},{"i":12,"n":"第十二条","txt":"国务院广播影视行政部门对申请备案公示的材料进行审核，在规定受理日期后二十日内，通过国务院广播影视行政部门政府网站予以公示。公示内容包括：剧名、制作机构、集数和内容提要等。 电视剧公示打印文本可以作为办理相关手续的证明。"},{"i":13,"n":"第十三条","txt":"国务院广播影视行政部门对申请备案公示的电视剧内容违反本规定的，不予公示。"},{"i":14,"n":"第十四条","txt":"制作机构应当按照公示的内容拍摄制作电视剧。 制作机构变更已公示电视剧主要人物、主要情节的，应当依照本规定重新履行备案公示手续；变更剧名、集数、制作机构的，应当经省、自治区、直辖市人民政府广播影视行政部门或者其上级业务主管部门同意后，向国务院广播影视行政部门申请办理相关变更手续。"},{"i":15,"n":"第十五条","txt":"国产剧、合拍剧、引进剧实行内容审查和发行许可制度。未取得发行许可的电视剧，不得发行、播出和评奖。"},{"i":16,"n":"第十六条","txt":"国务院广播影视行政部门设立电视剧审查委员会和电视剧复审委员会。 省、自治区、直辖市人民政府广播影视行政部门设立电视剧审查机构。"},{"i":17,"n":"第十七条","txt":"履行电视剧审查职责的广播影视行政部门，应当建立健全审查制度，规范审查程序，落实审查责任；聘请有较高学术水平、良好职业道德的专家对申请审查的电视剧履行审查职责。"},{"i":18,"n":"第十八条","txt":"审查人员应当按照有关规定履行职责，客观公正地提出审查意见。审查人员与送审方存在近亲属等关系、可能影响公正审查，或者参与送审剧目创作的，应当申请回避。"},{"i":19,"n":"第十九条","txt":"国务院广播影视行政部门电视剧审查委员会的职责是： （一）审查直接备案制作机构制作的电视剧； （二）审查合拍剧剧本（或者分集梗概）和完成片； （三）审查引进剧； （四）审查由省、自治区、直辖市人民政府广播影视行政部门电视剧审查机构提请国务院广播影视行政部门审查的电视剧； （五）审查引起社会争议的，或者因公共利益需要国务院广播影视行政部门审查的电视剧。"},{"i":20,"n":"第二十条","txt":"国务院广播影视行政部门电视剧复审委员会，负责对送审机构不服有关电视剧审查委员会或者电视剧审查机构的审查结论而提起复审申请的电视剧进行审查。"},{"i":21,"n":"第二十一条","txt":"省、自治区、直辖市人民政府广播影视行政部门电视剧审查机构的职责是： （一）审查本行政区域内制作机构制作的国产剧； （二）初审本行政区域内制作机构与境外机构制作的合拍剧剧本（或者分集梗概）和完成片； （三）初审本行政区域内电视台等机构送审的引进剧。"},{"i":22,"n":"第二十二条","txt":"送审国产剧，应当向省、自治区、直辖市以上人民政府广播影视行政部门提出申请，并提交以下材料： （一）国务院广播影视行政部门统一印制的《国产电视剧报审表》； （二）制作机构资质的有效证明； （三）剧目公示打印文本； （四）每集不少于500字的剧情梗概； （五）图像、声音、字幕、时码等符合审查要求的完整样片一套； （六）完整的片头、片尾和歌曲的字幕表； （七）国务院广播影视行政部门同意聘用境外人员参与国产剧创作的批准文件的复印件； （八）特殊题材需提交主管部门和有关方面的书面审看意见。"},{"i":23,"n":"第二十三条","txt":"送审合拍剧、引进剧，依照国务院广播影视行政部门有关规定执行。"},{"i":24,"n":"第二十四条","txt":"省、自治区、直辖市以上人民政府广播影视行政部门在收到完备的报审材料后，应当在五十日内作出许可或者不予许可的决定；其中审查时间为三十日。许可的，发给电视剧发行许可证；不予许可的，应当通知申请人并书面说明理由。 经审查需要修改的，送审机构应当在修改后，依照本规定重新送审。 电视剧发行许可证由国务院广播影视行政部门统一印制。"},{"i":25,"n":"第二十五条","txt":"送审机构对不予许可的决定不服的，可以自收到该决定之日起六十日内向国务院广播影视行政部门提出复审申请。国务院广播影视行政部门应当在收到复审申请五十日内作出复审决定；其中复审时间为三十日。复审合格的，发给电视剧发行许可证；不合格的，应当通知送审机构并书面说明理由。"},{"i":26,"n":"第二十六条","txt":"已经向广播影视行政部门申请审查，但尚未取得电视剧发行许可证的，送审机构不得向其他广播影视行政部门转移送审。"},{"i":27,"n":"第二十七条","txt":"已经取得电视剧发行许可证的电视剧，国务院广播影视行政部门根据公共利益的需要，可以作出责令修改、停止播出或者不得发行、评奖的决定。"},{"i":28,"n":"第二十八条","txt":"已经取得电视剧发行许可证的电视剧，应当按照审查通过的内容发行和播出。 变更剧名、主要人物、主要情节和剧集长度等事项的，原送审机构应当依照本规定向原发证机关重新送审。"},{"i":29,"n":"第二十九条","txt":"国务院广播影视行政部门应当定期将全国电视剧发行许可证颁发情况向社会公告。"},{"i":30,"n":"第三十条","txt":"电视台在播出电视剧前，应当核验依法取得的电视剧发行许可证。"},{"i":31,"n":"第三十一条","txt":"电视台对其播出电视剧的内容，应当依照本规定内容审核标准，进行播前审查和重播重审；发现问题应当及时经所在地省、自治区、直辖市人民政府广播影视行政部门报请国务院广播影视行政部门处理。"},{"i":32,"n":"第三十二条","txt":"国务院广播影视行政部门可以对全国电视台播出电视剧的总量、范围、比例、时机、时段等进行宏观调控。"},{"i":33,"n":"第三十三条","txt":"电视剧播出时，应当在每集的片首标明相应的电视剧发行许可证编号，在每集的片尾标明相应的电视剧制作许可证编号。"},{"i":34,"n":"第三十四条","txt":"电视台播出电视剧时，应当依法完整播出，不得侵害相关著作权人的合法权益。"},{"i":35,"n":"第三十五条","txt":"违反本规定，擅自制作、发行、播出电视剧或者变更主要事项未重新报审的，依照《广播电视管理条例》第四十八条的规定予以处罚。"},{"i":36,"n":"第三十六条","txt":"违反本规定，制作、发行、播出的电视剧含有本规定第五条禁止内容的，依照《广播电视管理条例》第四十九条的规定予以处罚。"},{"i":37,"n":"第三十七条","txt":"违反本规定第二十六条的，省、自治区、直辖市以上人民政府广播影视行政部门对转移申请不予受理；以欺骗等不正当手段取得发行许可证的，由原发证机关撤销电视剧发行许可证；原发证机关有过错的，对直接负责的主管人员和其他直接责任人员，依法给予处分。"},{"i":38,"n":"第三十八条","txt":"广播影视行政部门工作人员违反本规定，滥用职权、玩忽职守、徇私舞弊或者未依照本规定履行职责的，依法给予处分。"},{"i":39,"n":"第三十九条","txt":"审查人员违反本规定第十八条的，由省、自治区、直辖市以上人民政府广播影视行政部门给予警告；情节严重的，不得再聘请其担任审查人员。"},{"i":40,"n":"第四十条","txt":"重大革命和重大历史题材电视剧的管理，以及合拍剧、引进剧审批和播出管理，分别依照国家有关规定执行。"},{"i":41,"n":"第四十一条","txt":"本规定自2010年7月1日起施行。2004年9月20日国家广播电影电视总局发布的《电视剧审查管理规定》（总局令第40号）、2006年11月14日国家广播电影电视总局发布的《〈电视剧审查管理规定〉补充规定》（总局令第53号）同时废止。"}]};
